        add(9, "v13 · 零损坏放行(released_corrupt=0)", "未验证", "当前是 MOCK 引擎;本次运行 %d 句,失控检测 %d 次,早停 %d 次,重试 %d 次(只证明链路,不证明真实模型)" % (n, m["runaway"], m["early_stopped"], m["retries"]))
