def _on_art_event(rec):
    """写盘线程 → 事件循环 → 该会话的 WebSocket(状态变化:generating/finalizing/ready/failed...)。"""
    s = getattr(rec, "sess", None)
    if LOOP is None or s is None:
        return
    msg = dict(rec.summary(), type="artifact", turn=rec.uid)
    LOOP.call_soon_threadsafe(lambda: s.send(msg))


def init_artifacts():
    global ART
    if ART is None:
        ART = art.ArtifactStore(WORK / "artifacts", sr=SR, on_event=_on_art_event, model={"id": (Path(MODEL).name if os.path.isdir(MODEL) else MODEL), "sha256": SEC.get("model_sha256"), "trained": TRAINED})
        log.info("产物目录: %s · 已加载 %d 条清单 · 磁盘告警线 %d MB", ART.root, len(ART.disk_manifests), ART.min_free_mb)
    return ART


# ════════════════════════════════════════════════════════════════
#  DeepSeek
