def build_report():
    hw_both = bool(POOL) and len(POOL.workers) >= 2 and all(w.synth_segs > 0 for w in POOL.workers)
    tr = read_train_progress()
    ms = list(METRICS)
    items = []

    def add(i, title, status, detail):
        items.append({"id": i, "title": title, "status": status, "detail": detail})
    if MOCK:
        add(1, "真实硬件(T4 双卡)", "未验证", "当前是 MOCK 引擎,不能证明任何真实硬件/质量结论")
    else:
        names = [r["name"] for r in GPU_ROWS.values()]
        add(1, "真实硬件(T4 双卡)", "通过" if (hw_both and len(names) >= 2) else "未运行", "推理 worker 实际合成句数: %s;GPU: %s" % ([w.synth_segs for w in POOL.workers] if POOL else [], names) +
            ";训练双卡: " + ("见训练状态 ddp_check=%s" % json.dumps(tr.get("ddp_check"), ensure_ascii=False) if tr.get("ddp_check") else "未运行"))
    short = [m for m in ms if (m.get("chars") or 0) < 40]
    long_ = [m for m in ms if (m.get("chars") or 0) >= 200]
    bad = [m for m in ms if m.get("underruns") or m.get("rebuffers") or m.get("gaps") or m.get("dups") or m.get("foreign") or m.get("integrity_fail")]
    if not ms:
        add(2, "播放连续性(underrun=0, rebuffer=0)", "未运行", "还没有浏览器上报的播放测量。请在网页里合成短文本、长文本、连续多轮")
    elif bad:
        add(2, "播放连续性(underrun=0, rebuffer=0)", "失败", "%d/%d 轮出现欠载/重缓冲/漏块/重复块/串轮" % (len(bad), len(ms)))
    else:
        miss = [n for n, v in (("短文本", short), ("长文本(≥200字)", long_), ("连续多轮(≥3轮)", ms if len(ms) >= 3 else [])) if not v]
        add(2, "播放连续性(underrun=0, rebuffer=0)", "通过" if not miss and not MOCK else "未运行", "已测 %d 轮,全部无欠载" % len(ms) + (";尚缺: " + "、".join(miss) if miss else "") + (";MOCK 不算数" if MOCK else ""))
    stress = []
    if EVENTS["reconnect_resumed"]:
        stress.append("WebSocket 重连续传 %d 次" % EVENTS["reconnect_resumed"])
    if EVENTS["visibility"]:
        stress.append("页面切换 %d 次" % EVENTS["visibility"])
    add(3, "压力与网络测试(慢生成/抖动/切页/重连/GPU 忙)", "已部分观测" if stress else "未运行", ";".join(stress) or "尚未观测到。极端断网情况不承诺连续播放")
    cold = [m["ttfa_ms"] for m in ms if m.get("cold") and m.get("ttfa_ms")]
    warm = [m["ttfa_ms"] for m in ms if not m.get("cold") and m.get("ttfa_ms")]
    add(4, "性能报告(TTFA/RTF/chunk 间隔/水位)", "已测量" if (cold or warm) else "未运行", "冷 TTFA %s;热 TTFA %s" % (pcts(cold), pcts(warm)))
    srv_err = [t for t in TURN_LOG if t.get("errors")]
    add(5, "音频完整性(样本数/序号/END/边界/静音/削波)", ("失败" if srv_err else ("通过" if TURN_LOG and not MOCK else "未运行")), "服务端 %d 轮,其中 %d 轮有损坏句子" % (len(TURN_LOG), len(srv_err)))
    sims = [v for t in TURN_LOG for v in []]
    add(6, "克隆质量(口语/歌声,保留文本评估)", "未验证", "原始声纹 cosine 已按轮显示;%s;A/B 试听投票 %d 次;歌声克隆:不支持/未验证" % ("已有校准文件" if CAL else "未校准:不可给出人耳相似度百分比", len(EVENTS["ab_votes"])))
    wm = weights_match()
    add(7, "双卡一致性(同一权重/同一配置)", "通过" if wm else ("失败" if wm is False else "未运行"), "权重指纹一致=%s;sha256=%s;不承诺逐采样点相同,跨卡听感需人工 A/B" % (wm, SEC["model_sha256"]))
    add(8, "环境", "已记录", json.dumps(backend_summary(), ensure_ascii=False, default=str)[:600])
    v13_report_items(add)
    v14_report_items(add)
    v15_report_items(add)
    v16_report_items(add)
    v17_report_items(add)
    return {"generated": time.strftime("%F %T"), "mock": MOCK, "items": items, "turns_gateway": list(TURN_LOG)[-40:], "turns_browser": ms[-40:], "events": EVENTS, "v13": v13_state(), "v15": v15_state(), "v16": v16_state(), "v17": v17_state(),
            "per_gpu": {str(i): {"F_ms": round(W(i)["F"] * 1000, 1), "D_ms": round(W(i)["D"] * 1000, 1), "PRE_ms": round(W(i)["PRE"] * 1000), "chunk_gap_ms": pcts([g * 1000 for g in W(i)["gaps"]])}
                        for i in (range(len(POOL.workers)) if POOL else [])}}


