_EMO_RULES = [
    ("angry", re.compile(r"生气|愤怒|气死|滚|混蛋|可恶|讨厌|太过分|!{2,}|！{2,}|angry|furious")),
    ("sad", re.compile(r"难过|伤心|悲伤|遗憾|可惜|哭|失望|孤独|想念|抱歉|对不起|唉|sad|sorry|unfortunately")),
    ("comfort", re.compile(r"别担心|不要怕|没关系|会好起来|别难过|抱抱|慢慢来|放心|辛苦了|我在这|don't worry|it's okay")),
    ("happy", re.compile(r"开心|高兴|太棒|哈哈|真好|喜欢|恭喜|好消息|惊喜|耶|happy|great|wonderful|congrat")),
    ("question", re.compile(r"[?？]\s*$|吗[。.]?$|呢[。.]?$|是不是|为什么|怎么|什么|how |why |what ")),
]


def detect_emotion(t):
    """基于文本的规则情绪标签(neutral/happy/sad/question/comfort/angry)。
    ⚠ VoxCPM2 没有独立的 instruct 参数:风格只能通过「文本开头的括号指令」控制(V19_STYLE=1 才放行,默认关)。
      所以这个标签默认【不会】传给模型,只用于界面标注和(可选的)句间停顿微调;模型本身的语气变化来自文本语义与参考音频。"""
    for lab, rx in _EMO_RULES:
        if rx.search(t or ""):
            return lab
    return "neutral"


EMO_PAUSE_SCALE = {"sad": 1.25, "comfort": 1.15, "happy": 0.9, "angry": 0.9, "question": 1.0, "neutral": 1.0}


# ════════════════════════════════════════════════════════════════
#  TTS 引擎(运行在各自的 GPU 进程里)
# ════════════════════════════════════════════════════════════════
def SV_MODEL_NAME():
    try:
        from speaker_sim import SV_MODEL
        return SV_MODEL
    except Exception:  # noqa: BLE001
        return "microsoft/wavlm-base-plus-sv"


class MockEngine:
    """无 GPU 的自检引擎(VC_MOCK=1):合成正弦"语音",用来验证整条链路。"""
    name = "mock"

    def __init__(self, idx, send):
        self.idx, self.send = idx, send
        self.dtype = "mock"

    def load(self):
        time.sleep(0.5)

    def backend_info(self):
        return {"mock": True, "backend": "mock (正弦波合成, 非真实模型)", "device": "none", "model": "mock"}

    def spk_qc(self, path):
        return {"status": "not_evaluated", "reason": "Mock 引擎不产生真实声纹结论(仅用于测试)", "kind": "reference_qc", "mock": True, "suspect": False, "p10": None, "mean": None, "n_windows": 0}

    def spk_cmp(self, gen_path, ref_paths):
        return {"status": "not_evaluated", "reason": "Mock 引擎不产生真实声纹分数(仅用于测试)", "kind": "generated_vs_holdout", "mock": True, "scores": [None for _ in ref_paths], "model": "mock"}

    def set_voice(self, path, text, xvec):
        time.sleep(0.4)
        t0, first, n, ch, tp = time.time(), None, 0, [], time.time()
        for a, sr in self.stream("今天天气真好，我们一起出去走走吧。", "calib"):
            now = time.time()
            first = first or (now - t0)
            ch.append((round(now - tp, 4), len(a)))
            tp, n = now, n + len(a)
        wall = time.time() - t0
        return {"rtf": round(wall / (n / SR), 2), "ttfa": round(first, 2), "dtype": "mock", "sr": SR, "mode": "mock", "sim": 0.96, "rms": 3000.0, "ch": ch, "prompt_cached": True}

    def stream(self, text, profile, seed=None):
        """成本模型≈T4 + 2B VoxCPM2(RTF≈0.9~1.0, TTFA≈1s,均为估计,真机以诊断为准):
        预填充 PRE;每帧生成 F;每次解码一个固定开销 D。可用环境变量调参来压测调度/播放器。"""
        _seed_all(seed)
        F = float(os.environ.get("VC_MOCK_FRAME_MS", "82")) / 1000
        D = float(os.environ.get("VC_MOCK_DEC_MS", "30")) / 1000
        PRE = float(os.environ.get("VC_MOCK_PREFILL_MS", "450")) / 1000
        sched = SCHED.get(profile, SCHED["rest"])
        dur = max(0.6, len(text) * 0.2)
        f0 = 140 + (sum(map(ord, text)) % 5) * 25
        lead, tail = 0.18, 0.22
        total = lead + dur + tail
        nfr = int(total * 12.5)
        time.sleep(PRE)
        done, i, t0 = 0, 0, 0.0
        while done < nfr:
            n = min(sched[min(i, len(sched) - 1)], nfr - done)
            time.sleep(n * F + D)
            d = n / 12.5
            t = np.arange(int(SR * d)) / SR + t0
            sig = sum(np.sin(2 * np.pi * f0 * h * t) / h for h in range(1, 6))
            env = ((t > lead) & (t < lead + dur)) * (0.6 + 0.4 * np.sin(2 * np.pi * 3 * t))
            if os.environ.get("VC_MOCK_FAIL") == "nan" and "NANTRIGGER" in text:
                yield np.full(int(SR * d), np.nan, np.float32), SR
                return
            out_ = (0.25 * sig * env).astype(np.float32)
            if os.environ.get("VC_MOCK_ZERORUN") == "1" and i == 3 and len(out_) > 3000:      # Mock(v15):句内注入 1920 样本(80ms=一个码帧)数字零段,复现参考克隆里的零段簇
                out_[600:600 + 1920] = 0.0
            yield out_, SR
            done += n
            i += 1
            t0 += d
            self.last_frames = done
            if getattr(self, "capture_codes", False) and "RUNAWAYLOOP" in text and ((seed or 0) % 2 == 0 or "RUNAWAYALWAYS" in text):
                self.code_log.extend([7, 19, 233, 41, 5, 88] * max(1, n // 2))      # Mock:重复循环码(v13 检测用)
            _lg = os.environ.get("VC_MOCK_LATE_GPU", "")
            late_on = ("RUNAWAYLATE" in text and ((seed or 0) % 2 == 0 or os.environ.get("VC_MOCK_LATE_ALWAYS") == "1") and (_lg == "" or int(_lg) == self.idx))
            if getattr(self, "capture_codes", False) and "RUNAWAYLATE" in text:
                self.code_log.extend(range(1000 + done, 1000 + done + n))           # Mock(v14):内容期每帧码都不同
        if getattr(self, "capture_codes", False) and "RUNAWAYLATE" in text and late_on:        # Mock(v14):内容播完后不出 EOS,同一个码连续输出,电平 -34dB(不是低电平,TailHold 抓不到)
            for _ in range(60):
                time.sleep(12 * F + D)
                nz = np.random.default_rng(3).standard_normal(int(SR * 12 / 12.5))
                nz = np.convolve(nz, np.ones(8) / 8, mode="same")
                nz = nz / (np.sqrt(np.mean(nz ** 2)) + 1e-9) * 10 ** (-34 / 20)
                done += 12
                self.last_frames = done
                self.code_log.extend([5] * 12)
                yield nz.astype(np.float32), SR
        if os.environ.get("VC_MOCK_RUNAWAY") == "1" and "RUNAWAYTAIL" in text:      # 复刻线上故障:正常内容之后继续吐 -48dB 低电平噪声(未出 EOS)
            rng = np.random.default_rng(int(seed or 0) % 1000)
            for _ in range(6):
                nz = np.convolve(rng.standard_normal(int(SR * 12 / 12.5)), np.ones(40) / 40, mode="same")
                nz = nz / (np.sqrt(np.mean(nz ** 2)) + 1e-9) * 10 ** (-48 / 20)
                time.sleep(12 * F + D)
                done += 12
                self.last_frames = done
                yield nz.astype(np.float32), SR

    last_score = {"status": "completed", "reason": "Mock 假分数,仅用于测试链路,不代表真实质量"}

    def score(self, pcm):
        return 0.95 + (len(pcm) % 7) / 200.0

    def asr(self, path):
        return "这是一段模拟识别的参考文本"


class BaseEngine:
    """v19:与具体模型无关的引擎基类(声纹评分 / ASR / 状态上报)。TTS 引擎唯一实现 = VoxCPM2Engine。"""
    name = "base"

    def __init__(self, idx, send):
        self.idx, self.send = idx, send
        self.dtype = None
        self.ref = None
        self.prompt = None
        self._asr = None
        self.scorer_holder = None          # speaker_sim.ScorerHolder(显式状态机;永不返回 None)
        self.scorer_ref_id = None          # 当前参考声纹对应的 (路径, mtime, 大小) —— 防止串到别的语音库/样本
        self.last_score = {"status": "not_evaluated", "reason": "尚未打分"}
        self.sr = SR
        self.mode = ""
        self.order = []
        self.last_frames = 0

    def _free(self):
        import gc
        gc.collect()
        try:
            import torch
            torch.cuda.empty_cache()
        except Exception:  # noqa: BLE001
            pass

    def say(self, stage, msg):
        self.send("status", self.idx, stage, msg)
        log.info("[GPU%d] %s", self.idx, msg)

    # ───── 加载(服务启动时就加载到 GPU,绝不懒加载) ─────

    def _holder(self):
        from speaker_sim import ScorerHolder, SpkScorer
        if self.scorer_holder is None:
            self.scorer_holder = ScorerHolder(lambda: SpkScorer("cuda"), label="声纹评分模型(WavLM-SV)")
        return self.scorer_holder

    def scorer_info(self):
        return self._holder().info()

    def spk_qc(self, path):
        """【参考音频质检】疑似多人检测:2 秒窗口、1 秒步长的说话人嵌入,看各窗口与整体质心的相似度分布(启发式,阈值未校准)。
        与 spk_cmp(生成音频 vs 同库留出样本)是两件事,返回里用 kind 区分,不混用同一个\"声纹分数\"。"""
        from speaker_sim import AudioSkip, ScorerUnavailable, load_wav16k, result_status
        try:
            sc = self._holder().get()
        except ScorerUnavailable as e:
            return result_status("failed", e.reason, kind="reference_qc", scorer=e.info, suspect=False, n_windows=0, p10=None, mean=None)
        try:
            w = load_wav16k(path)
            win, hop = 32000, 16000
            if len(w) < win:
                return result_status("skipped", "音频太短(<2 秒),无法检测多人", kind="reference_qc", suspect=False, n_windows=0, p10=None, mean=None, note="音频太短,无法检测多人")
            embs = []
            for i in range(0, max(1, len(w) - win + 1), hop):
                try:
                    embs.append(sc.embed(w[i:i + win]))
                except AudioSkip:
                    continue                                              # 静音窗口不计入,也不补零
            if len(embs) < 3:
                return result_status("skipped", "有效语音窗口不足 3 个(共 %d 个),无法检测多人" % len(embs), kind="reference_qc", suspect=False, n_windows=len(embs), p10=None, mean=None,
                                     note="有效语音窗口不足,无法检测多人")
            import torch
            E = torch.stack(embs)
            c = torch.nn.functional.normalize(E.mean(0), dim=-1)
            sims = (E * c).sum(-1).cpu().numpy()
            p10 = float(np.percentile(sims, 10))
            return result_status("completed", "", kind="reference_qc", suspect=bool(p10 < 0.55), n_windows=len(embs), p10=round(p10, 3), mean=round(float(sims.mean()), 3),
                                 note="启发式阈值 0.55,未经标注数据校准", model=SV_MODEL_NAME())
        except AudioSkip as e:
            return result_status("skipped", e.reason, kind="reference_qc", suspect=False, n_windows=0, p10=None, mean=None, note=e.reason)

    def spk_cmp(self, gen_path, ref_paths):
        """【生成音频 vs 同一语音库留出样本】的说话人 cosine(原始分数,未校准)。
        返回 status: completed(至少 1 对有效)/ skipped(输入音频不合格,带原因)/ failed(评分器不可用,带最初异常)。分数永远不会被伪造。"""
        from speaker_sim import AudioSkip, ScorerUnavailable, load_wav16k, result_status
        try:
            sc = self._holder().get()
        except ScorerUnavailable as e:
            return result_status("failed", e.reason, kind="generated_vs_holdout", scorer=e.info, scores=[None for _ in ref_paths], model=SV_MODEL_NAME())
        try:
            g = sc.embed(load_wav16k(gen_path))
        except AudioSkip as e:
            return result_status("skipped", "生成音频不合格:" + e.reason, kind="generated_vs_holdout", scores=[None for _ in ref_paths], model=SV_MODEL_NAME(), scorer=self._holder().info())
        import torch
        out, skipped = [], []
        for p in ref_paths:
            try:
                r = sc.embed(load_wav16k(p))
                if r.shape != g.shape:
                    raise RuntimeError("嵌入维度不一致")
                out.append(round(float(torch.nn.functional.cosine_similarity(g, r, dim=-1)), 4))
            except AudioSkip as e:
                out.append(None)
                skipped.append({"ref": os.path.basename(str(p)), "reason": e.reason})
        done = [x for x in out if x is not None]
        st = result_status("completed" if done else "skipped", "" if done else "所有留出样本都不合格:" + "; ".join(x["reason"] for x in skipped[:2]),
                           kind="generated_vs_holdout", scores=out, skipped=skipped, model=SV_MODEL_NAME(), scorer=self._holder().info())
        return st

    def _prep_scorer(self, path):
        """为本次声音设置参考声纹。模型加载 与 参考音频读取 分开处理:参考文件有问题【不会】丢掉已加载好的模型。"""
        from speaker_sim import AudioSkip, ScorerUnavailable, load_wav16k
        try:
            if self._holder().state != "ready":
                self.say("voice", "加载声纹评分模型…")
            sc = self._holder().get()
        except ScorerUnavailable as e:
            self.last_score = {"status": "failed", "reason": e.reason}
            log.warning("[GPU%d] 声纹评分不可用(不影响合成): %s", self.idx, e.reason)
            return False
        try:
            wav = load_wav16k(path)                                  # 先读文件:缺失/损坏 → AudioSkip(skipped + 原因),不影响已加载的模型
            st = os.stat(path)
            sc.ref = None
            sc.set_ref([wav])
            self.scorer_ref_id = (str(path), int(st.st_mtime), int(st.st_size))
            self.last_score = {"status": "not_evaluated", "reason": "参考声纹已就绪,等待生成音频"}
            return True
        except AudioSkip as e:
            sc.ref, self.scorer_ref_id = None, None
            self.last_score = {"status": "skipped", "reason": "参考音频不能用于打分:" + e.reason}
        except Exception as e:  # noqa: BLE001
            sc.ref, self.scorer_ref_id = None, None
            self.last_score = {"status": "failed", "reason": "设置参考声纹失败:%s: %s" % (type(e).__name__, str(e)[:200])}
            log.warning("[GPU%d] 设置参考声纹失败(评分模型仍保留): %s", self.idx, e)
        return False

    def score(self, pcm):
        """返回 float 或 None;None 时 self.last_score 里有明确状态与原因(skipped / failed / not_evaluated),绝不伪造分数。"""
        from speaker_sim import AudioSkip, ScorerUnavailable, finite_or_none, pcm16_to_16k
        h = self.scorer_holder
        if h is None or h.state != "ready" or getattr(h.scorer, "ref", None) is None:
            if not self.last_score.get("reason"):
                self.last_score = {"status": "not_evaluated", "reason": "评分器未就绪"}
            if h is not None and h.state == "failed":
                self.last_score = {"status": "failed", "reason": h.last_error or "评分器加载失败"}
            return None
        try:
            v = finite_or_none(h.scorer.score(pcm16_to_16k(pcm, SR)))
        except AudioSkip as e:
            self.last_score = {"status": "skipped", "reason": e.reason}
            return None
        except ScorerUnavailable as e:
            self.last_score = {"status": "failed", "reason": e.reason}
            return None
        except Exception as e:  # noqa: BLE001
            self.last_score = {"status": "failed", "reason": "打分异常:%s: %s" % (type(e).__name__, str(e)[:200])}
            return None
        if v is None:
            self.last_score = {"status": "failed", "reason": "模型返回了非有限分数"}
            return None
        self.last_score = {"status": "completed", "reason": ""}
        return v

    @staticmethod
    def _to_np(a):
        if hasattr(a, "cpu"):
            return a.flatten().float().cpu().numpy()
        return np.asarray(a).reshape(-1)

    def asr(self, path):
        import soundfile as sf
        import torch
        if self._asr is None:
            from transformers import pipeline
            last = None
            for name in (ASR_MODEL, "openai/whisper-small"):
                try:
                    self.say("loading", "加载语音识别模型 %s…" % name.split("/")[-1])
                    self._asr = pipeline("automatic-speech-recognition", model=name, device=0, torch_dtype=torch.float16, chunk_length_s=30)
                    break
                except Exception as e:  # noqa: BLE001
                    last = e
                    log.warning("[GPU%d] ASR 模型 %s 加载失败: %s", self.idx, name, e)
            if self._asr is None:
                raise RuntimeError("语音识别模型加载失败: %s" % last)
        a, sr = sf.read(path, dtype="float32", always_2d=False)
        if a.ndim > 1:
            a = a.mean(axis=1)
        if sr != 16000:
            n = int(len(a) * 16000 / sr)
            a = np.interp(np.linspace(0, len(a) - 1, n), np.arange(len(a)), a).astype(np.float32)
        out = self._asr({"raw": a, "sampling_rate": 16000})
        return (out.get("text") or "").strip()


# ═══════════════════════════════════════════════════════════════════════════════
#  v18 · VoxCPM2 引擎适配器(VC_ENGINE=voxcpm2)
#  设计要点(每条都对应「首声要快」或「播放不断流/不出错」):
#   ① 声纹条件只在 set_voice 时冻结一次(build_prompt_cache),之后每句复用 → 不再每句重新编码参考音频(官方 generate() 每句都会重编码)
#   ② 流式:每个 LM 步(160ms 音频)立刻解码;首块只等 1 步;FrameCoalescer 按 SCHED 合并后送出,与网关的成本模型(dt=F·帧+D)一致
#   ③ 48k→24k:有状态 FIR 抽取器(跨块保留状态,块边界无台阶);模型采样率不是 24k 的整数倍直接拒绝
#   ④ dtype:T4(sm75)没有 bf16 张量核 → fp16 优先;试合成体检(NaN/无声/失控)不过自动换 fp32/bf16 重载
#   ⑤ 克隆模式:有可信文字 → 「参考+续写」(最像);试合成经 ASR 复核 CER 超阈值或异常 → 自动退回「纯参考」(不依赖文字,最稳)
#   ⑥ 扩散步数自适应:实测 RTF 高于目标才降步数(最低 6),优先保证不断流;所有句子用同一步数,避免句间音质不一致
#   ⑦ 开头的 "(…)" 会被 VoxCPM2 当风格指令 → sanitize_text 去掉开头括号字符
#  诚实声明:T4 上的真实 RTF / 首声 / 音质 / 稳定性【未验证:需在 Kaggle T4×2 实测】;沙箱只验证了逻辑、API 契约(对照真实 voxcpm 源码)和链路。
# ═══════════════════════════════════════════════════════════════════════════════
PROBE_TEXT = "你好，我已经准备好了，今天天气真不错，我们可以开始聊天了。"
CALIB_TEXT = "今天天气真好，我们一起出去走走吧。"


class VoxCPM2Engine(BaseEngine):
    name = "voxcpm2"

    def __init__(self, idx, send, fake=False):
        super().__init__(idx, send)
        self.fake = bool(fake)
        self.vox = None
        self.tts = None
        self.native_sr = 48000
        self.cache = None
        self.cache_mode = ""
        self.steps = int(os.environ.get("VC_VOX_STEPS", "10"))
        self.steps_min = int(os.environ.get("VC_VOX_STEPS_MIN", "6"))
        self.cfg_value = float(os.environ.get("VC_VOX_CFG", "2.0"))
        self.rtf_target = float(os.environ.get("VC_VOX_RTF_TARGET", "0.85"))
        self.autosteps = os.environ.get("VC_VOX_AUTOSTEPS", "1") == "1"
        self.cer_max = float(os.environ.get("VC_VOX_CER_MAX", "0.35"))
        self.custom_ok = False
        self.lora = False
        self.last_hifi = None
        self.probe_log = []
        self._seed_kw = False

    # ───── 加载 ─────
    def _snapshot(self):
        if os.path.isdir(VOX_MODEL):
            return VOX_MODEL
        from huggingface_hub import snapshot_download
        return snapshot_download(VOX_MODEL, ignore_patterns=["*.msgpack", "*.h5", "*.onnx", "flax_*", "tf_*", "*.ot", "*.gguf"])

    def load(self, force_dtype=None):
        import vox_audio as va
        t0 = time.time()
        if self.fake:
            from vox_fake import FakeVoxCPM
            self.vox, self.dtype, self.order = FakeVoxCPM(), "fake", ["fake"]
            self.mode = "VoxCPM2 假模型(仅链路测试)"
        else:
            import torch
            if not torch.cuda.is_available():
                raise RuntimeError("PyTorch 看不到 GPU(请在 Kaggle 右侧 Settings 里把 Accelerator 选成 GPU T4 x2)")
            major = torch.cuda.get_device_capability(0)[0]
            self.order = va.dtype_order(major, os.environ.get("VC_VOX_DTYPE", ""))
            self.dtype = force_dtype or self.order[0]
            self.say("loading", "定位 VoxCPM2 权重…")
            out = va.patched_model_dir(self._snapshot(), self.dtype, str(WORK / ("voxcpm2_" + self.dtype)))
            from voxcpm import VoxCPM
            want_opt = os.environ.get("VC_VOX_OPTIMIZE", "1") == "1"
            self.say("loading", "加载 VoxCPM2 (%s)%s…" % (self.dtype, " + torch.compile 预热(首次较慢)" if want_opt else ""))
            lora = os.environ.get("VC_VOX_LORA", "").strip()                         # v19:官方 LoRA(PVC 路线),与基座同一模型;加载失败 → 退回纯基座并如实提示
            lkw = {"lora_weights_path": lora} if lora else {}
            try:
                try:
                    self.vox = VoxCPM.from_pretrained(out, load_denoiser=False, optimize=want_opt, local_files_only=True, device="cuda", **lkw)
                except Exception as e_l:  # noqa: BLE001
                    if not lkw:
                        raise
                    log.warning("[GPU%d] LoRA 加载失败,退回纯基座 VoxCPM2: %s", self.idx, e_l)
                    self.say("loading", "LoRA 加载失败(%s),改用纯基座 VoxCPM2" % str(e_l)[:60])
                    lkw = {}
                    self._free()
                    self.vox = VoxCPM.from_pretrained(out, load_denoiser=False, optimize=want_opt, local_files_only=True, device="cuda")
                self.lora = bool(lkw)
                self.mode = "VoxCPM2 流式" + (" · torch.compile" if want_opt else "")
            except Exception as e:  # noqa: BLE001
                if not want_opt:
                    raise
                log.warning("[GPU%d] VoxCPM2 optimize=True 失败,改 optimize=False: %s", self.idx, e)
                log.warning(traceback.format_exc())
                self._free()
                self.vox = VoxCPM.from_pretrained(out, load_denoiser=False, optimize=False, local_files_only=True, device="cuda")
                self.mode = "VoxCPM2 流式(未编译)"
        self.tts = self.vox.tts_model
        self.native_sr = int(getattr(self.tts, "sample_rate", 48000))
        va.StreamDecimator.for_rates(self.native_sr, SR)                    # 非整数倍 → ValueError → 拒绝启动
        self.sr = SR
        try:
            import inspect
            self._seed_kw = "seed" in inspect.signature(self.tts._generate_with_prompt_cache).parameters      # PyPI 2.0.3 没有 seed 参数;git 主干有(且 seed=None 会随机)
        except Exception:  # noqa: BLE001
            self._seed_kw = False
        self.say("loaded", "模型就绪 · %s · %s · 原生 %dHz→%dHz · %.0fs" % (self.mode, self.dtype, self.native_sr, SR, time.time() - t0))

    def _free(self):
        self.vox = None
        self.tts = None
        self.cache = None
        if not self.fake:
            super()._free()

    def backend_info(self):
        info = {"mock": self.fake, "engine": "voxcpm2", "dtype": self.dtype, "mode": self.mode, "model": VOX_MODEL, "streaming": True, "custom_two_phase": False,
                "backend": "VoxCPM2(2B · %dHz→%dHz 抽取 · 冻结声纹缓存 · 流式)" % (self.native_sr, SR) if not self.fake else "VoxCPM2 假模型(非真实模型)",
                "native_sr": self.native_sr, "clone_mode": self.cache_mode, "steps": self.steps, "cfg": self.cfg_value, "prompt_cached": self.cache is not None,
                "device": "none" if self.fake else None}
        if self.fake:
            return info
        import importlib.metadata as md
        import torch
        info["device"] = torch.cuda.get_device_name(0)
        for pk in ("torch", "transformers", "voxcpm", "accelerate"):
            try:
                info["v_" + pk] = md.version(pk)
            except Exception:  # noqa: BLE001
                pass
        try:
            tot, n = 0.0, 0
            for p_ in self.tts.parameters():
                tot += float(torch.sum(torch.abs(p_.detach()), dtype=torch.float32))
                n += p_.numel()
            info["weights_params"], info["weights_abs_sum"] = n, round(tot, 2)        # 权重指纹:两张卡必须一致
        except Exception as e:  # noqa: BLE001
            info["weights_fp_error"] = str(e)[:100]
        return info

    # ───── 假引擎下的打分/识别(无 torch):与 MockEngine 相同的诚实占位 ─────
    def spk_qc(self, path):
        return MockEngine.spk_qc(self, path) if self.fake else super().spk_qc(path)

    def spk_cmp(self, gen_path, ref_paths):
        return MockEngine.spk_cmp(self, gen_path, ref_paths) if self.fake else super().spk_cmp(gen_path, ref_paths)

    def score(self, pcm):
        return MockEngine.score(self, pcm) if self.fake else super().score(pcm)

    def asr(self, path):
        return MockEngine.asr(self, path) if self.fake else super().asr(path)

    def _prep_scorer(self, path):
        if not self.fake:
            return super()._prep_scorer(path)

    # ───── 声纹冻结 ─────
    def _ref_seconds(self, path):
        try:
            import soundfile as sf
            i = sf.info(path)
            return float(i.frames) / float(i.samplerate)
        except Exception:  # noqa: BLE001
            return 0.0

    def _clone_modes(self, path, text, xvec):
        pref = os.environ.get("VC_VOX_CLONE_MODE", "auto").strip().lower()
        can_cont = bool((text or "").strip()) and not xvec and 0 < self._ref_seconds(path) <= float(os.environ.get("VC_VOX_PROMPT_MAX_S", "20"))
        if pref == "reference" or not can_cont:
            return ["reference"]
        return ["ref_continuation", "reference"]

    def _ref_for_reference_mode(self, path):
        """纯参考模式不需要文字 → 过长的参考在最安静处截断(默认 ≤15s;更长的参考只会拖慢首句 prefill)。续写模式不裁(文字对不上)。"""
        import vox_audio as va
        mx = float(os.environ.get("VC_VOX_REF_MAX_S", "15"))
        try:
            import hashlib
            import soundfile as sf
            a, sr = sf.read(path, dtype="float32", always_2d=False)
            if a.ndim > 1:
                a = a.mean(axis=1)
            if len(a) <= mx * sr:
                return path
            b = va.trim_at_quiet(a, sr, mx)
            h = hashlib.sha1((path + str(os.path.getmtime(path)) + str(mx)).encode()).hexdigest()[:10]
            WORK.mkdir(parents=True, exist_ok=True)
            out = str(WORK / ("vox_ref_%s.wav" % h))
            sf.write(out, b, sr, subtype="PCM_16")
            log.info("[GPU%d] 参考音频 %.1fs → 在安静处截为 %.1fs(纯参考模式)", self.idx, len(a) / sr, len(b) / sr)
            return out
        except Exception as e:  # noqa: BLE001
            log.warning("[GPU%d] 参考裁剪失败,使用原文件: %s", self.idx, e)
            return path

    def _build_cache(self, mode, path, text):
        if mode == "ref_continuation":
            self.cache = self.tts.build_prompt_cache(prompt_text=text.strip(), prompt_wav_path=path, reference_wav_path=path)
        else:
            self.cache = self.tts.build_prompt_cache(reference_wav_path=self._ref_for_reference_mode(path))
        self.cache_mode = mode

    def _make_prompt(self, path, text, xvec):
        self.ref = (path, text, bool(xvec))
        self.prompt = None

    # ───── 试合成(体检 + 可选 ASR 复核) ─────
    def _probe(self, text, check_asr=True):
        import vox_audio as va
        t0, first, parts, ch, tp = time.time(), None, [], [], time.time()
        self.last_frames = 0
        for a, sr in self.stream(text, "first"):
            now = time.time()
            first = first if first is not None else now - t0
            ch.append((round(now - tp, 4), len(a)))
            tp = now
            parts.append(np.asarray(a, np.float32))
        wall = time.time() - t0
        x = np.concatenate(parts) if parts else np.zeros(0, np.float32)
        ok, why = va.check_probe(x, text, SR)
        cer = None
        if ok and check_asr and not self.fake and os.environ.get("VC_VOX_PROBE_ASR", "1") == "1" and self.cache_mode == "ref_continuation":
            try:
                import tempfile
                import soundfile as sf
                with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as tf:
                    sf.write(tf.name, x, SR, subtype="PCM_16")
                hyp = self.asr(tf.name)
                os.unlink(tf.name)
                cer = va.cer(text, hyp)
                if cer > self.cer_max:
                    ok, why = False, "试合成经 ASR 复核 CER=%.2f > %.2f(续写模式疑似文字对不上/吞字),识别为「%s」" % (cer, self.cer_max, hyp[:40])
            except Exception as e:  # noqa: BLE001
                log.warning("[GPU%d] 试合成 ASR 复核失败(忽略,不阻塞): %s", self.idx, e)
        return {"x": x, "ok": ok, "why": why, "first": first or wall, "wall": wall, "dur": len(x) / SR, "ch": ch, "cer": cer}

    def set_voice(self, path, text, xvec):
        import vox_audio as va
        self._make_prompt(path, text, xvec)
        modes = self._clone_modes(path, text, xvec)
        chosen, res, bad = None, None, None
        self.probe_log = []
        for attempt in range(3):
            for mode in modes:
                self.say("voice", "冻结声纹(%s,%s)并试合成…" % (mode, self.dtype))
                try:
                    self._build_cache(mode, path, text)
                    res = self._probe(PROBE_TEXT)
                except Exception as e:  # noqa: BLE001
                    log.warning("[GPU%d] 模式 %s 试合成异常: %s", self.idx, mode, e)
                    log.warning(traceback.format_exc())
                    res = {"ok": False, "why": "%s: %s" % (type(e).__name__, str(e)[:120]), "x": np.zeros(0, np.float32), "first": 0.0, "wall": 0.0, "dur": 0.0, "ch": [], "cer": None}
                self.probe_log.append({"dtype": self.dtype, "mode": mode, "ok": res["ok"], "why": res["why"], "cer": res["cer"]})
                if res["ok"]:
                    chosen = mode
                    break
                bad = "%s/%s: %s" % (self.dtype, mode, res["why"])
                log.warning("[GPU%d] 试合成未通过(%s)", self.idx, bad)
            if chosen:
                break
            alt = [d for d in self.order if d != self.dtype]
            if attempt < 2 and alt and not self.fake:
                self.say("loading", "%s 精度试合成异常,改用 %s 重新加载…" % (self.dtype, alt[0]))
                self._free()
                self.load(force_dtype=alt[0])
                self._make_prompt(path, text, xvec)
        if not chosen:
            raise RuntimeError(bad or "VoxCPM2 试合成失败")
        self.cache_mode = chosen
        x = res["x"]
        pcm = (np.clip(x, -1, 1) * 32767).astype(np.int16)
        info = {"rtf": round(res["wall"] / max(res["dur"], 1e-3), 2), "ttfa": round(res["first"], 2), "dtype": self.dtype, "mode": "%s · %s" % (self.mode, chosen), "sr": SR,
                "rms": round(speech_rms(pcm), 1), "sim": None, "prompt_cached": True, "clone_mode": chosen, "steps": self.steps, "probe": self.probe_log[-3:], "cer": res["cer"]}
        info["lufs"], info["lufs_note"] = va.measure_lufs(x, SR)                          # v19:BS.1770 集成响度(pyloudnorm);不可用就是 None + 原因,不用 RMS 冒充
        info["lora"] = bool(self.lora)
        self._prep_scorer(path)
        try:
            s = self.score(pcm)
            info["sim"] = None if s is None else round(s, 4)
        except Exception as e:  # noqa: BLE001
            log.warning("[GPU%d] 试合成打分失败: %s", self.idx, e)
        # 第二次试合成(图/缓存已热)才是真实速度;RTF 过高 → 降扩散步数(最低 steps_min)直到 ≤ 目标,优先保证不断流
        import vox_audio as va
        for _ in range(4):
            try:
                c = self._probe(CALIB_TEXT, check_asr=False)
                if c["ok"] and c["dur"] > 1.0:
                    info["rtf"], info["ttfa"], info["ch"] = round(c["wall"] / c["dur"], 2), round(c["first"], 2), c["ch"]
                    ns = va.next_steps(self.steps, info["rtf"], self.rtf_target, self.steps_min) if self.autosteps else None
                    if ns is None:
                        break
                    self.say("voice", "RTF %.2f 高于目标 %.2f:扩散步数 %d → %d(优先不断流)" % (info["rtf"], self.rtf_target, self.steps, ns))
                    log.warning("[GPU%d] RTF %.2f > %.2f:扩散步数 %d → %d", self.idx, info["rtf"], self.rtf_target, self.steps, ns)
                    self.steps = ns
                    info["steps"] = ns
                else:
                    break
            except Exception as e:  # noqa: BLE001
                log.warning("[GPU%d] 第二次试合成失败(忽略): %s", self.idx, e)
                break
        info["steps"] = self.steps
        return info

    # ───── 流式合成 ─────
    def stream(self, text, profile, seed=None):
        import vox_audio as va
        text = va.sanitize_text(text)
        if not text:
            return
        if self.cache is None:
            raise RuntimeError("声音尚未就绪(没有冻结的声纹缓存)")
        sched = SCHED.get(profile, SCHED["rest"])
        _seed_all(seed)
        go = getattr(self, "gen_opts", None) or {}
        frames = int(go.get("max_new") or min(MAX_NEW_TOKENS, max(120, int(len(text) * 7))))
        kw = dict(target_text=text, prompt_cache=self.cache, min_len=2, max_len=va.patches_for_frames(min(frames, MAX_NEW_TOKENS)),
                  inference_timesteps=self.steps, cfg_value=self.cfg_value, retry_badcase=False)
        if self._seed_kw:
            kw["seed"] = SEED if seed is None else int(seed)
        dec = va.StreamDecimator.for_rates(self.native_sr, SR)
        co = va.FrameCoalescer(sched)
        total = 0
        arch = [] if os.environ.get("VC_HIFI_ARCHIVE", "1") == "1" else None       # v19:原生 48kHz 无损归档(不经抽取/响度/FX;实时播放仍走 24k 通道,互不影响)
        gen = self.tts.generate_with_prompt_cache_streaming(**kw)
        try:
            for item in gen:
                wav = item[0] if isinstance(item, (tuple, list)) else item
                a = self._to_np(wav).astype(np.float32)
                if arch is not None:
                    arch.append(a)
                if dec is not None:
                    a = dec.process(a)
                for blk in co.push(a):
                    total += len(blk)
                    self.last_frames = total // va.SPF
                    yield blk, SR
            tail = dec.flush() if dec is not None else np.zeros(0, np.float32)
            for blk in co.push(tail) + co.flush():
                total += len(blk)
                self.last_frames = total // va.SPF
                yield blk, SR
        finally:
            try:
                gen.close()
            except Exception:  # noqa: BLE001
                pass
            self._save_hifi(arch)

    def _save_hifi(self, arch):
        """把本句模型原生输出(48kHz,float32→PCM16,峰值保护)落盘到 WORK/hifi48/;只保留最近 VC_HIFI_KEEP 个。任何异常都不影响播放。"""
        if not arch:
            return None
        try:
            import soundfile as sf
            x = np.concatenate(arch).astype(np.float32)
            if not x.size or not np.isfinite(x).all():
                return None
            pk = float(np.max(np.abs(x)))
            if pk > 0.98:
                x = x * (0.98 / pk)
            d = WORK / "hifi48"
            d.mkdir(parents=True, exist_ok=True)
            p = d / ("%d_gpu%d.wav" % (int(time.time() * 1000), self.idx))
            sf.write(str(p), x, int(self.native_sr), subtype="PCM_16")
            keep = int(os.environ.get("VC_HIFI_KEEP", "300"))
            olds = sorted(d.glob("*.wav"))
            for o in olds[:-keep] if keep > 0 else []:
                try:
                    o.unlink()
                except OSError:
                    pass
            self.last_hifi = str(p)
            return str(p)
        except Exception as e:  # noqa: BLE001
            log.warning("[GPU%d] 48k 归档失败(不影响播放): %s", self.idx, e)
            return None


def make_engine(idx, send, cfg):
    """按配置创建引擎。mock=True 且没开 VC_VOX_FAKE → MockEngine(v17 原测试路径不变);mock=True 且 VC_VOX_FAKE=1 → VoxCPM2 适配器 + 假模型。"""
    if cfg.get("mock") and os.environ.get("VC_VOX_FAKE") != "1":
        return MockEngine(idx, send)
    return VoxCPM2Engine(idx, send, fake=bool(cfg.get("mock")))        # v19:唯一真实引擎 = VoxCPM2(不再静默换模型)


def worker_main(idx, gpu, job_q, res_q, epoch, cfg):
    """每张 GPU 一个进程。必须在 import torch 之前设置 CUDA_VISIBLE_DEVICES。"""
    if not cfg.get("mock"):
        os.environ["CUDA_VISIBLE_DEVICES"] = str(gpu)
        os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
        os.environ.setdefault("OMP_NUM_THREADS", "2")        # Kaggle 只有 4 个 CPU 核:两个 GPU 进程 + 网关,别让 CPU 线程互相抢占造成抖动
        os.environ.setdefault("MKL_NUM_THREADS", "2")

    def send(*m):
        res_q.put(m)

    try:
        eng = make_engine(idx, send, cfg)
        send("status", idx, "loading", "启动中…")
        try:
            eng.load()
        except Exception as e0:  # noqa: BLE001  v19:VoxCPM2 加载失败 → 只在【同一个模型】内降级精度重载(fp16 → fp32 → bf16),绝不静默换成别的模型
            if isinstance(eng, VoxCPM2Engine) and not eng.fake:
                last_err, ok_ = e0, False
                tried = [eng.dtype] if eng.dtype else []
                for alt in [d for d in (eng.order or ["float16", "float32", "bfloat16"]) if d not in tried] or ["float32"]:
                    log.error("[GPU%d] VoxCPM2 加载失败(%s: %s),改用 %s 重载:\n%s", idx, type(last_err).__name__, str(last_err)[:120], alt, traceback.format_exc())
                    send("status", idx, "loading", "VoxCPM2 加载失败(%s: %s)→ 改用 %s 重载(不换模型)…" % (type(last_err).__name__, str(last_err)[:80], alt))
                    try:
                        eng._free()
                        eng.load(force_dtype=alt)
                        ok_ = True
                        break
                    except Exception as e1:  # noqa: BLE001
                        last_err = e1
                if not ok_:
                    raise RuntimeError("VoxCPM2 在所有精度下都加载失败:%s: %s。修复建议:①确认 Settings→Internet=On 且 HF 可访问 ②pip 版本 voxcpm==%s 与 torch>=2.5 ③显存是否被其他进程占用(重启会话) ④把 VC_VOX_OPTIMIZE=0 关闭 torch.compile 再试"
                                       % (type(last_err).__name__, str(last_err)[:200], os.environ.get("VC_VOXCPM_VERSION", "2.0.3")))
            else:
                raise
        send("status", idx, "ready", "就绪")
    except Exception as e:  # noqa: BLE001
        log.error("[GPU%d] 引擎加载失败:\n%s", idx, traceback.format_exc())
        send("status", idx, "error", "%s: %s" % (type(e).__name__, e))
        return
    parent = mp.parent_process()
    deferred = []            # 待打分的句子:声纹打分很吃 GPU,只在本卡空闲(队列里没有新活)时才做,绝不插在两句合成之间拖慢播放
    try:
        send("backend", idx, eng.backend_info())
    except Exception as e:  # noqa: BLE001
        log.warning("[GPU%d] 读取后端信息失败: %s", idx, e)

    def settle(item, do_score, why=""):
        """一定会回报一条 sim 消息(带 status/reason):completed / failed / skipped / not_evaluated。不再静默丢弃后只发 None。"""
        tuid, seg_i, pcm_all, ep0 = item
        sim, info = None, {"status": "not_evaluated", "reason": why or "未评分"}
        if epoch.value != ep0:
            info = {"status": "skipped", "reason": "该句所属的任务已被取消或已开始新一轮,旧结果不会串到新任务"}
        elif do_score:
            try:
                sim = eng.score(pcm_all)
                info = dict(getattr(eng, "last_score", None) or {"status": "completed" if sim is not None else "not_evaluated", "reason": ""})
                if sim is None and info.get("status") == "completed":
                    info = {"status": "not_evaluated", "reason": "评分器没有返回分数"}
            except Exception as e:  # noqa: BLE001
                info = {"status": "failed", "reason": "打分异常:%s: %s" % (type(e).__name__, str(e)[:160])}
                log.warning("[GPU%d] 打分失败: %s", idx, e)
        elif not why:
            info = {"status": "skipped", "reason": "评分队列已满(本卡持续忙碌),为不拖慢合成已跳过本句评分"}
        try:
            h = getattr(eng, "scorer_holder", None)
            if h is not None:
                info["scorer_state"] = h.state
            info["ref_id"] = (getattr(eng, "scorer_ref_id", None) or [None, None, None])[1:]
        except Exception:  # noqa: BLE001
            pass
        send("sim", tuid, seg_i, sim, len(pcm_all) / SR, info)

    def run_tts(job):
        _, tuid, ep, seg, text, prof, seed = job[:7]
        if epoch.value != ep:
            send("seg_done", tuid, seg, idx, {"skipped": True})
            return
        max_new = min(MAX_NEW_TOKENS, max(120, int(len(text) * 7)))
        for attempt in range(2):                                    # 只有「还没送出任何音频」的失败才会用新种子重试一次(可复现:seed+attempt)
            cur = int(seed) + attempt
            t0, first, nsamp, sent_any, cancelled = time.time(), None, 0, False, False
            acc, ch, t_prev = [], [], t0                            # ch: 每块 (耗时, 样本数) —— 网关据此拟合「每帧生成时间 / 每块解码开销 / 预填充」
            qc = SegmentQC()
            err = None
            eng.last_frames = 0
            gen = eng.stream(text, prof, cur)
            try:
                for a, sr in gen:
                    if epoch.value != ep:                           # 用户已取消/重连:立刻停止生成,把 GPU 让给下一个任务
                        cancelled = True
                        break
                    if int(sr) != SR:
                        raise AudioCorrupt("块采样率 %s != %d" % (sr, SR))
                    pcm = _f2pcm(a)
                    if pcm.size == 0:
                        continue
                    qc.feed(pcm)
                    if qc.joins and qc.joins[-1][1] > 25 and qc.joins[-1][0] > 6000:
                        raise AudioCorrupt("chunk 边界波形断裂(跳变 %.0f)" % qc.joins[-1][0])
                    now = time.time()
                    if first is None:
                        first = now - t0
                    nsamp += len(pcm)
                    acc.append(pcm)
                    ch.append((round(now - t_prev, 4), len(pcm)))
                    t_prev = now
                    send("chunk", tuid, seg, pcm.tobytes(), round(now - t0, 4))
                    sent_any = True
            except AudioCorrupt as e:
                err = e
            finally:
                try:
                    gen.close()
                except Exception:  # noqa: BLE001
                    pass
            wall = time.time() - t0
            if cancelled:
                send("seg_done", tuid, seg, idx, {"skipped": True, "cancelled": True})
                return
            if err is None:
                fr = int(getattr(eng, "last_frames", 0) or 0)
                rep_ = qc.finish(frames=fr or None, hit_max=bool(fr and fr >= max_new - 1))
                if rep_["errors"]:
                    err = AudioCorrupt("; ".join(rep_["errors"]))
            else:
                rep_ = qc.finish()
                rep_["errors"] = [str(err)]
            if err is not None:
                wav = save_diag(DIAG_DIR, "gpu%s_t%s_s%s_a%d" % (idx, tuid, seg, attempt), qc.audio(), dict(rep_, text=text, seed=cur, gpu=idx))
                log.error("[GPU%d] 音频完整性检查失败(句 %d, 尝试 %d): %s → 诊断 %s", idx, seg, attempt, err, wav)
                if not sent_any and attempt == 0:
                    log.warning("[GPU%d] 尚未送出音频,用新种子重试一次", idx)
                    continue
                send("seg_err", tuid, seg, idx, "AudioCorrupt: %s%s" % (err, ("(诊断已保存 %s)" % wav) if wav else ""))
                return
            send("seg_done", tuid, seg, idx, {"first": first, "wall": wall, "audio": nsamp / SR, "ch": ch[:40], "seed": cur, "attempt": attempt, "qc": rep_})
            if epoch.value == ep and nsamp > SR * 1.2:
                deferred.append((tuid, seg, np.concatenate(acc), ep))     # 音频已全部发出;打分推迟到空闲时
            else:
                send("sim", tuid, seg, None, nsamp / SR, {"status": "skipped", "reason": ("句子太短(<1.2 秒),不评分" if epoch.value == ep else "任务已取消")})
            return

    # ═══════════════ v13 · M3 零损坏放行(开关 VC_V13_GUARD;关闭时走上面的 v12 run_tts,逐字节不变) ═══════════════
    def _drain_codes():
        c = getattr(eng, "code_log", None)
        if not c:
            return None
        ids = list(c)
        del c[:]
        return ids

    def _run_tts13(job):
        """与 v12 的区别:①帧预算按文本/声音标定;②生成中逐块检测(低电平坏尾/重复循环/卡死);③TailHold:末尾低电平帧先扣住,
        结束仍是低电平就丢弃(内容已完整 → 不算损坏);④hold_for_qc:网关判断播放头余量足够时,整句通过检查后才放行,
        所以失败可以【放行前】换种子/降温重试;余量不足时流式放行(首块 ≥160ms 才放行,之后 TailHold 仍然生效);⑤重试阶梯最多 3 次。"""
        _, tuid, ep, seg, text, prof, seed = job[:7]
        extra = job[7] if len(job) > 7 and isinstance(job[7], dict) else {}
        if epoch.value != ep:
            send("seg_done", tuid, seg, idx, {"skipped": True})
            return
        text = _v13.normalize_text(text) or text
        if _v14 is not None:
            text = _v14.spoken(text) or text                         # v14 M5:数字/小数/时间/金额/单位口语化(幂等;VC_V14_TEXT=0 关闭)
        spc = float(extra.get("spc") or 0.2)
        hold = bool(extra.get("hold"))
        exp = _v13.expected_frames(text, spc)
        max_new = _v13.max_new_frames(text, spc, MAX_NEW_TOKENS)
        ladder = _v13.retry_ladder()
        _lf, _sb, salv = int(extra.get("ladder_from") or 0), int(extra.get("seed_bias") or 0), []      # v14:跨卡重试 = 换种子 + 从降温阶梯开始
        if 0 < _lf < len(ladder):
            ladder = ladder[_lf:]
        wasted, m13 = 0.0, {"hold": hold, "runaway": 0, "early_stopped": 0, "retries": 0, "released_corrupt": 0, "wasted_s": 0.0, "failed": 0, "salvaged": 0}
        for attempt, (so, temp, rep) in enumerate(ladder):
            cur = int(seed) + so + _sb
            eng.gen_opts = {"temperature": temp, "rep": rep, "max_new": max_new}
            eng.capture_codes, eng.code_log, eng.last_frames = True, [], 0
            t0, first, nsamp, cancelled = time.time(), None, 0, False
            acc, ch, t_prev = [], [], t0
            gs, raw = (_v14.GuardState() if (_v14 is not None and _v14.on("SALVAGE")) else None), []
            held, sbuf, released = [], [], False
            qc, guard, th = SegmentQC(), _v13.RunawayGuard(exp, max_new), _v13.TailHold()
            err, stop = None, None

            def _release(arrs, now_):
                for o_ in arrs:
                    send("chunk", tuid, seg, o_.tobytes(), round(now_ - t0, 4))

            gen = eng.stream(text, prof, cur)
            try:
                for a, sr in gen:
                    if epoch.value != ep:
                        cancelled = True
                        break
                    if int(sr) != SR:
                        raise AudioCorrupt("块采样率 %s != %d" % (sr, SR))
                    pcm = _f2pcm(a)
                    if pcm.size == 0:
                        continue
                    qc.feed(pcm)
                    if qc.joins and qc.joins[-1][1] > 25 and qc.joins[-1][0] > 6000:
                        raise AudioCorrupt("chunk 边界波形断裂(跳变 %.0f)" % qc.joins[-1][0])
                    now = time.time()
                    if first is None:
                        first = now - t0
                    ch.append((round(now - t_prev, 4), len(pcm)))
                    t_prev = now
                    fr = int(getattr(eng, "last_frames", 0) or 0)
                    ids_ = _drain_codes()
                    if gs is not None:
                        gs.feed(ids_)
                        raw.append(pcm)
                    stop = guard.feed_pcm(pcm, fr or None) or guard.feed_codes(ids_)
                    out = th.feed(pcm)
                    if out.size:
                        acc.append(out)
                        nsamp += out.size
                        if hold:
                            held.append(out)
                        else:
                            sbuf.append(out)
                            if released or sum(len(x_) for x_ in sbuf) >= int(0.16 * SR):
                                _release(sbuf, now)
                                sbuf, released = [], True
                    if stop:
                        break
            except AudioCorrupt as e:
                err = e
            finally:
                try:
                    gen.close()
                except Exception:  # noqa: BLE001
                    pass
            wall = time.time() - t0
            if cancelled:
                send("seg_done", tuid, seg, idx, {"skipped": True, "cancelled": True})
                return
            tl_ = th.flush()
            if tl_.size and err is None and not (stop and stop[1]):
                acc.append(tl_)
                nsamp += tl_.size
                (held if hold else sbuf).append(tl_)
            fr = int(getattr(eng, "last_frames", 0) or 0)
            reason, fatal = (stop[0], bool(stop[1])) if stop else (None, False)
            if err is None and fatal:
                err = AudioCorrupt("生成中检测到失控(%s):已生成 %d 帧,预期约 %.0f 帧,上限 %d" % (reason, fr, exp, max_new))
            if reason and not fatal:
                m13["early_stopped"] += 1
            if reason:
                m13["runaway"] += 1
            if err is None:
                rep_ = qc.finish(frames=(None if reason else (fr or None)), hit_max=bool(fr and fr >= max_new - 1 and not reason))
                rep_["v13"] = {"guard": reason, "dropped_tail_s": round(th.dropped / SR, 2), "exp_frames": round(exp, 1), "max_new": max_new}
                if rep_["errors"]:
                    err = AudioCorrupt("; ".join(rep_["errors"]))
            else:
                rep_ = qc.finish()
                rep_["errors"] = [str(err)]
            if err is not None:
                wav = save_diag(DIAG_DIR, "gpu%s_t%s_s%s_a%d" % (idx, tuid, seg, attempt), qc.audio(), dict(rep_, text=text, seed=cur, gpu=idx, v13=True))
                wasted += wall
                log.error("[GPU%d] 音频完整性检查失败(句 %d, 尝试 %d/%d, %s): %s → 诊断 %s", idx, seg, attempt + 1, len(ladder), "整句保持" if hold else "流式", err, wav)
                if gs is not None and reason in ("stuck", "repeat", "over_budget") and not released and raw:
                    salv.append((gs.clean_frames(reason), np.concatenate(raw), cur, reason))      # v14:记下「失控循环之前」的干净前缀,阶梯耗尽时用于抢救
                if not released and attempt < len(ladder) - 1:
                    m13["retries"] += 1
                    log.warning("[GPU%d] 尚未放行任何音频:换种子/降温重试(第 %d 次),浪费 GPU %.1fs", idx, attempt + 2, wall)
                    continue
                if salv and not released and _v14 is not None:
                    best = max(salv, key=lambda s_: s_[0])
                    okv, cov = _v14.salvage_decision(best[0], exp)
                    if okv:
                        keep = _v14.fade_out(best[1][: int(best[0] * 1920)])          # 12.5Hz 码本:每帧 1920 样本;20ms 淡出,避免截断点爆音
                        _release([keep], time.time())
                        m13["salvaged"], m13["wasted_s"] = 1, round(wasted, 2)
                        info14 = {"reason": best[3], "clean_frames": int(best[0]), "exp_frames": round(exp, 1), "coverage": cov, "seed": best[2]}
                        log.warning("[GPU%d] v14 抢救放行(句 %d):%s 之前的干净前缀 %d 帧(覆盖率 %.0f%% ≥ %.0f%%),可能少尾部几个字;已如实标记 salvaged", idx, seg, best[3], best[0], cov * 100, _v14.SALVAGE_MIN_COVERAGE * 100)
                        send("v13m", idx, m13)
                        send("seg_done", tuid, seg, idx, {"first": first, "wall": wall, "audio": len(keep) / SR, "ch": [], "seed": best[2], "attempt": attempt, "salvaged": True, "v14": info14, "frames": int(best[0]),
                                                           "qc": {"warnings": ["v14 抢救放行:%s 之后的循环已裁掉,覆盖率 %.0f%%(可能缺少末尾少量文字)" % (best[3], cov * 100)], "errors": []}, "v13": m13})
                        return
                m13["failed"], m13["wasted_s"] = 1, round(wasted, 2)
                if released:
                    m13["released_corrupt"] = 1                         # 诚实计数:流式放行后才发现问题,无法收回已放行的块
                send("v13m", idx, m13)
                send("seg_err", tuid, seg, idx, "AudioCorrupt: %s%s" % (err, (" (诊断已保存 %s)" % wav) if wav else ""))
                return
            now = time.time()
            _release(held if hold else sbuf, now)
            m13["wasted_s"] = round(wasted, 2)
            send("v13m", idx, m13)
            send("seg_done", tuid, seg, idx, {"first": first, "wall": wall, "audio": nsamp / SR, "ch": ch[:40], "seed": cur, "attempt": attempt, "qc": rep_, "v13": m13, "frames": fr, "exp_frames": round(exp, 1)})
            if epoch.value == ep and nsamp > SR * 1.2 and acc:
                deferred.append((tuid, seg, np.concatenate(acc), ep))
            else:
                send("sim", tuid, seg, None, nsamp / SR, {"status": "skipped", "reason": ("句子太短(<1.2 秒),不评分" if epoch.value == ep else "任务已取消")})
            return

    def _run_opener(job):
        """桥接音库:用同一条克隆管线合成一条短语;走同样的失控检测与 TailHold;三次内失败只记录原因,不影响主流程。"""
        _, vid, key, cat, text, seed = job[:6]
        t0, best, why = time.time(), None, ""
        exp = _v13.expected_frames(text, 0.2)
        max_new = _v13.max_new_frames(text, 0.2, MAX_NEW_TOKENS)
        for so, temp, rep in _v13.retry_ladder():
            eng.gen_opts = {"temperature": temp, "rep": rep, "max_new": max_new}
            eng.capture_codes, eng.code_log, eng.last_frames = True, [], 0
            guard, th, outs, bad = _v13.RunawayGuard(exp, max_new), _v13.TailHold(), [], None
            gen = eng.stream(text, "second", int(seed) + so)
            try:
                for a, sr in gen:
                    if int(sr) != SR:
                        raise AudioCorrupt("块采样率 %s != %d" % (sr, SR))
                    pcm = _f2pcm(a)
                    if pcm.size == 0:
                        continue
                    outs.append(th.feed(pcm))
                    stop = guard.feed_pcm(pcm, int(getattr(eng, "last_frames", 0) or 0) or None) or guard.feed_codes(_drain_codes())
                    if stop:
                        bad = stop[0] if stop[1] else None
                        break
            except AudioCorrupt as e:
                bad = str(e)
            finally:
                try:
                    gen.close()
                except Exception:  # noqa: BLE001
                    pass
            outs.append(th.flush())
            pcm_all = np.concatenate(outs) if outs else np.zeros(0, np.int16)
            if bad:
                why = bad
                continue
            d_ = _v13.frame_db(pcm_all, 480)
            lead = int(np.argmax(d_ >= -42.0)) if d_.size and (d_ >= -42.0).any() else 0
            pcm_all = pcm_all[max(0, lead - 2) * 480:]
            ok, w_ = _v13.opener_ok(pcm_all)
            if ok:
                best = pcm_all
                break
            why = w_
        send("opener", idx, vid, key, best.astype("<i2").tobytes() if best is not None else None, {"cat": cat, "text": text, "why": why, "wall": round(time.time() - t0, 2)})

    def run_tts13(job):
        try:
            _run_tts13(job)
        finally:
            eng.gen_opts, eng.capture_codes = None, False              # 绝不把本句的 max_new / 采样覆盖带到下一次(例如声音校准合成)

    def run_opener(job):
        try:
            _run_opener(job)
        finally:
            eng.gen_opts, eng.capture_codes = None, False

    while True:
        try:
            job = job_q.get(timeout=0.25 if deferred else 2)
        except _queue.Empty:
            if parent is not None and not parent.is_alive():
                return
            if deferred:
                settle(deferred.pop(0), True)
            continue
        while len(deferred) > 4:                                    # 有界队列:积压太多(一直在忙)→ 最旧的一条标记 skipped 并写明原因(不静默丢弃)
            settle(deferred.pop(0), False)
        kind = job[0]
        if kind == "quit":
            return
        try:
            if kind == "voice":
                _, vid, path, text, xvec = job
                send("status", idx, "voice", "提取声音特征并试合成…")
                info = eng.set_voice(path, text, xvec)
                send("voice_ok", idx, vid, info)
                send("status", idx, "ready", "就绪")
            elif kind == "asr":
                _, rid, path = job
                send("status", idx, "voice", "识别参考音频文字…")
                try:
                    txt = eng.asr(path)
                    send("asr", rid, txt, "")
                except Exception as e:  # noqa: BLE001
                    log.error("[GPU%d] 识别失败: %s", idx, e)
                    send("asr", rid, "", "%s: %s" % (type(e).__name__, e))
                send("status", idx, "ready", "就绪")
            elif kind == "spk_qc":
                _, rid, path = job
                try:
                    send("spk_qc", rid, eng.spk_qc(path), "")                 # 状态(completed/failed/skipped)在结果里,质检不因评分器故障而中断上传
                except Exception as e:  # noqa: BLE001
                    log.warning("[GPU%d] 多人检测失败(忽略): %s", idx, e)
                    send("spk_qc", rid, {}, "%s: %s" % (type(e).__name__, e))
            elif kind == "spk_cmp":
                _, rid, gen_path, refs = job
                try:
                    r_ = eng.spk_cmp(gen_path, refs)
                    send("spk_cmp", rid, r_, "" if r_.get("status") != "failed" else r_.get("reason", "评分器不可用"))
                except Exception as e:  # noqa: BLE001
                    log.warning("[GPU%d] 声纹比对失败: %s", idx, e)
                    send("spk_cmp", rid, {}, "%s: %s" % (type(e).__name__, e))
            elif kind == "tts":
                (run_tts13 if (_v13 is not None and _v13.on("GUARD")) else run_tts)(job)
            elif kind == "opener":
                run_opener(job)
        except Exception as e:  # noqa: BLE001
            log.error("[GPU%d] 任务出错:\n%s", idx, traceback.format_exc())
            if kind == "voice":
                send("voice_err", idx, job[1], "%s: %s" % (type(e).__name__, e))
                send("status", idx, "ready", "就绪(声音设置失败)")
            elif kind == "tts":
                send("seg_err", job[1], job[3], idx, "%s: %s" % (type(e).__name__, e))
            elif kind == "opener":
                send("opener", idx, job[1], job[2], None, {"cat": job[3], "text": job[4], "why": "%s: %s" % (type(e).__name__, e)})
            elif kind in ("asr", "spk_qc", "spk_cmp"):
                send(kind, job[1], "" if kind == "asr" else {}, str(e))
'''
FILES['protocol.py'] = r'''# -*- coding: utf-8 -*-
"""
protocol.py —— 音频帧协议 v2(网关 ↔ 浏览器共用,带单元测试)

每个 WebSocket 二进制帧 = 20 字节小端头 + int16 PCM:
    turn  u32   轮次 ID(防止不同轮次串音)
    seq   u32   轮内序号,从 0 连续递增(检测漏块 / 重复块 / 乱序)
    sr    u32   本帧真实采样率
    n     u32   本帧样本数(必须等于 payload 字节数 / 2)
    flags u16   bit0 END  = 本轮最后一帧(可以 n=0,仅作结束标记)
                bit1 SEG  = 本帧是某个句子的第一帧
                bit2 PAUSE= 本帧开头包含按标点插入的自然停顿(静音)
    seg   u16   句子序号(取模 65536,仅用于诊断)
头长 20 字节 → PCM 起点 4 字节对齐,浏览器可直接建立 Int16Array 视图,无需拷贝。
"""
import struct

HEADER = struct.Struct("<IIIIHH")
HEADER_SIZE = HEADER.size           # 20
F_END, F_SEG, F_PAUSE = 1, 2, 4


class FrameError(ValueError):
    pass


def pack_frame(turn, seq, sr, pcm_bytes, flags=0, seg=0):
    if len(pcm_bytes) % 2:
        raise FrameError("PCM 字节数必须是偶数")
    return HEADER.pack(turn & 0xFFFFFFFF, seq & 0xFFFFFFFF, sr, len(pcm_bytes) // 2, flags & 0xFFFF, seg & 0xFFFF) + bytes(pcm_bytes)


def unpack_frame(buf):
    if len(buf) < HEADER_SIZE:
        raise FrameError("帧太短: %d 字节" % len(buf))
    turn, seq, sr, n, flags, seg = HEADER.unpack_from(buf, 0)
    if len(buf) - HEADER_SIZE != n * 2:
        raise FrameError("样本数与负载长度不符: 头部 n=%d, 实际 %d 字节" % (n, len(buf) - HEADER_SIZE))
    return {"turn": turn, "seq": seq, "sr": sr, "n": n, "flags": flags, "seg": seg, "pcm": bytes(buf[HEADER_SIZE:])}


class FrameChecker:
    """接收端校验器(与浏览器里的 JS 实现逻辑一致)。accept() 返回 (动作, 说明): 'ok' | 'dup' | 'gap' | 'foreign' | 'sr' | 'bad'"""

    def __init__(self, turn, sr=24000):
        self.turn, self.sr = turn, sr
        self.expected = 0
        self.samples = 0
        self.count = 0
        self.ended = False
        self.stat = {"dup": 0, "gap": 0, "foreign": 0, "sr": 0, "bad": 0, "missing": 0}

    def accept(self, buf):
        try:
            f = unpack_frame(buf)
        except FrameError as e:
            self.stat["bad"] += 1
            return "bad", str(e)
        if f["turn"] != self.turn:
            self.stat["foreign"] += 1
            return "foreign", "turn %d != %d" % (f["turn"], self.turn)
        if f["sr"] != self.sr:
            self.stat["sr"] += 1
            return "sr", "sr %d != %d" % (f["sr"], self.sr)
        if f["seq"] < self.expected:
            self.stat["dup"] += 1
            return "dup", "seq %d < expected %d" % (f["seq"], self.expected)
        if f["seq"] > self.expected:
            self.stat["gap"] += 1
            self.stat["missing"] += f["seq"] - self.expected
            return "gap", "seq %d > expected %d" % (f["seq"], self.expected)
        self.expected += 1
        self.count += 1
        self.samples += f["n"]
        if f["flags"] & F_END:
            self.ended = True
        return "ok", f

    def verify_done(self, chunks, samples):
        """与服务端 turn_done 里的总块数 / 总样本数对账"""
        return self.ended and self.count == chunks and self.samples == samples and not self.stat["gap"] and not self.stat["dup"]
'''
FILES['audio_qc.py'] = r'''# -*- coding: utf-8 -*-
"""
audio_qc.py —— 音频完整性检测 / 参考音频质检 / 声学摘要 / 相似度校准(只依赖 numpy)

  · 合成音频:NaN/Inf、无声、削波、样本数、截断、chunk 边界不连续、响度突变 —— 发现损坏必须报错并保存诊断,不得标记为成功
  · 参考音频:口语 / 歌声 / 背景音乐 / 噪声 / 疑似多人 的【启发式】判定(未经标注数据校准,只用于提示,不是权威结论)
  · 声学摘要:语速、停顿、音高范围、响度范围、音色指标;参考与生成分别计算并给出差异
  · 相似度:原始 cosine 与"校准后的估计"严格区分;没有校准文件就显示"未校准,不可给出百分比"
"""
import json
import math
import os
import time
import wave
from pathlib import Path

import numpy as np

SR = 24000


class AudioCorrupt(Exception):
    """合成音频被判定为损坏(NaN/Inf、无声、严重削波、样本数错误、边界断裂…)"""


def to_np(a):
    if hasattr(a, "detach"):
        a = a.detach().float().cpu().numpy()
    return np.asarray(a, dtype=np.float32).reshape(-1)


def float_to_pcm(a, strict=True):
    """float → int16。strict=True 时遇到 NaN/Inf 直接抛 AudioCorrupt(不再用 nan_to_num 悄悄掩盖)。"""
    a = to_np(a)
    if not np.isfinite(a).all():
        bad = int((~np.isfinite(a)).sum())
        if strict:
            raise AudioCorrupt("音频含 %d 个 NaN/Inf 样本(共 %d)" % (bad, a.size))
        a = np.nan_to_num(a)
    return (np.clip(a, -1.0, 1.0) * 32767.0).round().astype("<i2")


def db(x, floor=-120.0):
    return float(20 * math.log10(max(float(x), 1e-9))) if x > 0 else floor


def frame_rms(x, frame):
    n = len(x) // frame
    if n == 0:
        return np.zeros(0, np.float32)
    f = x[: n * frame].astype(np.float32).reshape(n, frame)
    return np.sqrt((f ** 2).mean(axis=1))


# ════════════════════════════════════════════════════════════════
#  合成音频完整性
# ════════════════════════════════════════════════════════════════
class SegmentQC:
    """逐块喂入(原始 int16,未做去静音),结束时给出报告。errors 非空 = 损坏。"""
    FR = SR // 100

    def __init__(self, sr=SR, keep_audio=True):
        self.sr = sr
        self.chunks = []
        self.keep = keep_audio
        self.n = 0
        self.joins = []          # (跳变幅度, 比值)
        self.chunk_db = []
        self.prev_tail = None

    def feed(self, pcm):
        pcm = np.asarray(pcm)
        if pcm.size == 0:
            return
        x = pcm.astype(np.float32)
        if self.prev_tail is not None:
            jump = abs(float(x[0]) - float(self.prev_tail[-1]))
            ctx = np.concatenate([self.prev_tail[-32:], x[:32]])
            local = float(np.abs(np.diff(ctx)).mean()) if ctx.size > 2 else 1.0
            self.joins.append((jump, jump / max(local, 1.0)))
        self.prev_tail = x[-64:].copy()
        r = frame_rms(x, self.FR)
        voiced = r[r >= 110.0]
        if voiced.size >= 3:                                      # 只统计有声块的响度,避免静音块拉出假"突变"
            self.chunk_db.append(db(float(np.sqrt((voiced ** 2).mean())) / 32768.0))
        self.n += pcm.size
        if self.keep:
            self.chunks.append(pcm.astype("<i2", copy=False))

    def audio(self):
        return np.concatenate(self.chunks) if self.chunks else np.zeros(0, "<i2")

    def finish(self, frames=None, spf=1920, hit_max=False):
        pcm = self.audio() if self.keep else None
        err, warn = [], []
        rep = {"samples": self.n, "sr": self.sr, "chunks": len(self.joins) + (1 if self.n else 0)}
        if self.n == 0:
            err.append("没有产生任何音频")
        if pcm is not None and pcm.size:
            x = pcm.astype(np.float32)
            r = frame_rms(x, self.FR)
            peak = float(np.abs(x).max())
            voiced_frac = float((r >= 110.0).mean()) if r.size else 0.0
            sp = r[r >= max(110.0, float(np.percentile(r, 90)) * 0.12)] if r.size else r
            speech_rms = float(np.sqrt((sp ** 2).mean())) if sp.size else 0.0
            clip = float((np.abs(x) >= 32000).mean())
            rep.update(peak_dbfs=round(db(peak / 32768.0), 2), speech_rms_dbfs=round(db(speech_rms / 32768.0), 2),
                       voiced_frac=round(voiced_frac, 3), clip_ratio=round(clip, 5), dur_s=round(self.n / self.sr, 3))
            if speech_rms < 60 or voiced_frac < 0.04:
                err.append("音频近似无声(有声帧 %.1f%%)" % (voiced_frac * 100))
            if clip > 0.01:
                err.append("严重削波(%.2f%% 样本贴近满幅)" % (clip * 100))
            elif clip > 0.002:
                warn.append("轻微削波(%.2f%%)" % (clip * 100))
            tail = r[-2:].mean() if r.size >= 2 else 0.0
            if hit_max or (frames is not None and frames <= 0):
                err.append("疑似被 max_new_tokens 截断(生成未自然结束)")
            elif speech_rms > 0 and tail > 0.6 * speech_rms and self.n / self.sr > 1.0:
                warn.append("结尾仍有较大能量,可能被截断")
        if frames:
            exp = frames * spf
            if self.n and abs(self.n - exp) / max(self.n, 1) > 0.03:
                err.append("样本数 %d 与 %d 帧×%d=%d 不符(%.1f%%)" % (self.n, frames, spf, exp, abs(self.n - exp) / max(self.n, 1) * 100))
        bad_join = [j for j in self.joins if j[1] > 25 and j[0] > 6000]
        mild = [j for j in self.joins if j[1] > 10 and j[0] > 1500]
        rep["max_join_jump"] = round(max([j[0] for j in self.joins] or [0.0]), 1)
        rep["max_join_ratio"] = round(max([j[1] for j in self.joins] or [0.0]), 2)
        if bad_join:
            err.append("%d 个 chunk 边界波形断裂(最大跳变 %.0f)" % (len(bad_join), max(j[0] for j in bad_join)))
        elif mild:
            warn.append("%d 个 chunk 边界有轻微跳变" % len(mild))
        if len(self.chunk_db) >= 3:
            d = np.abs(np.diff(self.chunk_db))
            rep["max_chunk_loudness_step_db"] = round(float(d.max()), 2)
            if d.max() > 12:
                warn.append("相邻块响度突变 %.1f dB" % d.max())
        rep["errors"], rep["warnings"] = err, warn
        return rep


def save_diag(dirpath, tag, pcm, report, sr=SR):
    """损坏音频的诊断快照:WAV + JSON。返回 WAV 路径(失败返回 '')"""
    try:
        d = Path(dirpath)
        d.mkdir(parents=True, exist_ok=True)
        base = d / ("%s_%s" % (time.strftime("%H%M%S"), "".join(c if c.isalnum() else "_" for c in tag)[:40]))
        if pcm is not None and len(pcm):
            with wave.open(str(base) + ".wav", "wb") as w:
                w.setnchannels(1)
                w.setsampwidth(2)
                w.setframerate(sr)
                w.writeframes(np.asarray(pcm, "<i2").tobytes())
        Path(str(base) + ".json").write_text(json.dumps(report, ensure_ascii=False, indent=2, default=str), encoding="utf-8")
        return str(base) + ".wav"
    except Exception:  # noqa: BLE001
        return ""


# ════════════════════════════════════════════════════════════════
#  声学摘要
# ════════════════════════════════════════════════════════════════
def _f0_track(x, sr, fmin, fmax, hop=0.010, win=0.040):
    """基于归一化自相关的简易基频跟踪(向量化)。返回 f0(Hz, 无声=0), 帧能量 dB"""
    h, w = int(sr * hop), int(sr * win)
    n = 1 + max(0, (len(x) - w) // h)
    if n < 3:
        return np.zeros(0), np.zeros(0)
    idx = np.arange(w)[None, :] + h * np.arange(n)[:, None]
    fr = x[idx].astype(np.float32)
    fr -= fr.mean(axis=1, keepdims=True)
    e = np.sqrt((fr ** 2).mean(axis=1) + 1e-12)
    edb = 20 * np.log10(e + 1e-9)
    nfft = 1 << (2 * w - 1).bit_length()
    spec = np.fft.rfft(fr * np.hanning(w)[None, :], nfft, axis=1)
    ac = np.fft.irfft(np.abs(spec) ** 2, nfft, axis=1)[:, :w]
    ac = ac / (ac[:, :1] + 1e-9)
    lo, hi = int(sr / fmax), min(int(sr / fmin), w - 1)
    seg = ac[:, lo:hi]
    k = seg.argmax(axis=1)
    pk = seg[np.arange(n), k]
    f0 = sr / (k + lo)
    thr_e = np.percentile(edb, 90) - 30
    voiced = (pk > 0.40) & (edb > thr_e)
    return np.where(voiced, f0, 0.0), edb


def acoustic_summary(x, sr=SR, text=None, kind="speech"):
    """x: float32/int16 单声道。kind='singing' 时音高范围放宽,且不给出"语速"(歌唱的节奏不能当说话语速)。"""
    x = np.asarray(x)
    if x.dtype.kind == "i":
        x = x.astype(np.float32) / 32768.0
    x = x.astype(np.float32).reshape(-1)
    out = {"kind": kind, "dur_s": round(len(x) / sr, 3)}
    if len(x) < sr * 0.5:
        out["error"] = "音频太短"
        return out
    f0, edb = _f0_track(x, sr, 60.0, 900.0 if kind == "singing" else 420.0)
    if f0.size == 0:
        out["error"] = "音频太短"
        return out
    act = edb > (np.percentile(edb, 95) - 35)                     # 有效发声帧(相对能量)
    idx = np.where(act)[0]
    if idx.size == 0:
        out["error"] = "无有效语音"
        return out
    a0, a1 = idx[0], idx[-1] + 1
    hop = 0.010
    active_s = (a1 - a0) * hop
    out["active_s"] = round(active_s, 3)
    # 停顿:有效区间内连续 ≥150ms 的非发声帧
    run, pauses = 0, []
    for v in act[a0:a1]:
        if not v:
            run += 1
        else:
            if run * hop >= 0.15:
                pauses.append(run * hop)
            run = 0
    out["pause_count"] = len(pauses)
    out["pause_mean_s"] = round(float(np.mean(pauses)), 3) if pauses else 0.0
    out["pause_ratio"] = round(float(sum(pauses) / max(active_s, 1e-6)), 3)
    if text and kind != "singing":
        chars = sum(1 for c in text if c.isalnum() or "\u4e00" <= c <= "\u9fff")
        out["chars"] = chars
        out["chars_per_s"] = round(chars / max(active_s, 1e-6), 3)
        out["chars_per_s_no_pause"] = round(chars / max(active_s - sum(pauses), 1e-6), 3)
    v = f0[f0 > 0]
    out["voiced_ratio"] = round(float(v.size / max(f0.size, 1)), 3)
    if v.size >= 10:
        st = 12 * np.log2(v / 55.0)
        out["f0_median_hz"] = round(float(np.median(v)), 1)
        out["f0_p10_hz"], out["f0_p90_hz"] = round(float(np.percentile(v, 10)), 1), round(float(np.percentile(v, 90)), 1)
        out["f0_range_st"] = round(float(np.percentile(st, 90) - np.percentile(st, 10)), 2)
        out["f0_std_st"] = round(float(st.std()), 2)
    ed = edb[act]
    out["loud_p10_db"], out["loud_p90_db"] = round(float(np.percentile(ed, 10)), 1), round(float(np.percentile(ed, 90)), 1)
    out["loud_range_db"] = round(out["loud_p90_db"] - out["loud_p10_db"], 1)
    out["peak_dbfs"] = round(db(float(np.abs(x).max())), 2)
    seg = x[int(a0 * hop * sr): int(a1 * hop * sr)]
    if seg.size > 2048:
        n = len(seg) // 1024
        sp = np.abs(np.fft.rfft(seg[: n * 1024].reshape(n, 1024) * np.hanning(1024)[None, :], axis=1)) + 1e-9
        fr = np.fft.rfftfreq(1024, 1.0 / sr)
        pw = sp.mean(axis=0)
        out["centroid_hz"] = round(float((fr * pw).sum() / pw.sum()), 1)
        cs = np.cumsum(pw) / pw.sum()
        out["rolloff85_hz"] = round(float(fr[min(np.searchsorted(cs, 0.85), len(fr) - 1)]), 1)
        out["flatness"] = round(float(np.exp(np.log(sp).mean(axis=1)).mean() / sp.mean(axis=1).mean()), 4)
    return out


def compare_summaries(ref, gen):
    """参考 vs 生成的差异(只比较两侧都有的指标;歌声参考不与口语生成比较音高/语速)"""
    if not ref or not gen or ref.get("error") or gen.get("error"):
        return {"note": "缺少可比较的摘要"}
    if ref.get("kind") == "singing":
        return {"note": "参考是歌声:音高 / 语速 / 节奏不能作为口语生成的目标,不做差异比较(歌声克隆未验证)"}
    d = {}
    if ref.get("chars_per_s") and gen.get("chars_per_s"):
        d["rate_ratio"] = round(gen["chars_per_s"] / ref["chars_per_s"], 3)
    if "pause_ratio" in ref and "pause_ratio" in gen:
        d["pause_ratio_diff"] = round(gen["pause_ratio"] - ref["pause_ratio"], 3)
        d["pause_mean_diff_s"] = round(gen["pause_mean_s"] - ref["pause_mean_s"], 3)
    if ref.get("f0_median_hz") and gen.get("f0_median_hz"):
        d["f0_median_diff_st"] = round(12 * math.log2(gen["f0_median_hz"] / ref["f0_median_hz"]), 2)
    if ref.get("f0_range_st") is not None and gen.get("f0_range_st") is not None:
        d["f0_range_diff_st"] = round(gen["f0_range_st"] - ref["f0_range_st"], 2)
    if "loud_range_db" in ref and "loud_range_db" in gen:
        d["loud_range_diff_db"] = round(gen["loud_range_db"] - ref["loud_range_db"], 1)
    if ref.get("centroid_hz") and gen.get("centroid_hz"):
        d["centroid_ratio"] = round(gen["centroid_hz"] / ref["centroid_hz"], 3)
    return d


# ════════════════════════════════════════════════════════════════
#  参考音频质检(启发式)
# ════════════════════════════════════════════════════════════════
def reference_qc(x, sr, orig_sr=None, channels=1, text=None):
    x = np.asarray(x, np.float32).reshape(-1)
    dur = len(x) / sr
    q = {"duration_s": round(dur, 2), "orig_sr": int(orig_sr or sr), "channels": int(channels), "sr": int(sr),
         "heuristic": True, "warnings": [], "kind": "unknown", "kind_zh": "无法判定", "blocking": False}
    if dur < 0.5:
        q.update(blocking=True)
        q["warnings"].append("音频不足 0.5 秒")
        return q
    fr = int(sr * 0.025)
    r = frame_rms(x, fr)
    edb = 20 * np.log10(r + 1e-6)
    speech_lvl, floor_lvl = float(np.percentile(edb, 90)), float(np.percentile(edb, 10))
    snr = speech_lvl - floor_lvl
    q.update(peak_dbfs=round(db(float(np.abs(x).max())), 2), clip_ratio=round(float((np.abs(x) >= 0.99).mean()), 5),
             silence_ratio=round(float((edb < speech_lvl - 35).mean()), 3), snr_db_est=round(snr, 1), floor_dbfs=round(floor_lvl, 1))
    # 底噪帧的"调性":背景音乐 / 持续音的频谱平坦度很低,白噪声接近 1
    quiet = np.argsort(edb)[: max(4, len(edb) // 5)]
    flats = []
    for k in quiet[:40]:
        seg = x[k * fr:(k + 1) * fr]
        if seg.size < fr:
            continue
        sp = np.abs(np.fft.rfft(seg * np.hanning(fr))) + 1e-9
        flats.append(float(np.exp(np.log(sp).mean()) / sp.mean()))
    floor_flat = float(np.mean(flats)) if flats else 1.0
    q["floor_flatness"] = round(floor_flat, 3)
    f0, e2 = _f0_track(x, sr, 60.0, 900.0)
    voiced = f0 > 0
    q["voiced_s"] = round(float(voiced.sum() * 0.010), 2)
    sustain = 0.0
    if voiced.sum() >= 20:
        st = np.where(voiced, 12 * np.log2(np.maximum(f0, 1.0) / 55.0), np.nan)
        run, keep = [], 0
        for i in range(len(st)):
            if np.isnan(st[i]):
                if len(run) >= 30 and (max(run) - min(run)) < 1.0:
                    keep += len(run)
                run = []
            else:
                run.append(st[i])
                if max(run) - min(run) >= 1.0:                 # 音高漂出 1 个半音:不是持续音符
                    if len(run) - 1 >= 30:
                        keep += len(run) - 1
                    run = [st[i]]
        if len(run) >= 30 and (max(run) - min(run)) < 1.0:
            keep += len(run)
        sustain = keep / voiced.sum()
    q["note_sustain_ratio"] = round(float(sustain), 3)
    kind, zh = "clean_speech", "清晰口语"
    if q["voiced_s"] < 0.8:
        kind, zh = "unknown", "无法判定(有声部分太少)"
    elif sustain > 0.40:
        kind, zh = "singing", "疑似歌声(持续音符比例高)"
    elif snr < 20 and floor_flat < 0.18 and floor_lvl > -55:
        kind, zh = "bg_music", "疑似带背景音乐/持续音"
    elif snr < 15:
        kind, zh = "noisy", "噪声较大"
    q["kind"], q["kind_zh"] = kind, zh
    w = q["warnings"]
    if dur < 3:
        w.append("时长不足 3 秒,克隆稳定性差(建议 8~20 秒)")
    elif dur < 6:
        w.append("时长偏短(建议 8~20 秒)")
    if dur > 30:
        w.append("时长超过 30 秒,已在能量最低处截取前段")
    if q["clip_ratio"] > 0.005:
        w.append("有削波(%.2f%%),请降低录音增益" % (q["clip_ratio"] * 100))
    if q["silence_ratio"] > 0.5:
        w.append("静音占比过高(%.0f%%)" % (q["silence_ratio"] * 100))
    if snr < 20 and kind == "clean_speech":
        w.append("信噪比估计偏低(%.0f dB)" % snr)
    if kind == "singing":
        w.append("歌声:口语克隆流程对歌声【未验证/不支持】,请提供清晰口语样本;歌声需单独标记与管理")
    if kind == "bg_music":
        w.append("背景音乐会被当成声音特征。请使用无伴奏的原声;人声分离结果必须再质检,分离伪影可能被误认为说话人特征")
    if text is not None and kind == "clean_speech" and text.strip():
        cps = len([c for c in text if c.isalnum() or "\u4e00" <= c <= "\u9fff"]) / max(q["voiced_s"], 0.1)
        q["text_chars_per_voiced_s"] = round(cps, 2)
        if cps > 9 or cps < 1.2:
            w.append("参考文字与音频时长不匹配(%.1f 字/秒),请核对文字是否与录音严格对应" % cps)
    q["blocking"] = kind in ("singing", "bg_music", "noisy", "unknown") or q["clip_ratio"] > 0.02 or dur < 3
    return q


# ════════════════════════════════════════════════════════════════
#  相似度:原始 cosine 与校准估计严格区分
# ════════════════════════════════════════════════════════════════
def load_calibration(paths):
    """calibration.json: {"method":"logistic","a":..,"b":..,"n_pos":..,"n_neg":..,"auc":..,"condition":"speech","model":"microsoft/wavlm-base-plus-sv","note":"…"}
    必须来自【独立、代表目标场景的标注评测数据】。没有文件 = 未校准。"""
    for p in paths:
        try:
            if p and Path(p).exists():
                c = json.loads(Path(p).read_text(encoding="utf-8"))
                if c.get("method") == "logistic" and "a" in c and "b" in c and int(c.get("n_pos", 0)) + int(c.get("n_neg", 0)) >= 40:
                    c["_path"] = str(p)
                    return c
        except Exception:  # noqa: BLE001
            pass
    return None


def similarity_view(raw, model, cal=None, condition="speech"):
    v = {"raw_cosine": None if raw is None else round(float(raw), 4), "model": model, "range": [-1.0, 1.0], "condition": condition,
         "calibrated": False, "label": "未校准:仅为原始声纹余弦,不能换算成人耳相似度百分比", "probability": None}
    if raw is not None and cal and cal.get("condition", "speech") == condition:
        p = 1.0 / (1.0 + math.exp(-(float(cal["a"]) * float(raw) + float(cal["b"]))))
        n = int(cal.get("n_pos", 0)) + int(cal.get("n_neg", 0))
        v.update(calibrated=True, probability=round(p, 4), label="校准估计:同一说话人概率(%s,样本 %d,AUC %s)" % (cal["method"], n, cal.get("auc", "?")),
                 calibration={"method": cal["method"], "n": n, "auc": cal.get("auc"), "note": cal.get("note", "")})
    return v


def percentile(xs, q):
    xs = sorted(xs)
    if not xs:
        return None
    k = (len(xs) - 1) * q / 100.0
    lo, hi = int(math.floor(k)), int(math.ceil(k))
    return xs[lo] + (xs[hi] - xs[lo]) * (k - lo)
'''
FILES['speaker_sim.py'] = r'''# -*- coding: utf-8 -*-
"""
声纹相似度工具(服务端实时打分 + evaluate.py 离线评估共用)

  模型 : microsoft/wavlm-base-plus-sv (WavLM x-vector,transformers 原生支持)
  指标 : 说话人嵌入的余弦相似度 (Cosine Similarity),范围 -1~1,越接近 1 越像。原始分数,未经独立标注数据校准,不是"人耳相似度百分比"。

v7.1 修复(对应截图「声纹比对失败:AttributeError: 'NoneType' object has no attribute 'embed'」):
  根因: 旧代码在评分器加载/设参考失败后把 scorer 置 None 并永久标记 scorer_failed,而 spk_cmp / spk_qc 只判断 `scorer is None and not scorer_failed`
        就直接调用 scorer.embed() —— scorer_failed=True 时 scorer 恒为 None,于是必现 NoneType.embed;并且最初的底层异常只写进 warning 日志,界面看不到。
        同时「加载模型」与「读取参考音频」被塞进同一个 try,任何一个参考文件的问题都会把已经加载好的模型永久丢掉。
  修复: ScorerHolder 显式状态机(unloaded / loading / ready / failed) + 记录最初异常 + 有界重试(退避) + 永不返回 None;
        音频校验(过短 / 静音 / 非有限值 / 损坏)返回带原因的 skipped,而不是补零伪装成有效分数。
"""
import math
import os
import threading
import time

import numpy as np

SV_MODEL = os.environ.get("VC_SV_MODEL", "microsoft/wavlm-base-plus-sv")
MIN_SAMPLES = int(os.environ.get("VC_SV_MIN_SAMPLES", "8000"))          # 0.5 s @16k;更短的音频嵌入不可靠 → skipped
SILENCE_RMS = float(os.environ.get("VC_SV_SILENCE_RMS", "0.002"))
MAX_SECONDS = 30


class AudioSkip(Exception):
    """输入音频不适合打分(不是模型故障):调用方应把它标成 skipped 并显示原因,不得补零后给分。"""

    def __init__(self, reason, code="invalid_audio"):
        super().__init__(reason)
        self.reason, self.code = reason, code


class ScorerUnavailable(RuntimeError):
    """评分器当前不可用(加载失败 / 冷却中 / 重试次数用尽)。携带最初的底层异常说明。"""

    def __init__(self, reason, state="failed", info=None):
        super().__init__(reason)
        self.reason, self.state, self.info = reason, state, info or {}


def to16k(x, sr):
    """float32 mono -> 16kHz float32"""
    x = np.asarray(x, dtype=np.float32).reshape(-1)
    if sr == 16000 or x.size == 0:
        return x
    try:
        from math import gcd
        from scipy.signal import resample_poly
        g = gcd(int(sr), 16000)
        return resample_poly(x, 16000 // g, int(sr) // g).astype(np.float32)
    except Exception:  # noqa: BLE001
        n = int(len(x) * 16000 / sr)
        return np.interp(np.linspace(0, len(x) - 1, n), np.arange(len(x)), x).astype(np.float32)


def check_audio(w, min_samples=None):
    """校验 16k 单声道音频;不合格抛 AudioSkip(带原因)。返回截断到 30 秒的 float32 数组。"""
    w = np.asarray(w, dtype=np.float32).reshape(-1)
    if w.size == 0:
        raise AudioSkip("音频为空", "empty")
    if not np.isfinite(w).all():
        raise AudioSkip("音频含 NaN/Inf(损坏或合成异常)", "non_finite")
    if w.size < (min_samples or MIN_SAMPLES):
        raise AudioSkip("音频太短(%.2fs < %.2fs),说话人嵌入不可靠,已跳过(不补零)" % (w.size / 16000, (min_samples or MIN_SAMPLES) / 16000), "too_short")
    if float(np.sqrt(np.mean(w.astype(np.float64) ** 2))) < SILENCE_RMS:
        raise AudioSkip("音频近乎静音,无法提取说话人特征", "silent")
    return w[: 16000 * MAX_SECONDS]


def load_wav16k(path):
    """读取音频文件 → 16k 单声道。文件缺失/损坏 → AudioSkip(带原因),不会抛出含糊的底层异常。"""
    if not os.path.isfile(str(path)):
        raise AudioSkip("参考/生成音频文件不存在:%s" % os.path.basename(str(path)), "missing_file")
    try:
        import soundfile as sf
        a, sr = sf.read(str(path), dtype="float32", always_2d=False)
    except Exception as e:  # noqa: BLE001
        raise AudioSkip("音频无法解码(文件损坏或格式不支持):%s: %s" % (type(e).__name__, str(e)[:80]), "decode_error")
    if a.ndim > 1:
        a = a.mean(axis=1)
    if not sr or sr <= 0:
        raise AudioSkip("音频采样率异常(%r)" % sr, "bad_sample_rate")
    return to16k(a, sr)


def pcm16_to_16k(pcm, sr=24000):
    return to16k(np.asarray(pcm, dtype=np.float32) / 32768.0, sr)


class SpkScorer:
    """加载一次,反复打分。device 例如 'cuda' / 'cuda:0' / 'cpu'。加载失败直接抛出【原始异常】(由 ScorerHolder 记录)。"""

    def __init__(self, device="cuda"):
        import torch
        from transformers import AutoFeatureExtractor, WavLMForXVector
        self.torch = torch
        self.device = device if (device == "cpu" or torch.cuda.is_available()) else "cpu"
        self.fe = AutoFeatureExtractor.from_pretrained(SV_MODEL)
        try:
            model = WavLMForXVector.from_pretrained(SV_MODEL)
        except Exception:  # noqa: BLE001
            # 该仓库只有 pytorch_model.bin;torch<2.6 时 transformers 会拒绝加载 -> 用 weights_only=True 手动加载(同样安全)
            from huggingface_hub import hf_hub_download
            from transformers import AutoConfig
            cfg = AutoConfig.from_pretrained(SV_MODEL)
            model = WavLMForXVector(cfg)
            sd = torch.load(hf_hub_download(SV_MODEL, "pytorch_model.bin"), map_location="cpu", weights_only=True)
            res = model.load_state_dict(sd, strict=False)
            missing = [k for k in getattr(res, "missing_keys", []) if not k.startswith("wavlm.")]
            if missing:                                      # 分类头/投影权重缺失 = 得到随机嵌入,必须报错而不是悄悄给分
                raise RuntimeError("声纹模型权重不完整(缺少 %d 个键,例如 %s)" % (len(missing), missing[:3]))
        self.model = model.to(self.device).eval()
        self.ref = None

    def embed(self, wav16k):
        torch = self.torch
        w = check_audio(wav16k)
        inp = self.fe([w], sampling_rate=16000, return_tensors="pt", padding=True)
        inp = {k: v.to(self.device) for k, v in inp.items()}
        with torch.inference_mode():
            e = self.model(**inp).embeddings
        if e is None or e.numel() == 0:
            raise RuntimeError("模型返回了空嵌入")
        e = torch.nn.functional.normalize(e.float(), dim=-1)[0]
        if not bool(torch.isfinite(e).all()):
            raise RuntimeError("模型返回了非有限嵌入(NaN/Inf)")
        return e

    def set_ref(self, wav16k_list):
        """参考声纹 = 若干条真人音频嵌入的均值(再归一化)"""
        torch = self.torch
        if isinstance(wav16k_list, np.ndarray):
            wav16k_list = [wav16k_list]
        es = torch.stack([self.embed(w) for w in wav16k_list])
        if len({tuple(e.shape) for e in es}) != 1:
            raise RuntimeError("参考嵌入维度不一致")
        self.ref = torch.nn.functional.normalize(es.mean(0), dim=-1)
        return self.ref

    def score(self, wav16k):
        if self.ref is None:
            raise ScorerUnavailable("尚未设置参考声纹(set_ref 未成功)", "no_reference")
        e = self.embed(wav16k)
        if e.shape != self.ref.shape:
            raise RuntimeError("嵌入维度不一致(%s vs %s)" % (tuple(e.shape), tuple(self.ref.shape)))
        return float((e * self.ref).sum().item())

    def pair(self, a16k, b16k):
        return float((self.embed(a16k) * self.embed(b16k)).sum().item())


class ScorerHolder:
    """评分器生命周期:unloaded → loading → ready | failed。

      · 永远不返回 None:get() 要么返回可用评分器,要么抛 ScorerUnavailable(带最初异常、尝试次数、下次重试时间)。
      · 有界重试:最多 max_attempts 次加载,失败后按 cooldown 秒退避(默认 0/20/60s),用尽后保持 failed(调用 reset() 才会重新开始),
        不会每个请求都重新下载/加载大模型。
      · factory 可注入(单元测试用假工厂;真实环境是 SpkScorer)。
    """

    def __init__(self, factory, max_attempts=3, cooldown=(0.0, 20.0, 60.0), clock=time.time, label="声纹评分器"):
        self.factory, self.max_attempts, self.cooldown, self.clock, self.label = factory, max_attempts, tuple(cooldown), clock, label
        self.state = "unloaded"
        self.scorer = None
        self.attempts = 0
        self.last_error = None          # "TypeName: message" —— 最初/最近一次底层异常(原文,不会被泛化成"评分失败")
        self.last_error_type = None
        self.next_retry_at = 0.0
        self.loaded_at = None
        self._lock = threading.RLock()

    def info(self):
        wait = max(0.0, self.next_retry_at - self.clock()) if self.state == "failed" else 0.0
        return {"state": self.state, "attempts": self.attempts, "max_attempts": self.max_attempts, "last_error": self.last_error, "error_type": self.last_error_type,
                "retry_in_s": round(wait, 1), "exhausted": bool(self.state == "failed" and self.attempts >= self.max_attempts), "model": SV_MODEL, "loaded_at": self.loaded_at,
                "has_reference": bool(self.scorer is not None and getattr(self.scorer, "ref", None) is not None)}

    def reset(self):
        with self._lock:
            if self.state != "ready":
                self.state, self.attempts, self.next_retry_at = "unloaded", 0, 0.0

    def get(self):
        with self._lock:
            if self.state == "ready" and self.scorer is not None:
                return self.scorer
            now = self.clock()
            if self.state == "failed":
                if self.attempts >= self.max_attempts:
                    raise ScorerUnavailable("%s加载失败且已重试 %d 次仍失败:%s" % (self.label, self.attempts, self.last_error), "failed", self.info())
                if now < self.next_retry_at:
                    raise ScorerUnavailable("%s上次加载失败(%s);%.0f 秒后自动重试" % (self.label, self.last_error, self.next_retry_at - now), "failed", self.info())
            self.state = "loading"
            self.attempts += 1
            try:
                sc = self.factory()
            except Exception as e:  # noqa: BLE001 —— 记录最初异常原文
                self.scorer = None
                self.state = "failed"
                self.last_error = "%s: %s" % (type(e).__name__, str(e).strip()[:300])
                self.last_error_type = type(e).__name__
                idx = min(self.attempts, len(self.cooldown) - 1)
                self.next_retry_at = self.clock() + self.cooldown[idx]
                raise ScorerUnavailable("%s加载失败(第 %d/%d 次):%s" % (self.label, self.attempts, self.max_attempts, self.last_error), "failed", self.info())
            self.scorer, self.state, self.last_error, self.last_error_type, self.loaded_at = sc, "ready", None, None, time.time()
            return sc


def result_status(status, reason="", **kw):
    """统一的评分结果:status ∈ completed | failed | skipped | not_evaluated;任何非 completed 都必须带 reason,且不含分数。"""
    assert status in ("completed", "failed", "skipped", "not_evaluated")
    d = {"status": status, "reason": reason}
    d.update(kw)
    return d


def finite_or_none(v):
    try:
        v = float(v)
        return v if math.isfinite(v) else None
    except Exception:  # noqa: BLE001
        return None
