import asyncio
import ipaddress
import os
import re
import socket
import time
from urllib.parse import urlsplit

MAX_URL_LEN = 2048
ALLOWED_SCHEMES = ("http", "https")
BLOCKED_NAMES = {"localhost", "localhost.localdomain", "ip6-localhost", "ip6-loopback", "metadata", "metadata.google.internal", "instance-data",
                 "instance-data.ec2.internal", "kubernetes", "kubernetes.default", "host.docker.internal", "gateway.docker.internal"}
BLOCKED_SUFFIXES = (".localhost", ".local", ".internal", ".lan", ".home", ".home.arpa", ".corp", ".intranet", ".private", ".localdomain", ".cluster.local")
METADATA_IPS = {"169.254.169.254", "169.254.170.2", "100.100.100.200", "192.0.0.192", "fd00:ec2::254", "168.63.129.16"}
