def _test_allow():
    return {x.strip().lower() for x in os.environ.get("VC_BROWSER_TEST_ALLOW", "").split(",") if x.strip()}


def ip_is_public(ip):
    """True = 可以访问的公网地址。解析不了的当作不安全。"""
    if isinstance(ip, str):
        try:
            ip = ipaddress.ip_address(ip.split("%")[0])
        except ValueError:
            return False
    if ip.version == 6:
        emb = [ip.ipv4_mapped, ip.sixtofour]
        if ip.teredo:
            emb += [ip.teredo[0], ip.teredo[1]]
        raw = int(ip)
        if (raw >> 32) == 0x0064FF9B0000000000000000:                      # 64:ff9b::/96 NAT64
            emb.append(ipaddress.IPv4Address(raw & 0xFFFFFFFF))
        for e in emb:
            if e is not None and not ip_is_public(e):
                return False
        if ip.is_site_local:
            return False
    if str(ip) in METADATA_IPS:
        return False
    return bool(ip.is_global) and not (ip.is_multicast or ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_unspecified)


