class FakeGW(I.LLMGateway):
    """【仅测试】可编程的网关:不发网络请求"""
    def __init__(self, replies, **kw):
        super().__init__(key="test-key", **kw)
        self.replies, self.calls, self.payloads = list(replies), 0, []

    async def _post(self, payload, timeout):
        self.calls += 1
        self.payloads.append(payload)
        r = self.replies.pop(0) if self.replies else (200, {"choices": [{"message": {"content": "{}"}, "finish_reason": "stop"}]})
        if isinstance(r, Exception):
            raise r
        if callable(r):
            return r(payload)
        return r


