    rows["xvfb"], rows["ffmpeg"] = bool(shutil.which("Xvfb") or shutil.which("xvfb-run")), bool(shutil.which("ffmpeg"))
    try:
        rows["chromium_version"] = browser.version if browser is not None else None
    except Exception:  # noqa: BLE001
        rows["chromium_version"] = None
    hosts = ["www.bing.com", "www.google.com", "duckduckgo.com", "www.baidu.com", "en.wikipedia.org"]
    res = await asyncio.gather(*[_dns(h) for h in hosts])
    rows["dns"] = {h: r for h, r in zip(hosts, res)}
    HEALTH.update(done=True, at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), rows=rows)
    return HEALTH
