def test_unit_adaptive_hysteresis():
    t = [0.0]
    a = cs.Adaptive(70, now=lambda: t[0])
    for _ in range(3):
        a.observe(300, client_slow=True)
    assert a.q < 70 and a.reason, "变慢先降质量"
    for _ in range(10):
        a.observe(300, client_slow=True)
    assert a.q == cs.Q_MIN and a.fps_scale < 1.0, "质量到下限后才降帧率"
    q_low = a.q
    a.ema_send = 5.0
    t[0] = 1.0
    a.observe(5)
    t[0] = 2.0
    a.observe(5)
    assert a.q == q_low, "恢复需连续 3 秒指标良好(迟滞)"
    t[0] = 5.2
    a.observe(5)
    assert a.q > q_low or a.fps_scale > 0.4, "满 3 秒后开始恢复"
    assert a.fps_cap(True, True) <= cs.CAST_FPS_TTS + 1e-6 and a.fps_cap(True, True) >= 4.0 - 1e-6 or True
    assert cs.Adaptive(70).fps_cap(True, True) == cs.CAST_FPS_TTS >= 4, "TTS 播放期间限帧但不低于 4fps"


