def test_unit_suggest_cooldown_on_429_and_cache():
    async def run():
        class R:
            def __init__(s, c, b=b'["q",["a"]]'):
                s.status_code, s.content = c, b
        calls = []

        class C:
            def __init__(s, codes):
                s.codes = list(codes)

            async def get(s, url):
                calls.append(url)
                return R(s.codes.pop(0))
        omnibox.netguard.acheck_url = lambda u, resolve=True: asyncio.sleep(0)       # 不做真实 DNS
        sg = omnibox.Suggest()
        sg.client = C([200, 429])
        r1 = await sg.fetch("abc", "google")
        r2 = await sg.fetch("abc", "google")
        assert r1["ok"] and r2["cache"] is True and len(calls) == 1, "命中缓存不再请求"
        r3 = await sg.fetch("abd", "google")
        assert not r3["ok"] and "429" in r3["error"]
        n = len(calls)
        r4 = await sg.fetch("abe", "google")
        assert not r4["ok"] and "冷却" in r4["error"] and len(calls) == n, "遇 429 后冷却期内一次都不再发"
