    async def after(self, ctx, settle=True, target_covered=False):
        s, v = self.s, self.s.v12
        pg = s.page
        if settle:
            await s._settle()
        await v.frames_quiet()
        await asyncio.sleep(0)
        sig = await self._sig()
        mo = {"c": 0, "a": 0, "d": 0}
        if ctx.get("mo") and pg is not None:
            try:
                mo = await pg.evaluate(MO_OFF_JS)
            except Exception:  # noqa: BLE001
                pass
        kinds, ev0, ev = [], ctx["events"], v.counters
        old = ctx.get("sig") or {}
        if len(s.pages) > ctx["pages"] or ev["popup"] > ev0["popup"]:
            kinds.append("popup")
        if ev["dialog"] > ev0["dialog"]:
            kinds.append("dialog")
        if ev["download"] > ev0["download"]:
            kinds.append("download")
        new_doc = bool(old and sig and old.get("token") != sig.get("token"))
        cur_url = pg.url if pg and not pg.is_closed() else ""
        if new_doc or (not sig and cur_url != ctx["url"] and ev["nav"] > ev0["nav"]):
            kinds.append("navigation")
        elif cur_url != ctx["url"]:
            kinds.append("spa_route")
        dom_n = int(mo.get("c", 0)) + int(mo.get("a", 0)) + int(mo.get("d", 0))
        sig_changed = bool(old and sig and not new_doc and (old.get("n") != sig.get("n") or old.get("tl") != sig.get("tl") or old.get("th") != sig.get("th") or old.get("modal") != sig.get("modal") or old.get("cls") != sig.get("cls")))
        if dom_n > 0 or sig_changed:
            kinds.append("dom")
        if old and sig and old.get("active") != sig.get("active") and sig.get("active") not in ("", "body"):          # 焦点「回到 body」只是失焦,不算变化(否则点空白会被误判)
            kinds.append("focus")
        if old and sig and not new_doc and (old.get("sx") != sig.get("sx") or old.get("sy") != sig.get("sy")):
            kinds.append("scroll")
