        fa, fb = ctx.get("frame"), v.latest_frame_bytes()
        if fa and fb and fa is not fb:
            vis_ratio = frame_diff_ratio(fa, fb)
            if vis_ratio is not None:
                vis = vis_ratio >= VISUAL_RATIO
                if vis:
                    kinds.append("visual")
