        s1 = st.add_sample(a["library_id"], b"orig1", "wav", _wav(6, 1), 6, 48000, 2, _qc(), "你好世界", "user", True, session="rec1")
        h1 = libs.sha256_file(st.sample_paths(a["library_id"], s1["sample_id"])["orig"])
        s2 = st.add_sample(a["library_id"], b"orig2", "wav", _wav(6, 2), 6, 24000, 1, _qc(), "再见", "user", True, session="rec2")
        sb = st.add_sample(b["library_id"], b"origB", "wav", _wav(6, 3), 6, 24000, 1, _qc(), "你好", "user", True)
        assert len(st.get(a["library_id"])["samples"]) == 2 and len(st.get(b["library_id"])["samples"]) == 1
        assert libs.sha256_file(st.sample_paths(a["library_id"], s1["sample_id"])["orig"]) == h1, "旧样本不得被覆盖"
        assert s1["sample_id"] != s2["sample_id"] and s1["orig_sha256"] == libs.sha256_bytes(b"orig1")
