        # 容量不足:明确拒绝,不删样本
        st.min_free = 1 << 62
        raises(lambda: st.add_sample(a["library_id"], b"x", "wav", _wav(6, 5), 6, 24000, 1, _qc(), "", "", False), libs.StoreError, "磁盘空间不足")
