def test_unit_libraries_dataset_freeze_jobs_candidates_rollback():
    with tempfile.TemporaryDirectory() as td:
        st = libs.LibraryStore(Path(td) / "libs", min_free_mb=1)
        raw = st.create("训练库", False)
