            bb = await sess.page.locator("#b").bounding_box()
            cur = [e for e in sub.q if e.get("type") == "cursor" and e.get("kind") == "click"]
            assert cur and abs(cur[-1]["x"] - (bb["x"] + bb["width"] / 2)) <= 1 and abs(cur[-1]["y"] - (bb["y"] + bb["height"] / 2)) <= 1, (cur, bb)
            assert await sess.page.title() == "clicked"
            assert any(e["kind"] == "verify" for e in sess.log)
