            assert await sess.page.input_value("#n") == "你好abc"
            tev = [e["text"] for e in sub.q if e.get("type") == "typing"]
            assert tev and tev[-1] == "你好abc" and len(set(tev)) > 1
            # 4) 滚动 / 返回 / 前进 / 刷新 / 读取
            assert await _run(sess, [{"action": "goto", "url": base + "/long"}, {"action": "scroll", "direction": "down", "amount": 800}]) == "done"
            assert await sess.page.evaluate("window.scrollY") > 300
            assert await _run(sess, [{"action": "back"}, {"action": "forward"}, {"action": "reload"}, {"action": "read"}]) == "done"
