class _Clock:
    def __init__(self):
        self.t = 1000.0

    def __call__(self):
        return self.t


def test_unit_scorer_holder_state_machine():
    import speaker_sim as ss
    clk, calls = _Clock(), {"n": 0, "fail": True}

    def factory():
        calls["n"] += 1
        if calls["fail"]:
            raise OSError("模拟:模型下载失败 / CUDA out of memory")
        return object()
    h = ss.ScorerHolder(factory, max_attempts=3, cooldown=(0, 20, 60), clock=clk)
    assert h.state == "unloaded"
    e = raises(h.get, ss.ScorerUnavailable)                                   # 第 1 次:失败,记录最初异常原文
    assert h.state == "failed" and "OSError" in h.last_error and "CUDA out of memory" in e.reason and calls["n"] == 1
    e = raises(h.get, ss.ScorerUnavailable, "秒后自动重试")                    # 冷却中:不会再去加载(不会每个请求都重试)
    assert calls["n"] == 1 and e.info["retry_in_s"] > 0
    clk.t += 21
    raises(h.get, ss.ScorerUnavailable)                                       # 第 2 次重试仍失败
    assert calls["n"] == 2
    clk.t += 61
    raises(h.get, ss.ScorerUnavailable)                                       # 第 3 次
    assert calls["n"] == 3
    clk.t += 10000
    e = raises(h.get, ss.ScorerUnavailable, "已重试 3 次")                     # 有界:用尽后不再重试
    assert calls["n"] == 3 and h.info()["exhausted"] and "OSError" in e.reason
    h.reset()                                                                 # 受控恢复
    calls["fail"] = False
    sc = h.get()
    assert h.state == "ready" and sc is not None and h.get() is sc and calls["n"] == 4 and h.last_error is None   # 就绪后不再重复加载


