# ═════════════════════ 语音指令 ═════════════════════
def test_unit_voice_planner_controls_and_loose_search():
    import browser_agent as ba
    for t, k in (("暂停。", "pause"), ("继续", "resume"), ("取消任务", "cancel"), ("停止", "cancel")):
        assert ba.plan_rules(t).get("control") == k, t
    p = ba.plan_rules("搜索 今天的天气。")
    assert p["actions"][0]["action"] == "search" and p["actions"][0]["query"] == "今天的天气" and p["actions"][0]["engine"] == "bing", p
    assert [a["action"] for a in ba.plan_rules("打开第一个结果")["actions"]] == ["open_result"] and ba.plan_rules("打开第一个结果")["actions"][0]["n"] == 1
    assert ba.plan_rules("往下滚动")["actions"][0]["direction"] == "down" and ba.plan_rules("返回")["actions"][0]["action"] == "back" and ba.plan_rules("刷新页面")["actions"][0]["action"] == "reload"
    p = ba.plan_rules("日期", loose=True)                                       # 语音里直接说关键词 = 搜索
    assert p["actions"][0]["query"] == "日期" and p.get("assumed_search")
    assert not ba.plan_rules("日期")["actions"]                                  # 非语音(严格)模式仍然要求明确
    assert not ba.plan_rules("发送这条消息给老板", loose=True)["actions"]         # 含高影响词不会被当成普通搜索自动执行


def test_unit_agent_cursor_and_typing_events_follow_real_calls():
    """鼠标/键盘事件必须与真实的 Playwright 调用一一对应(这里用记录型替身页面验证事件序列;真实 Chromium 画面验证见 test_portal 的浏览器测试,缺 Chromium 时标「未验证」)。"""
    import browser_agent as ba

    class Mouse:
        def __init__(self):
            self.moves = []

        async def move(self, x, y, steps=1):
            self.moves.append((round(x), round(y)))

    class Kb:
        def __init__(self):
            self.typed = []

        async def type(self, ch):
            self.typed.append(ch)

    class Pg:
        mouse, keyboard = Mouse(), Kb()

        async def evaluate(self, *a):
            return {"tag": "input", "type": "search", "name": "q", "ce": False}

    async def go():
        s = ba.BSession(None, "t")
        s.page = Pg()
        sub = ba.Sub()
        s.subs.add(sub)
        await s._mouse_to(500, 300, "click")
        await s._type("天气 ok", "bing.com") if False else None
        return s, sub
    s, sub = asyncio.run(go())
    ev = [m for m in sub.q if m["type"] == "cursor"]
    assert len(s.page.mouse.moves) == len(ev) >= 6, (len(s.page.mouse.moves), len(ev))                 # 每个事件 = 一次真实 mouse.move
    assert (ev[-1]["x"], ev[-1]["y"]) == s.page.mouse.moves[-1] == (500, 300) and ev[-1]["kind"] == "click" and all(e["kind"] == "move" for e in ev[:-1])
    assert all(ev[i]["t"] <= ev[i + 1]["t"] for i in range(len(ev) - 1))                                  # 时间戳来自真实执行,单调递增

    async def typ():
        s = ba.BSession(None, "t2")
        s.page = Pg()
        sub = ba.Sub()
        s.subs.add(sub)
        await s._type("天气 ok", "bing.com")
        return s, sub
    try:
        s2, sub2 = asyncio.run(typ())
    except Exception:  # noqa: BLE001
        s2 = None
    if s2 is not None:
        ty = [m for m in sub2.q if m["type"] == "typing"]
        assert Pg.keyboard.typed == list("天气 ok") and [m["ch"] for m in ty] == list("天气 ok") and ty[-1]["done"] and ty[-1]["text"] == "天气 ok"      # 每个字符 = 一次真实 keyboard.type


# ═════════════════════ Mock 引擎服务集成:/api/search 的错误必须是可读 JSON ═════════════════════
def _http(srv, method, path, body=None):
    import urllib.error
    import urllib.request
    data = json.dumps(body).encode() if isinstance(body, dict) else body
    req = urllib.request.Request(srv.url(path), data=data, method=method, headers={"Content-Type": "application/json"} if isinstance(body, dict) else {})
    try:
        r = urllib.request.urlopen(req, timeout=90)
        raw, code, hd = r.read(), r.status, r.headers
    except urllib.error.HTTPError as e:
        raw, code, hd = e.read(), e.code, e.headers
    try:
        return code, json.loads(raw), hd
    except ValueError:
        return code, raw.decode("utf-8", "replace"), hd


def test_server_search_without_keys_and_json_errors():
    import test_gateway as tg
    srv_fake, base = _fake_site()
    FakeSite.modes.update(bing="ok", ddg="ok", wiki="ok")
    env = dict(VC_SEARCH_CACHE_TTL="0", VC_TEST_BING_BASE=base, VC_TEST_DDG_BASE=base, VC_TEST_WIKI_BASE=base, BRAVE_SEARCH_API_KEY="", GOOGLE_CSE_KEY="", GOOGLE_CSE_CX="", PLAYWRIGHT_BROWSERS_PATH="/nonexistent_pw", DEEPSEEK_API_KEY="")
    srv = tg.Server(**env)
    try:
        code, j, hd = _http(srv, "POST", "/api/search", {"q": "日期", "answer": False})                        # 没有任何 Key,直接搜索
        assert code == 200 and j["ok"] and j["mode"]["provider"] == "http:bing+duckduckgo" and len(j["results"]) == 3 and j["request_id"] and hd.get("X-Request-Id") == j["request_id"], (code, j)
        assert j["results"][0]["domain"] == "example.org" and j["attempts"][0]["ok"]
        code, st, _ = _http(srv, "GET", "/api/portal/status")
        assert st["search"]["auto"] == "http" and {x["id"]: x["available"] for x in st["search"]["providers"]}["bing"]
        # 提供方 5xx → 自动回退,用户看到实际 provider
        FakeSite.modes.update(bing="503")
        code, j, _ = _http(srv, "POST", "/api/search", {"q": "日期", "answer": False})
        assert code == 200 and j["mode"]["provider"] == "http:duckduckgo" and j["attempts"][0]["kind"] == "server_error"
        # 全部失败(浏览器二进制缺失):502 + JSON + 每次尝试 + 明确说明 —— 不是裸 503/空白
        FakeSite.modes.update(bing="503", ddg="challenge", wiki="503")
        code, j, hd = _http(srv, "POST", "/api/search", {"q": "日期", "answer": False})
        assert code == 502 and isinstance(j, dict) and j["ok"] is False and j["error"] and j["request_id"] and not j["results"], (code, j)
        provs = [a["provider"] for a in j["attempts"]]
        assert provs[:3] == ["bing", "duckduckgo", "wikipedia"] and provs[-1] == "browser" and j["attempts"][-1]["kind"] == "config" and ("Chromium" in j["error"] or "playwright" in j["error"]), j
        # 路由不存在/方法错误:也是 JSON(带 error 字段),前端永远拿到可读信息
        code, j, _ = _http(srv, "GET", "/api/search")
        assert code == 405 and isinstance(j, dict) and j.get("error"), (code, j)
        code, j, _ = _http(srv, "POST", "/api/search", {"q": ""})
        assert code == 400 and j["error"], (code, j)
    finally:
        srv.stop()
        srv_fake.shutdown()


if __name__ == "__main__":
    tests = [(k, v) for k, v in sorted(globals().items()) if k.startswith("test_") and callable(v)]
    if "--unit" in sys.argv:
        tests = [(k, v) for k, v in tests if k.startswith("test_unit_")]
    bad = 0
    for name, fn in tests:
        t0 = time.time()
        try:
            fn()
            print("  ✓ %s (%.1fs)" % (name, time.time() - t0), flush=True)
        except Exception:  # noqa: BLE001
            import traceback
            bad += 1
            print("  ✗ %s" % name)
            traceback.print_exc()
    for s in SKIPPED:
        print("  ⚠ 未验证:" + s)
    print("%d 项通过, %d 项失败, %d 项未验证" % (len(tests) - bad, bad, len(SKIPPED)))
    sys.exit(1 if bad else 0)
