            r_ = pg.evaluate("(() => { const r = document.getElementById('shot').getBoundingClientRect(), w = document.getElementById('stageWrap').getBoundingClientRect(); return [r.left, r.top, r.width, r.height, w.left, w.top, w.width, w.height]; })()")
            Fx.clicks.clear()
            cx, cy = r_[4] + r_[6] / 2, r_[5] + r_[7] / 2                          # 1:1 + 已滚动:点容器中心
            pg.mouse.click(cx, cy)
            for _ in range(40):
                if Fx.clicks:
                    break
                time.sleep(0.1)
            ex, ey = (cx - r_[0]) / r_[2] * 1600, (cy - r_[1]) / r_[3] * 1000
            assert Fx.clicks and abs(Fx.clicks[-1][0] - ex) <= 2.5 and abs(Fx.clicks[-1][1] - ey) <= 2.5, (Fx.clicks, ex, ey)
            pg.click("#vFit"); pg.click("#vIn"); pg.wait_for_timeout(300)
