def banner(t):
    print("\n" + "═" * 70 + "\n  " + t + "\n" + "═" * 70, flush=True)


def secret(name):
    try:
        from kaggle_secrets import UserSecretsClient
        v = UserSecretsClient().get_secret(name)
        return (v or "").strip()
    except Exception:
        return (os.environ.get(name) or "").strip()


def run(cmd, tail=25, env=None, show=None, timeout=None):
    """运行命令,流式打印关键行;失败时抛出带日志尾部的错误。timeout(秒)= 子进程看门狗:超时直接终止并按失败处理(交给 retry 重试)。"""
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
    timer, timed_out = None, []
    if timeout:
        def _kill():
            if p.poll() is None:
                timed_out.append(1)
                try:
                    p.kill()
                except Exception:
                    pass
        timer = threading.Timer(timeout, _kill)
        timer.daemon = True
        timer.start()
    last = deque(maxlen=tail)
    n = 0
    for line in p.stdout:
        line = line.rstrip()
        last.append(line)
        n += 1
        if show and re.search(show, line):
            print("   " + line[:150], flush=True)
        elif n % 15 == 0:
            print(".", end="", flush=True)
    p.wait()
    if timer:
        timer.cancel()
    if p.returncode != 0:
        raise RuntimeError("命令失败%s(%s):\n%s" % ("(超时 %ds 被终止)" % timeout if timed_out else "", " ".join(map(str, cmd[:6])), "\n".join(last)))
    return list(last)


def retry(fn, tries=3, wait=6, what="操作"):
    """网络类操作(pip / 下载模型 / ngrok)的统一重试:指数退避,最后一次失败才抛出。"""
    for i in range(1, tries + 1):
        try:
            return fn()
        except Exception as e:
            if i >= tries:
                raise
            print("  ⚠ %s 失败(第 %d/%d 次): %s → %ds 后重试" % (what, i, tries, str(e).splitlines()[0][:120], wait * i), flush=True)
            time.sleep(wait * i)


def disk_free_gb(path="/kaggle/working"):
    try:
        return shutil.disk_usage(path if os.path.exists(path) else "/").free / 1e9
    except Exception:
        return 99.0


def resource_report():
    """CPU / 内存 / 磁盘一行摘要(心跳用)。psutil 缺失时退回 /proc/meminfo;任何失败只返回问号。"""
    try:
        import psutil
        vm = psutil.virtual_memory()
        cpu = psutil.cpu_percent(interval=None)
        s = "CPU %.0f%% · 内存 %.1f/%.1fGB(%.0f%%)" % (cpu, (vm.total - vm.available) / 1e9, vm.total / 1e9, vm.percent)
        if vm.percent > 92:
            s += " ⚠ 内存紧张(过高会被 Kaggle 杀进程;可减少并发/关闭浏览器功能)"
        return s
    except Exception:
        try:
            mi = {l.split(":")[0]: int(l.split()[1]) for l in open("/proc/meminfo") if ":" in l}
            return "内存可用 %.1f/%.1fGB" % (mi["MemAvailable"] / 1e6, mi["MemTotal"] / 1e6)
        except Exception:
            return "资源信息不可用"


_CURVE = {"shown": False}


def stream(cmd, env=None, cwd=None):
    """运行子进程并原样转发输出;识别训练曲线更新信号并在 Notebook 里刷新图表。可被 Ctrl+C / 停止按钮中断。"""
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env, cwd=cwd, start_new_session=True)
    try:
        for line in p.stdout:
            line = line.rstrip()
            if line.startswith("CURVE_UPDATED "):
                try:
                    from IPython.display import Image, display, update_display
                    img = Image(filename=line.split(" ", 1)[1])
                    if _CURVE["shown"]:
                        update_display(img, display_id="vc_curve")
                    else:
                        display(img, display_id="vc_curve")
                        _CURVE["shown"] = True
                except Exception:
                    pass
                continue
            print(line[:230], flush=True)
        p.wait()
    except KeyboardInterrupt:
        try:
            os.killpg(os.getpgid(p.pid), signal.SIGTERM)
        except Exception:
            pass
        raise
    return p.returncode


