HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, HERE)
import v16  # noqa: E402

SR = 24000


def speech(sec, f0=120.0, amp=0.3, noise_db=-65.0, seed=0, pauses=True):
    """合成浊音 + 句中停顿(只剩底噪),比「连续音」更接近真实录音的 SNR 结构。"""
    rng = np.random.default_rng(seed)
    t = np.arange(int(sec * SR)) / SR
    x = np.zeros_like(t)
    for k in range(1, 15):
        x += np.sin(2 * np.pi * f0 * k * t + k) / k
    x = x / np.abs(x).max() * amp
    if pauses:
        m = np.ones_like(t)
        period = 2.2                                      # 每 2.2 秒一个 0.5 秒停顿
        for s in np.arange(1.7, sec, period):
            m[int(s * SR): int((s + 0.5) * SR)] = 0.0
        x = x * m
    x = x + rng.standard_normal(len(t)) * 10 ** (noise_db / 20)
    return x.astype(np.float32)


def long_audio(sec, seed=0):
    return speech(sec, seed=seed)


# ───────── M1:无时长限制 ─────────
def test_short_audio_is_one_segment():
    x = speech(8.0)
    assert v16.split_long_audio(x, SR) == [(0, len(x))]


def test_long_audio_split_is_gapless_and_in_pauses():
    x = long_audio(95.0)
    segs = v16.split_long_audio(x, SR)
    assert segs[0][0] == 0 and segs[-1][1] == len(x)
    assert all(segs[i][1] == segs[i + 1][0] for i in range(len(segs) - 1)), "片段必须首尾相接(不丢样本、不重叠)"
    L = [(e - s) / SR for s, e in segs]
    assert all(3.0 <= l <= 23.1 for l in L), L
    for s, e in segs[:-1]:                                   # 切点落在静音里
        w = x[max(0, e - 1200): e + 1200]
        assert float(np.sqrt((w ** 2).mean())) < 0.01, "切点不在停顿处"


def test_split_without_pauses_still_bounded():
    x = speech(75.0, pauses=False)
    segs = v16.split_long_audio(x, SR)
    assert all((e - s) / SR <= 23.1 for s, e in segs) and segs[-1][1] == len(x)


def test_two_hour_stream_is_fast_and_bounded():
    x = np.tile(long_audio(60.0), 120)[: 2 * 3600 * SR]
    t0 = time.time()
    segs = v16.split_long_audio(x, SR)
    assert time.time() - t0 < 20.0
    assert segs[-1][1] == len(x) and all((e - s) / SR <= 23.1 for s, e in segs)


