    assert p["mode"] == "incremental" and set(p["new_ids"]) == {"e", "f"} and len(p["replay_ids"]) == 2
    assert set(p["replay_ids"]) <= {"a", "b", "c", "d"} and abs(p["lr"] - 4e-5) < 1e-12 and p["parent"] == "v1"
