        assert refs["composite"]["active"] and len(refs["composite"]["members"]) >= 2 and refs["composite"]["seconds"] <= 20.0, refs["composite"]
        # 停用一条 → 不再出现在成员/训练集中
        off = refs["composite"]["members"][0]
        j = _http(srv, "POST", "/api/libs/%s/refs/%s" % (lid, off), {"enabled": False, "weight": 9})[1]
        row = next(x for x in j["refs"] if x["sample_id"] == off)
        assert row["enabled"] is False and row["weight"] == 3.0 and off not in j["composite"]["members"] and row["trainable"] is False
        # 激活:复合参考被喂给克隆通路
        a = _http(srv, "POST", "/api/libs/%s/activate" % lid, {})[1]
