def speech(sec=6, seed=0, floor=1e-4):
    rng = np.random.default_rng(seed)
    n = int(sec * SR)
    t = np.arange(n) / SR
    f0 = 120 + 20 * np.sin(2 * np.pi * 0.7 * t)
    ph = 2 * np.pi * np.cumsum(f0) / SR
    s = sum(np.sin(k * ph) / k for k in range(1, 12))
    env = np.convolve((np.sin(2 * np.pi * 2.2 * t) > -0.3).astype(float), np.ones(1200) / 1200, "same")
    fr = rng.normal(0, 0.03, n) * (np.sin(2 * np.pi * 1.3 * t + 1) > 0.6) * env
    return (0.18 * s * env + fr + rng.normal(0, floor, n)).astype(np.float32)


