    assert not v17.gate_decide(b, _chal(b))["promote"], "无显著提升保持冠军"
    assert not v17.gate_decide(b, _chal(b, sim=lambda a: a + 0.03, cer=lambda a: a + 0.05))["promote"]
    assert not v17.gate_decide(b, _chal(b, sim=lambda a: a + 0.03, hf_floor_db=lambda a: a + 5))["promote"], "沙沙声变大必须被拒"
