def test_subprocess_engine_protocol():
    w = "import sys,json,base64,numpy as np\nfor l in sys.stdin:\n  y=np.full(480,0.1,np.float32); print(json.dumps({'pcm_b64':base64.b64encode(y.tobytes()).decode(),'sr':24000}),flush=True)\n"
    E = v17.SubprocessEngine([sys.executable, "-c", w]).load()
    try:
        y, sr = E.synthesize("hi", E.make_speaker_state(np.zeros(10), "t"), seed=3)
        assert len(y) == 480 and sr == 24000
    finally:
        E.release()


# ───────── 入库 ─────────
def test_resumable_upload():
    U = I.UploadStore(tempfile.mkdtemp()); data = os.urandom(3_000_000); sha = hashlib.sha256(data).hexdigest()
    uid = U.create("../../x y.wav", size=len(data), sha256=sha)["id"]; cs = 1_000_000
    U.append(uid, 0, data[:cs], hashlib.sha256(data[:cs]).hexdigest())
    try: U.append(uid, 0, data[:cs]); assert False
    except I.IngestError as e: assert e.status == 409 and e.extra["expected"] == cs
    try: U.append(uid, cs, b"x" * cs, "0" * 64); assert False
    except I.IngestError as e: assert e.status == 422
    try: U.finish(uid); assert False
    except I.IngestError as e: assert e.status == 409
    U.append(uid, cs, data[cs:2 * cs]); U.append(uid, 2 * cs, data[2 * cs:])
    r = U.finish(uid); assert r["sha256"] == sha and ".." not in os.path.relpath(r["path"], U.root) and U.finish(uid)["sha256"] == sha
    bad = U.create("b", size=3, sha256="0" * 64)["id"]; U.append(bad, 0, b"abc")
    try: U.finish(bad); assert False
    except I.IngestError as e: assert e.status == 422 and os.path.exists(U._p(bad, ".part"))
    assert U.abort(bad)["kept_in"] == "trash/"
    try: I.UploadStore(U.root, min_free_mb=10 ** 9).create("c"); assert False
    except I.DiskLow as e: assert e.status == 507


def test_recording_crash_recovery_gaps_and_volumes():
    root = tempfile.mkdtemp(); R = I.RecStore(root); sr = 24000
    ch = (0.1 * np.sin(2 * np.pi * 200 * np.arange(sr * 5) / sr)).astype(np.float32)
    R.start("rec_test_01", sr)
    for i in range(20): R.chunk("rec_test_01", i, (ch * (1 + i / 100)).astype(np.float32).tobytes())
    R2 = I.RecStore(root)                                           # 模拟崩溃重启
    assert [s["id"] for s in R2.list_unfinished()] == ["rec_test_01"]
    for i in range(20, 40):
        if i != 30: R2.chunk("rec_test_01", i, (ch * (1 + i / 100)).astype(np.float32).tobytes())
    assert R2.chunk("rec_test_01", 5, (ch * 1.05).astype(np.float32).tobytes())["dup"]
    try: R2.chunk("rec_test_01", 5, b"\x00" * 8); assert False
    except I.IngestError as e: assert e.status == 409
    try: R2.finish("rec_test_01"); assert False
    except I.IngestError as e: assert e.extra["missing"] == [30]
    R2.chunk("rec_test_01", 30, (ch * 1.30).astype(np.float32).tobytes())
    r = R2.finish("rec_test_01"); w = I.WavMap(r["files"][0])
    assert w.n == 40 * len(ch) and np.allclose(w.slice(30 * len(ch), 31 * len(ch)), ch * 1.30)
    old = I.RecStore.MAX_PART_BYTES; I.RecStore.MAX_PART_BYTES = len(ch) * 4 * 7
    try:
        R3 = I.RecStore(tempfile.mkdtemp()); R3.start("rec_vol_01", sr)
        for i in range(20): R3.chunk("rec_vol_01", i, ch.tobytes())
        rv = R3.finish("rec_vol_01"); assert len(rv["files"]) >= 3 and sum(I.WavMap(p).n for p in rv["files"]) == 20 * len(ch)
        R3.start("rec_gap_01", sr)
        for i in (0, 1, 3): R3.chunk("rec_gap_01", i, ch.tobytes())
        assert I.WavMap(R3.finish("rec_gap_01", allow_gaps=True)["files"][0]).n == 4 * len(ch)
    finally:
        I.RecStore.MAX_PART_BYTES = old


def test_stream_split_long_audio_no_lost_samples():
    sr = 16000; n = sr * 1800                                          # 30 分钟(完整的 2 小时用例见开发报告;CI 里缩短)
    p = os.path.join(tempfile.mkdtemp(), "long.wav"); rng = np.random.default_rng(1)
    with open(p, "wb") as f:
        f.write(b"RIFF" + struct.pack("<I", 36 + n * 2) + b"WAVEfmt " + struct.pack("<IHHIIHH", 16, 1, 1, sr, sr * 2, 2, 16) + b"data" + struct.pack("<I", n * 2))
        done = 0
        while done < n:
            L = int(rng.uniform(4, 9) * sr); t = np.arange(L) / sr
            y = 0.25 * np.sin(2 * np.pi * rng.uniform(110, 220) * t) * np.sin(np.pi * t / t[-1]) + rng.normal(0, 3e-4, L)
            y = np.concatenate([y, rng.normal(0, 3e-4, int(rng.uniform(0.5, 1.0) * sr))])[:n - done]
            f.write((np.clip(y, -1, 1) * 32767).astype(np.int16).tobytes()); done += len(y)
    w = I.WavMap(p); prev, cnt, mx = 0, 0, 0
    for a, b in I.stream_split(w, window_s=300):
        assert a == prev, "首尾必须相接"; prev = b; cnt += 1; mx = max(mx, (b - a) / sr)
    assert prev == w.n and cnt > 100 and mx <= 17.5, (prev, w.n, cnt, mx)


def test_switches_off_means_off():
    old = dict(os.environ)
    try:
        os.environ["VC_V17"] = "0"
        assert not any(v17.switches().values())
        os.environ["VC_V17"] = "1"; os.environ["VC_V17_STUDIO"] = "0"
        assert v17.on("DEFECTS") and not v17.on("STUDIO")
    finally:
        os.environ.clear(); os.environ.update(old)


