FILES['tests/e2e_vox.py'] = r'''# -*- coding: utf-8 -*-
"""
端到端(无 GPU):起真实网关 + 双 worker(VoxCPM2 适配器 + 假模型) → 克隆 → 多句朗读,用【虚拟播放器】量化「首声延迟」与「播放-停顿-播放」。
虚拟播放器:已收音频 ≥ 计划起播水位(plan.prebuf_ms)才起播,之后按实时速度消耗;播放头追上已收样本 = 一次欠载(停顿),停顿期间等数据到来再继续。
用法: python tests/e2e_vox.py [--step-ms 60,150,400] [--text "..."]
注意:假模型只验证【调度/规划/链路】;真实 RTF / 音质必须在 Kaggle T4×2 上实测(本脚本在 Kaggle 里同样可跑,但那时 VC_VOX_FAKE 要关)。
"""
import argparse, asyncio, json, os, sys, time
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, "tests"))
os.environ.update(VC_ENGINE="voxcpm2", VC_VOX_FAKE="1")
import numpy as np
import test_gateway as tg
import protocol as pr
SR = 24000


async def play_turn(port, text, sid="e2e"):
    import websockets
    ws = await websockets.connect("ws://127.0.0.1:%d/ws" % port, max_size=None)
    await ws.send(json.dumps({"type": "hello", "sid": sid}))
    t_send = time.time(); await ws.send(json.dumps({"type": "say", "text": text, "opts": {"tts": True}}))
    chk, uid, plan, done, ev, cum, played_ack, t_ack = None, None, None, None, [], 0, 0, 0.0
    t_first = None
    while True:
        try: m = await asyncio.wait_for(ws.recv(), 60)
        except asyncio.TimeoutError: break
        now = time.time()
        if isinstance(m, (bytes, bytearray)):
            if chk is None: continue
            act, f = chk.accept(bytes(m)); assert act == "ok", (act, f)
            cum += f["n"]; ev.append((now, cum)); t_first = t_first or now
        else:
            j = json.loads(m)
            if j["type"] == "turn_start": uid = j["turn"]; chk = pr.FrameChecker(uid, SR)
            elif j["type"] == "plan": plan = j
            elif j["type"] == "turn_done": done = j
        if uid is not None and now - t_ack > 0.25 and t_first:           # 模拟播放进度回执(背压用)
            await ws.send(json.dumps({"type": "ack", "turn": uid, "next_seq": chk.expected if chk else 0, "played": int(min(cum, max(0, (now - t_first)) * SR)), "level_ms": 0})); t_ack = now
        if done is not None and chk and chk.ended: break
    await ws.close()
    return dict(ev=ev, plan=plan, done=done, t_send=t_send, total=cum, chk_ok=bool(chk and chk.ended))


def simulate(ev, prebuf_ms, ended):
    """返回 (起播时刻相对 t0, 欠载次数, 总停顿 s)。"""
    if not ev: return None, 0, 0.0
    need = prebuf_ms / 1000.0 * SR
    start_i = next((i for i, (t, c) in enumerate(ev) if c >= need), len(ev) - 1)
    t_play = ev[start_i][0]; played_at_t = 0.0; under, stall = 0, 0.0
    prev_t, prev_c = ev[start_i]
    pos = 0.0                                              # 已播放秒数
    cur_t = t_play
    for t, c in ev[start_i + 1:]:
        have = prev_c / SR                                 # 此刻已到数据(秒)
        play_until = pos + (t - cur_t)                     # 若不停顿,到 t 时播放头位置
        if play_until > have + 1e-3:                       # 播放头追上数据 → 停顿
            under += 1
            pos = have; stall += play_until - have; cur_t = t
        else:
            pos = play_until; cur_t = t
        prev_c = c
    return t_play, under, stall


def clone_long(srv, wait_s=300):
    import urllib.request
    r = srv.post("/api/voice?consent=1&text=" + urllib.request.quote("今天天气真好我们一起出去走走吧") + "&ext=wav", tg.wav_bytes(tg.speechlike(10.0)))
    assert r.get("ok"), r
    t0 = time.time()
    while time.time() - t0 < wait_s:
        v = srv.state()["voice"]
        if v["state"] == "ready": return v
        if v["state"] == "error": raise RuntimeError(v)
        time.sleep(0.5)
    raise RuntimeError("clone timeout")


LONG = "今天天气真好，我们一起出去走走吧。路上可以看看花，也可以拍几张照片。回来的时候，顺便买一点水果，晚上一起吃。你觉得这样安排怎么样？如果下雨了我们就改去博物馆，那里也很有意思，还有安静的咖啡厅可以休息。"

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--step-ms", default="60,150,400"); ap.add_argument("--text", default=LONG); a = ap.parse_args()
    rows, bad = [], 0
    for sm in [float(x) for x in a.step_ms.split(",")]:
        srv = tg.Server(VC_VOX_FAKE_STEP_MS=sm, VC_VOX_FAKE_PREFILL_MS=250, VC_MOCK_FAIL="")
        try:
            clone_long(srv)
            bk = srv.state()["backend"]["workers"]; eng = [v.get("engine") for v in bk.values()]; assert all(e == "voxcpm2" for e in eng), bk
            r = asyncio.run(play_turn(srv.port, a.text))
            pre = (r["plan"] or {}).get("prebuf_ms", 0)
            t_play, under, stall = simulate(r["ev"], pre, r["chk_ok"])
            ttfa = (r["ev"][0][0] - r["t_send"]) if r["ev"] else None
            st = {k: (list(v.values())[0] if isinstance(v, dict) and v else v) for k, v in {"rtf": {w: x.get("rtf") for w, x in srv.state()["backend"]["workers"].items()}}.items()}
            rows.append(dict(step_ms=sm, engine=eng, chunks_ok=r["chk_ok"], audio_s=round(r["total"] / SR, 1), ttfa_s=round(ttfa, 2) if ttfa else None, plan_prebuf_ms=pre,
                             play_start_after_send_s=round(t_play - r["t_send"], 2) if t_play else None, underruns=under, stall_s=round(stall, 3), plan_mode=(r["plan"] or {}).get("v13_mode"), bridge=(r["plan"] or {}).get("bridge")))
            if not r["chk_ok"] or under: bad += 1
        finally: srv.stop()
    for x in rows: print(json.dumps(x, ensure_ascii=False))
    print("端到端:%d 个场景,%d 个出现欠载/不完整" % (len(rows), bad)); sys.exit(1 if bad else 0)

if __name__ == "__main__": main()
'''

