def lookup_polyphone_phrase(text: str) -> List[Dict[str, object]]:
    t = text or ''
    hits, seen = [], set()
    for _k, meta in POLYPHONE_PHRASE_TABLE.items():
        ph = str(meta.get('phrase', ''))
        if ph and ph in t and ph not in seen:
            seen.add(ph)
            hits.append(meta)
    return hits


def expand_domain_terms(text: str) -> str:
    out = text or ''
    if 'STD-' not in out:
        return out
    for k, meta in TECH_TERM_ORAL_TABLE.items():
        if k in out:
            out = out.replace(k, meta['spoken_zh'])
    return out


def lexicon_stats() -> Dict[str, int]:
    return {
        "polyphone_entries": len(POLYPHONE_PHRASE_TABLE),
        "tech_term_entries": len(TECH_TERM_ORAL_TABLE),
        "total_entries": len(POLYPHONE_PHRASE_TABLE) + len(TECH_TERM_ORAL_TABLE),
    }
