def get_benchmark_slice(category: str = '', limit: int = 50) -> List[Dict[str, object]]:
    rows = [r for r in BENCHMARK_SUITE_V20 if (not category or r['category'] == category)]
    return rows[:max(1, int(limit))]


def benchmark_bank_summary() -> Dict[str, object]:
    cats = {}
    for r in BENCHMARK_SUITE_V20:
        c = str(r['category'])
        cats[c] = cats.get(c, 0) + 1
    return {
        "total_utterances": len(BENCHMARK_SUITE_V20),
        "total_seeded_trials": len(BENCHMARK_SUITE_V20) * 3,
        "categories": cats,
    }
