def prosody_bank_stats():
    return {
        "version": "v21.0",
        "total_rules": len(PROSODY_LEXICON_V21),
        "domains": sorted({r["domain"] for r in PROSODY_LEXICON_V21}),
        "sample_rule": PROSODY_LEXICON_V21[0]["rule_id"],
    }

def lookup_prosody_rule(word_or_id):
    key = str(word_or_id or '').strip()
    for item in PROSODY_LEXICON_V21:
        if item['rule_id'] == key or item['anchor_word'] in key or item['pattern'] == key:
            return item
    return PROSODY_LEXICON_V21[0]
