FILES['v21_api.py'] = r'''# -*- coding: utf-8 -*-
"""
v21_api.py —— v21 旗舰超低首声零断流控制台与 REST 接口 (/v21, /api/v21/*)
"""
from pathlib import Path
from fastapi import Request
from fastapi.responses import HTMLResponse, JSONResponse

import v21_ttfa_accelerator as v21_ttfa
import v21_gapless_scheduler as v21_gs
import v21_prosody_director as v21_pd
import v21_reliability_guard as v21_rg
import v21_phoneme_prosody_bank as v21_ppb
import v21_acoustic_matrix_bank as v21_amb
import v21_stress_corpus_bank as v21_scb


def install(app, ctx=None):
    verifier = v21_rg.EndToEndPlaybackVerifier(sr=24000, num_gpus=2)
    prefetcher = v21_ttfa.WarmupPromptPrefetcher()
    prefetcher.register_worker_cache(0, "/kaggle/working/vc/voice/ref.wav", "ref_continuation", "黄金基线参考声纹")
    prefetcher.register_worker_cache(1, "/kaggle/working/vc/voice/ref.wav", "ref_continuation", "黄金基线参考声纹")

    @app.get("/v21", response_class=HTMLResponse)
    async def v21_page():
        p = Path(__file__).resolve().parent / "v21.html"
        if p.exists():
            return HTMLResponse(p.read_text(encoding="utf-8"))
        return HTMLResponse("<h1>v21 Console Ready</h1>")

    @app.get("/api/v21/status")
    async def v21_status():
        sample_proof = verifier.run_verified_pipeline(
            "欢迎使用星河克隆语音v21旗舰二十万行级终极系统，首声延迟极快，双卡并发前瞻调度彻底消除播放停顿现象！"
        )
        return JSONResponse({
            "ok": True,
            "version": "v21.0-flagship-200k",
            "ttfa_ms": sample_proof["ttfa_ms"],
            "legacy_ttfa_ms": sample_proof["legacy_ttfa_ms"],
            "ttfa_speedup_pct": sample_proof["ttfa_speedup_pct"],
            "zero_stutter_verified": sample_proof["gapless_verified"],
            "underruns": sample_proof["underruns"],
            "rebuffers": sample_proof["rebuffers"],
            "dual_gpu_cache": prefetcher.verify_dual_gpu_consistency(),
            "knowledge_banks": {
                "prosody_lexicon": v21_ppb.prosody_bank_stats(),
                "acoustic_matrix": v21_amb.acoustic_matrix_summary(),
                "stress_corpus": v21_scb.stress_corpus_summary(),
            },
            "export_paths": [
                "/app/kaggle_export/kaggle_voxcpm2_v21_complete.py",
                "/app/kaggle_export/参考代码.py",
                "/app/public/kaggle/kaggle_voxcpm2_v21_complete.py",
                "/app/kaggle_workspace/参考代码.py",
            ],
        })

    @app.post("/api/v21/verify_stream")
    async def v21_verify_stream(req: Request):
        body = await req.json()
        text = str(body.get("text") or "你好，这是一段用于验证快速出首声与连续零卡顿播放的克隆语音测试文本。")
        res = verifier.run_verified_pipeline(text)
        return JSONResponse(res)
'''

