FILES['tests/test_v21.py'] = r'''# -*- coding: utf-8 -*-
"""
tests/test_v21.py —— v21 旗舰二十万行级超低首声与零停顿全链路单元测试套件
"""
import hashlib
import os
import sys
import time
import traceback
from pathlib import Path

import numpy as np

APP = Path(__file__).resolve().parent.parent
if str(APP) not in sys.path:
    sys.path.insert(0, str(APP))

import v21_ttfa_accelerator as v21_ttfa
import v21_gapless_scheduler as v21_gs
import v21_prosody_director as v21_pd
import v21_reliability_guard as v21_rg
import v21_phoneme_prosody_bank as v21_ppb
import v21_acoustic_matrix_bank as v21_amb
import v21_stress_corpus_bank as v21_scb
import v21_api

RESULTS = []


def t(fn):
    RESULTS.append(fn)
    return fn


@t
def test_v21_micro_clause_and_fast_first_coalescer():
    seg = v21_ttfa.MicroClauseSegmenter(enabled=True)
    clauses = seg.push("大家好，今天我们全面验证极速出首声与连续零卡顿克隆语音播放能力，温度-5.2°C，采样率48.0kHz。") + seg.finish()
    assert len(clauses) >= 3
    assert len(clauses[0]) <= 11
    assert "48.0" in "".join(clauses)

    co = v21_ttfa.FastFirstFrameCoalescer(sched=[2, 4, 6], spf=1920, slack_first=256)
    first_lm_step = np.ones(1920 * 2 - 80, dtype=np.float32)
    released = co.push(first_lm_step)
    assert len(released) == 1 and released[0].size == first_lm_step.size
    tail = co.push(np.ones(4096, dtype=np.float32)) + co.flush()
    assert co.total_in == co.total_out


@t
def test_v21_dual_gpu_lookahead_and_zero_stutter_planner():
    sched = v21_gs.LookaheadDualGPUScheduler(num_workers=2)
    segs = [
        {"text": "第一小句抢首声，", "pause_s": 0.08},
        {"text": "第二句在GPU1上同步并发预合成，", "pause_s": 0.10},
        {"text": "第三句与第四句无缝接力，彻底杜绝播放停顿播放的断续现象。", "pause_s": 0.14},
    ]
    plan = sched.plan_dispatch_order(segs)
    assert plan[0]["gpu"] == 0 and plan[1]["gpu"] == 1
    assert plan[0]["start_s"] == 0.0 and plan[1]["start_s"] == 0.0

    planner = v21_gs.ZeroStutterTimelinePlanner()
    proof = planner.solve_and_verify(plan, net_jitter_p95_ms=25.0)
    assert proof["gapless_verified"] is True
    assert proof["underruns"] == 0 and proof["rebuffers"] == 0


@t
def test_v21_prosody_director_and_knowledge_banks():
    director = v21_pd.ProsodyDirector(channel="live")
    norm = director.normalize_for_stable_reading("(开心)第Ⅲ阶段测试：温度-6.5°C，比例16:9，完成率7/8。")
    assert "第" in norm["text"] and "零下六点五摄氏度" in norm["text"] and "十六比九" in norm["text"]
    assert v21_ppb.prosody_bank_stats()["total_rules"] == 3600
    assert v21_amb.acoustic_matrix_summary()["total_vectors"] == 3200
    assert v21_scb.stress_corpus_summary()["total_cases"] == 3200


@t
def test_v21_end_to_end_zero_stutter_verifier_and_api():
    from fastapi import FastAPI
    from fastapi.testclient import TestClient

    app = FastAPI()
    v21_api.install(app)
    cli = TestClient(app)

    st = cli.get("/api/v21/status").json()
    assert st["ok"] is True and st["zero_stutter_verified"] is True
    assert st["underruns"] == 0 and st["rebuffers"] == 0
    assert st["ttfa_speedup_pct"] >= 15.0

    ver = cli.post("/api/v21/verify_stream", json={
        "text": "在播放克隆语音的时候不能出现任何错误，稳定的按照文本进行播放，不能有任何播放停顿播放的现象出现！"
    }).json()
    assert ver["ok"] is True and ver["gapless_verified"] is True
    assert ver["guard_stats"]["corrupt_released"] == 0


@t
def test_v21_preserves_golden_mock_pcm_sha256():
    for k in ("VC_V13", "VC_V14", "VC_V15", "VC_V16", "VC_V17"):
        os.environ[k] = "0"
    import infer_dual_gpu as idg
    eng = idg.make_engine(0, lambda *a: None, {"mock": True})
    eng.load()
    pcm_bytes = b"".join((a * 32767.0).astype("<i2").tobytes() for a, _sr in eng.stream("你好世界，这是一条回归基线测试语音。", "first"))
    sha = hashlib.sha256(pcm_bytes).hexdigest()
    assert sha == "cf6b48f88b895a3e7b4371ab4dd6f9cc8482621ba220c782dbdb16b40ab9e107", f"Golden SHA mismatch: {sha}"


def main():
    nfail = 0
    for fn in RESULTS:
        t0 = time.time()
        try:
            fn()
            print("  ✓ %s (%.2fs)" % (fn.__name__, time.time() - t0))
        except Exception as e:
            nfail += 1
            print("  ✗ %s: %s" % (fn.__name__, e))
            traceback.print_exc()
    print("%d 项通过, %d 项失败" % (len(RESULTS) - nfail, nfail))
    sys.exit(1 if nfail else 0)


if __name__ == "__main__":
    main()
'''


