# ════════════════════════════════════════════════════════════════
#  会话 / 轮次
# ════════════════════════════════════════════════════════════════
class Worker:
    def __init__(self, idx, gpu, proc, q):
        self.idx, self.gpu, self.proc, self.q = idx, gpu, proc, q
        self.status, self.msg = "loading", "启动中…"
        self.voice_vid = None
        self.voice_info = {}
        self.pending = 0
        self.inflight = 0
        self.cur = None          # (turn uid, seg idx)
        self.mem = (0.0, 0.0, 0)
        self.synth_segs = 0

    def ready(self):
        return self.status in ("ready", "voice") and self.proc.is_alive()


class Pool:
    def __init__(self, ctx, gpus, cfg):
        self.ctx = ctx
        self.epoch = ctx.Value("i", 0)
        self.backlog = []          # [(turn uid, seg idx, text, profile)]
        self.res_q = ctx.Queue()
        self.workers = []
        for i, g in enumerate(gpus):
            q = ctx.Queue()
            p = ctx.Process(target=worker_main, args=(i, g, q, self.res_q, self.epoch, cfg), daemon=True, name="tts-gpu%s" % g)
            p.start()
            self.workers.append(Worker(i, g, p, q))

    def usable(self):
        return [w for w in self.workers if w.ready() and w.voice_vid == VOICE["vid"] and VOICE["vid"] > 0]

    def _next_job(self, w):
        self.backlog.sort(key=lambda j: (j[0], j[1]))
        for j in list(self.backlog):
            t = ACTIVE.get(j[0])
            if t is None or t.closed or j[1] >= len(t.segs):
                self.backlog.remove(j)
                continue
            if t.pinned is not None and t.pinned != w.idx:
                continue
            if t.blocked() and not getattr(t.segs[j[1]], "x_tries", 0):      # 背压:浏览器已经领先足够多,先不要继续烧 GPU(v14:跨卡重试的句子是队首,后面的句子已就绪却发不出去,不能再被背压挡住 → 否则死锁)
                continue
            _av = getattr(t.segs[j[1]], "avoid", None)
            if _av is not None and _av == w.idx and any(x_.idx != w.idx for x_ in self.usable()):
                continue                         # v14:这一句刚在这张卡上失败,留给另一张卡
            self.backlog.remove(j)
            return t, j
        return None

    def schedule(self):
        """拉取式调度(work-stealing) + 背压:哪张卡空了就领队首的句子;但某一轮"已发出但尚未播放 + 已就绪未发送"的音频超过窗口时,这一轮暂停派活。"""
        for w in sorted(self.usable(), key=lambda x: x.idx):
            if w.inflight > 0:
                continue
            job = self._next_job(w)
            if job is None:
                continue
            t, (uid, seg_i, clean, prof) = job
            seg = t.segs[seg_i]
            seg.worker, seg.sent_at = w.idx, time.time()
            w.inflight += 1
            w.cur = (uid, seg_i)
            w.pending += len(clean)
            w.synth_segs += 1
            t.gpu_segs[str(w.idx)] = t.gpu_segs.get(str(w.idx), 0) + 1
            seed = seg_seed(VOICE["vid"], seg_i, clean)
            _ex13 = v13_job_extra(t, seg_i, clean, w)
            if getattr(seg, "v14_extra", None):
                _ex13 = dict(_ex13 or {}, **seg.v14_extra)
            w.q.put(("tts", uid, self.epoch.value, seg_i, clean, prof, seed) + ((_ex13,) if _ex13 else ()))

        v13_opener_kick(self)

    def bump(self):
        with self.epoch.get_lock():
            self.epoch.value += 1

    def stop(self):
        for w in self.workers:
            try:
                w.q.put(("quit",))
            except Exception:  # noqa: BLE001
                pass


class Session:
    def __init__(self, sid):
        self.sid = sid
        self.ws = None
        self.q = None
        self.attached = False
        self.sender = None
        self.q_bytes = 0
        self.legacy = False
        self.history = []
        self.task = None
        self.turn = None
        self.turns = OrderedDict()
        self.detached_at = None

    def attach(self, ws):
        self.ws, self.q, self.q_bytes, self.attached, self.detached_at = ws, asyncio.Queue(), 0, True, None
        self.sender = asyncio.get_running_loop().create_task(self._sender(ws, self.q))

    def detach(self):
        self.attached = False
        self.detached_at = time.time()
        if self.sender:
            self.sender.cancel()
        self.sender = None

    async def _sender(self, ws, q):
        try:
            while True:
                m = await q.get()
                if isinstance(m, (bytes, bytearray)):
                    await ws.send_bytes(bytes(m))
                    self.q_bytes -= len(m)
                else:
                    await ws.send_text(m)
        except Exception:  # noqa: BLE001
            pass

    def send(self, obj):
        if self.attached:
            self.q.put_nowait(json.dumps(obj, ensure_ascii=False))

    def send_bin(self, b):
        if self.attached:
            self.q_bytes += len(b)
            self.q.put_nowait(b)


def broadcast(obj):
    for s in list(SESSIONS):
        if not s.legacy and s.attached:
            s.send(obj)


class Seg:
    def __init__(self, idx, text, end_char):
        self.idx, self.text, self.end = idx, text, end_char
        self.out = []
        self.done = False
        self.err = ""
        self.trim = Trimmer()
        self.worker = -1
        self.had_audio = False
        self.stats = {}
        self.sim = None
        self.sim_dur = 0.0
        self.sim_done = False
        self.sent_at = 0.0
        self.emotion = detect_emotion(text)


class Turn:
    def __init__(self, sess, ref, breath, say_only, gpu_policy=None):
        _uid[0] += 1
        self.uid = _uid[0]
        self.sess, self.ref, self.breath, self.say_only = sess, ref, breath, say_only
        self.segs = []
        self.cur = 0
        self.text_done = False
        self.closed = False
        self.pending_pause = 0
        self.t0 = time.time()
        self.first_audio = None
        self.samples = 0                # 已打包进帧的样本数(含插入的停顿)
        self.full_text = ""
        self.gpu_segs = {}
        self.tts = True
        self.warned = False
        self.sim_wait = 0
        self.sim_sent = False
        self.plan = None
        self.window_ms = SEND_AHEAD_MS
        self.seq = 0
        self.log = []                   # 已发出的全部帧,index == seq,用于断线重连后精确续传
        self.played = 0                 # 浏览器回报的已消费样本数
        self.level_ms = None
        self.has_acks = False
        self.done_msg = None
        self.replayed = 0
        self.chunk_log = []             # (seg, gpu, 距轮次开始秒数)
        self.errors = []
        self.lib = dict(VOICE.get("library") or {})      # 任务开始时固定:library_id / 数据集版本 / 参考样本 / 模型哈希 / 采样参数(执行期间切库不影响本任务)
        self.integrity = []
        self.gen_pcm = []
        self.gen_samples = 0
        self.gen_truncated = False
        self.art = None                 # artifacts.TurnRec(第一次真正发出音频时创建)
        self.art_done = False
        self.art_ended = set()
        self.cold = WARM["n"] == 0
        self.llm_t0 = None
        self.llm_chars = 0
        self.policy = gpu_policy or GPU_POLICY
        self.pinned = None
        if self.policy == "pin_turn" and POOL and POOL.workers:
            ok = [w.idx for w in POOL.workers if w.ready()] or [w.idx for w in POOL.workers]
            self.pinned = ok[self.uid % len(ok)]

    # —— 背压 ——
    def played_est(self):
        if self.sess.legacy:                                  # 兼容通道没有 ack:用"还没写出 socket 的字节数"近似
            return max(0, self.samples - self.sess.q_bytes // 2)
        return self.played

    def sent_ahead_ms(self):
        return max(0, self.samples - self.played_est()) * 1000.0 / SR

    def unsent_ms(self):
        n = 0
        for g in self.segs[self.cur:]:
            n += sum(len(a) for a in g.out)
        return n * 1000.0 / SR

    def blocked(self):
        return (self.sent_ahead_ms() + self.unsent_ms()) > self.window_ms

    def llm_cps(self):
        if self.llm_t0 is None or self.llm_chars < 6:
            return None
        return self.llm_chars / max(time.time() - self.llm_t0, 0.2)


# ════════════════════════════════════════════════════════════════
#  实测性能模型(每张 GPU 单独拟合): dt(块) = F×帧数 + D;首块 = PRE + F×帧 + D
# ════════════════════════════════════════════════════════════════
TARGET_RMS = [0.0]
GAIN = {}
RECENT = {}
FRAME_S = 1.0 / 12.5
TEXT_STATS = {"spc": 0.2, "trim": 0.3}                 # 每字音频秒数 / 每句被去掉的首尾静音秒数(两卡共用:只取决于说话人与文本)
WST = {}


def new_stats():
    return {"F": 0.085, "D": 0.03, "PRE": 0.5, "rtf": 1.0, "ttfa": 0.9, "n": 0, "obs": deque(maxlen=90), "gaps": deque(maxlen=400)}


def W(idx):
    return WST.setdefault(idx, new_stats())


def _ema(old, new, a=0.35):
    return old * (1 - a) + new * a


def fit_cost(st):
    obs = st["obs"]
    if len(obs) < 5:
        return
    xs = np.array([o[0] for o in obs], dtype=np.float64)
    ys = np.array([o[1] for o in obs], dtype=np.float64)
    if xs.std() < 0.5:
        D = st["D"]
        F = float(np.median(np.maximum(ys - D, 0.01) / np.maximum(xs, 1)))
    else:
        F = float(((xs - xs.mean()) * (ys - ys.mean())).sum() / ((xs - xs.mean()) ** 2).sum())
        D = float(ys.mean() - F * xs.mean())
    st["F"] = min(0.2, max(0.03, F))
    st["D"] = min(0.25, max(0.0, D))


def ingest_chunks(idx, ch):
    st = W(idx)
    for ci, (dt, ns) in enumerate(ch or []):
        fr = ns / 1920.0
        if ci > 0 and fr >= 1:
            st["obs"].append((fr, float(dt)))
        if ci > 0:
            st["gaps"].append(float(dt))                      # 该 GPU 相邻块的到达间隔(秒)
    if ch:
        fit_cost(st)
        fr0 = ch[0][1] / 1920.0
        st["PRE"] = min(3.0, max(0.1, _ema(st["PRE"], ch[0][0] - fr0 * st["F"] - st["D"])))


def sim_arrivals(turn):
    """模拟 GPU(拉取式调度,每张卡用自己实测的 F/D/PRE)合成已知的所有句子: 返回按【播放顺序】排好的 [(到达时刻 s, 可播放时长 s)]。"""
    segs = turn.segs
    ws = POOL.usable() if POOL else []
    if turn.pinned is not None:
        ws = [w for w in ws if w.idx == turn.pinned] or ws
    ids = [w.idx for w in ws] or [0]
    free = {i: 0.0 for i in ids}
    ev, prev_pause = [], 0.0
    for k, sg in enumerate(segs):
        i = min(ids, key=lambda x: free[x])
        st = W(i)
        F, D, PRE = st["F"], st["D"], st["PRE"]
        if v14_on("TAIL"):                                                # v14 M1:用该卡「整句耗时/预测」的 P95(样本 <30 用保守先验 1.25),而不是均值;下限 1.0
            _u = V14_TAIL.uplift(i, 0.95)
            F, D, PRE = F * _u, D * _u, PRE * _u
        prof = "first" if k == 0 else ("second" if k == 1 else "rest")
        sched = SCHED.get(prof, SCHED["rest"])
        raw = max(0.5, len(sg.text) * TEXT_STATS["spc"]) + TEXT_STATS["trim"]
        nfr = max(2, int(round(raw / FRAME_S)))
        lead, tail = TEXT_STATS["trim"] * 0.5, TEXT_STATS["trim"] * 0.5
        t, done, ci, raw_cum, deliv_prev = free[i] + PRE, 0, 0, 0.0, 0.0
        first = True
        while done < nfr:
            m = min(sched[min(ci, len(sched) - 1)], nfr - done)
            t += m * F + D
            done += m
            ci += 1
            raw_cum += m * FRAME_S
            deliv = max(0.0, raw_cum - lead) - (tail if done >= nfr else 0.0)
            deliv = max(deliv, deliv_prev)
            dur = deliv - deliv_prev
            deliv_prev = deliv
            if dur > 0 and first:
                dur += prev_pause
                first = False
            if dur > 0:
                ev.append((t, dur))
        free[i] = t + 0.02
        prev_pause = pause_ms(sg.end, turn.breath) / 1000.0
    return ev


def plan_prebuf(turn):
    """起播水位规划: 模拟全程每一块"什么时候到、能播多久",得出播放最少要晚开始多久 need,才能保证每一块在被播放到之前已经到达。
    连续优先: ms = need × 安全系数 + 余量,生成速度不足时会多等(上限 PLAN_CAP_MS);低延迟: 系数更小、封顶很低,更容易欠载。"""
    if not turn.segs:
        return {"ms": 0, "need_ms": 0, "reason": "", "extra_wait_ms": 0}
    ev = sim_arrivals(turn)
    if not ev:
        return {"ms": 0, "need_ms": 0, "reason": "", "extra_wait_ms": 0}
    t0, need, played = ev[0][0], 0.0, 0.0
    for arr, dur in ev:
        need = max(need, arr - t0 - played)
        played += dur
    need_ms = need * 1000.0
    if _v13 is not None and _v13.on("PLAN") and LATENCY_MODE == "continuous":
        return v13_plan(turn, need, need_ms)
    ms = need_ms * PLAN_K + (0 if need <= 0 else 60 + 0.08 * need_ms)
    reason = "按实测速度模拟:生成速度足够,无需因生成而额外等待" if need <= 0 else "按实测速度模拟:后续句子会比播放更晚到达,需预留 %d ms" % need_ms
    llm_slow = False
    if not turn.say_only and not turn.text_done:                         # AI 对话:LLM 吐字速度也要算进去
        cps = turn.llm_cps()
        if cps is not None and cps < 1.5 / max(TEXT_STATS["spc"], 0.05):
            llm_slow = True
            ms = max(ms, min(PLAN_CAP_MS, 6000 if LATENCY_MODE == "continuous" else 1500))
            reason += ";LLM 文字到达速度(%.1f 字/秒)慢于朗读速度的 1.5 倍,先囤积音频" % cps
    ms = int(max(0.0, min(PLAN_CAP_MS, ms)))
    return {"ms": ms, "need_ms": int(need_ms), "reason": reason, "extra_wait_ms": int(max(0, ms - PLAN_FLOOR_MS)), "llm_slow": llm_slow,
            "capped": bool(need_ms * PLAN_K > PLAN_CAP_MS)}


def send_plan(turn):
    if turn.closed or turn.first_audio is not None or not turn.segs:
        return
    p = plan_prebuf(turn)
    turn.plan = p
    turn.window_ms = max(SEND_AHEAD_MS, p["ms"] + 8000)
    ws = POOL.usable() if POOL else []
    st = W(ws[0].idx) if ws else W(0)
    turn.sess.send({"type": "plan", "turn": turn.uid, "prebuf_ms": p["ms"], "need_ms": p["need_ms"], "reason": p["reason"], "extra_wait_ms": p["extra_wait_ms"],
                    "capped": p.get("capped", False), "llm_slow": p.get("llm_slow", False), "window_ms": turn.window_ms, "segs": len(turn.segs), "mode": LATENCY_MODE,
                    "rtf": round(st["rtf"], 2), "ttfa": round(st["ttfa"], 2), "floor_ms": PLAN_FLOOR_MS,
                    "v13_mode": p.get("mode"), "bridge": bool(p.get("bridge")), "bridge_ms": p.get("bridge_ms", 0)})
    log.info("[#%d] 播放计划: %d 句 · 起播水位 %dms(need %dms) · %s", turn.uid, len(turn.segs), p["ms"], p["need_ms"], p["reason"])
    if p.get("mode") == "bridge" and turn.first_audio is None:
        ts13 = v13_ts(turn)
        if not ts13.lead_done:
            ts13.lead_done = True
            if v13_emit_bridge(turn, ("think", "ack"), lead=True):
                v13_watch(turn)


def pcts(xs):
    xs = [float(x) for x in xs]
    if not xs:
        return None
    return {"n": len(xs), "p50": round(aq.percentile(xs, 50), 1), "p95": round(aq.percentile(xs, 95), 1), "p99": round(aq.percentile(xs, 99), 1), "max": round(max(xs), 1)}


def voice_public():
    return {"state": VOICE["state"], "mode": VOICE["mode"], "text": VOICE["text"], "text_source": VOICE["text_source"], "text_trusted": VOICE["text_trusted"],
            "vid": VOICE["vid"], "info": VOICE["info"], "err": VOICE["err"], "msg": VOICE["msg"], "qc": VOICE["qc"], "ref_summary": VOICE["ref_summary"], "kind": VOICE["kind"]}


def weights_match():
    fps = [(b.get("weights_params"), b.get("weights_abs_sum")) for b in BACKEND.values() if b.get("weights_abs_sum") is not None]
    if len(fps) < 2:
        return None
    return all(f == fps[0] for f in fps)


def read_train_progress():
    out = {"event": "train_progress", "status": "idle", "epoch": None, "similarity": None}
    try:
        if TRAIN_STATE.exists():
            out.update(json.loads(TRAIN_STATE.read_text(encoding="utf-8")))
        if EVAL_LOG.exists():
            rows = []
            for ln in EVAL_LOG.read_text(encoding="utf-8").splitlines():
                try:
                    rows.append(json.loads(ln))
                except ValueError:
                    pass
            if rows:
                out["evals"] = rows[-30:]
                out["epoch_eval"], out["similarity"] = rows[-1].get("epoch"), rows[-1].get("sim_val_centroid", rows[-1].get("similarity"))
    except Exception:  # noqa: BLE001
        pass
    out["event"] = "train_progress"
    return out


def gpu_table():
    rows = []
    tr = read_train_progress()
    training = tr.get("status") in ("running", "starting")
    tg = {str(g.get("device_index")): g for g in (tr.get("gpus") or [])}
    for idx, r in sorted(GPU_ROWS.items()):
        task = "空闲"
        role = ""
        for w in (POOL.workers if POOL else []):
            if str(w.gpu) == str(idx):
                role = "推理 worker%d" % w.idx
                task = {"loading": "加载模型", "voice": "克隆/识别中", "error": "出错", "ready": "就绪"}.get(w.status, w.status)
                if w.inflight and w.cur:
                    task = "合成 轮次#%s 第%d句" % (w.cur[0], w.cur[1] + 1)
        if training:
            g = tg.get(str(idx))
            role, task = "训练", "训练中" + ((" · rank %s" % g.get("rank")) if g else "")
        rows.append({"index": idx, "name": r["name"], "util": r["util"], "mem_used": round(r["mem_used"], 2), "mem_total": round(r["mem_total"], 2), "role": role, "task": task})
    return rows


def backend_summary():
    s = {"mock": bool(MOCK), "workers": {str(k): v for k, v in BACKEND.items()}, "model": (Path(MODEL).name if os.path.isdir(MODEL) else MODEL),
         "trained": TRAINED, "weights_match": weights_match(), "model_sha256": SEC["model_sha256"], "latency_mode": LATENCY_MODE, "gpu_policy": GPU_POLICY}
    streaming = [b.get("streaming") for b in BACKEND.values() if "streaming" in b]
    s["streaming"] = (all(streaming) if streaming else None)
    s["mode_label"] = ("MOCK(模拟引擎,不代表真实质量)" if MOCK else ("真实 VoxCPM2 · 流式" if s["streaming"] else ("⚠ 官方整句生成(非流式,首声延迟≈整句生成时间)" if s["streaming"] is False else "后端尚未就绪")))
    return s


def state_public():
    ws = []
    for w in POOL.workers if POOL else []:
        ws.append({"idx": w.idx, "gpu": w.gpu, "status": w.status, "msg": w.msg, "voice": (w.voice_vid == VOICE["vid"] and VOICE["vid"] > 0),
                   "mem": [round(w.mem[0], 1), round(w.mem[1], 1)], "util": w.mem[2], "info": w.voice_info, "alive": w.proc.is_alive(), "synth_segs": w.synth_segs,
                   "stats": {"F_ms": round(W(w.idx)["F"] * 1000, 1), "D_ms": round(W(w.idx)["D"] * 1000, 1), "PRE_ms": round(W(w.idx)["PRE"] * 1000), "rtf": round(W(w.idx)["rtf"], 2),
                             "gap_ms": pcts([g * 1000 for g in W(w.idx)["gaps"]])}})
    return {"type": "state", "workers": ws, "voice": voice_public(), "deepseek": bool(DS_KEY or MOCK_LLM), "mock": MOCK, "monitor_only": MONITOR_ONLY,
            "model": (Path(MODEL).name if os.path.isdir(MODEL) else MODEL), "trained": TRAINED, "target": TARGET_RMS[0], "backend": backend_summary(),
            "gpus": gpu_table(), "calibrated": bool(CAL), "sv_model": SV_MODEL, "emotion_pause": EMOTION_PAUSE,
            "perf": {"mode": LATENCY_MODE, "policy": GPU_POLICY, "spc": round(TEXT_STATS["spc"], 3), "send_ahead_ms": SEND_AHEAD_MS}, "train": read_train_progress(),
            "library": VOICE.get("library"), "v13": v13_state(), "v15": v15_state(), "v16": v16_state(), "v17": v17_state()}


# ════════════════════════════════════════════════════════════════
#  输出:按句序打包成协议 v2 帧
# ════════════════════════════════════════════════════════════════
def emit(turn, pcm_bytes, flags=0, seg=0):
    f = pack_frame(turn.uid, turn.seq, SR, pcm_bytes, flags, seg)
    turn.seq += 1
    turn.log.append(f)
    turn.sess.send_bin(f)


def pump(turn):
    """按句子顺序把已就绪的音频推给浏览器。受背压窗口限制:浏览器领先过多时,音频留在队列里不发。"""
    if turn.closed:
        return
    while turn.cur < len(turn.segs):
        seg = turn.segs[turn.cur]
        if seg.out:
            if turn.sent_ahead_ms() >= turn.window_ms:
                return
            flags = F_SEG if not seg.had_audio else 0
            pause_b = b""
            if turn.pending_pause > 0:
                pause_b = v15_pause_bytes(turn, seg, int(SR * turn.pending_pause / 1000))
                turn.pending_pause = 0
                flags |= F_PAUSE
            audio_b = b"".join(a.astype("<i2").tobytes() for a in seg.out)
            seg.out = []
            b = pause_b + audio_b
            turn.samples += len(b) // 2
            seg.emitted = getattr(seg, "emitted", 0) + len(b) // 2
            if V14_REF is not None:
                V14_REF.add(b)
            art_record(turn, seg.idx, pause_b, audio_b)           # 与 emit 完全同一处、同一顺序:整轮 = 实际播放序列,单段 = 只含本段
            if turn.first_audio is None:
                turn.first_audio = time.time() - turn.t0
                WARM["n"] += 1
            seg.had_audio = True
            emit(turn, b, flags, seg.idx)
        if seg.done:
            art_seg_end(turn, seg)
            if seg.had_audio:
                turn.pending_pause = int(pause_ms(seg.end, turn.breath) * (EMO_PAUSE_SCALE.get(seg.emotion, 1.0) if EMOTION_PAUSE else 1.0))
            turn.cur += 1
            continue
        v13_watch(turn)
        return
    if turn.text_done and turn.cur >= len(turn.segs):
        finish_turn(turn)


def art_record(turn, seg_idx, pause_b, audio_b):
    """把【即将 emit 的这一批】按播放顺序交给有界写盘线程;同时维护评估用内存副本(播放顺序,不含停顿)。不做任何磁盘 I/O。"""
    if audio_b:
        if turn.gen_samples < SR * GEN_PCM_CAP_S:
            turn.gen_pcm.append(audio_b)
            turn.gen_samples += len(audio_b) // 2
        else:
            turn.gen_truncated = True
    if ART is None:
        return
    if turn.art is None:
        turn.art = ART.begin(turn.uid, (turn.lib or {}).get("library_id"), {})
        turn.art.sess = turn.sess
        UID_AID[turn.uid] = turn.art.aid
        while len(UID_AID) > 2000:
            UID_AID.pop(next(iter(UID_AID)))
    turn.art.add(seg_idx, pause_b, audio_b)


def art_seg_end(turn, seg):
    if turn.art is None or seg.idx in turn.art_ended:
        return
    turn.art_ended.add(seg.idx)
    turn.art.seg_end(seg.idx, seg.err or "", len(seg.text))


def art_finish(turn, cancelled=False):
    if turn.art is None or turn.art_done:
        return
    turn.art_done = True
    if cancelled:
        for sg in turn.segs[:turn.cur + 1]:
            art_seg_end(turn, sg)
    params = {"temperature": os.environ.get("VC_TEMPERATURE"), "top_p": os.environ.get("VC_TOP_P"), "top_k": os.environ.get("VC_TOP_K"), "repetition_penalty": os.environ.get("VC_REP_PENALTY"),
              "seed": os.environ.get("VC_SEED"), "latency_mode": LATENCY_MODE, "gpu_policy": turn.policy}
    turn.art.finish({"frames": list(turn.log), "integrity": list(turn.integrity), "errors": list(turn.errors), "library": dict(turn.lib or {}), "params": params,
                     "chars": len(turn.full_text), "text": turn.full_text, "cancelled": cancelled, "model_sha256": SEC.get("model_sha256")})


def finish_turn(turn):
    turn.closed = True
    ACTIVE.pop(turn.uid, None)
    if _v13 is not None and LOOP is not None and POOL is not None:
        LOOP.call_later(0.5, POOL.schedule)                 # v13:轮次结束后,空闲卡继续后台合成桥接音库
    emit(turn, b"", F_END, len(turn.segs))
    art_finish(turn)
    v15_forensics_turn(turn)
    v16_forensics_turn(turn)
    v17_forensics_turn(turn)
    if turn.sim_wait > 0:
        RECENT[turn.uid] = turn
    gaps = {}
    for g in sorted(set(x[1] for x in turn.chunk_log)):
        xs, last = [], None
        for sg, gg, t in turn.chunk_log:
            if gg != g:
                continue
            if last is not None and last[0] == sg:
                xs.append((t - last[1]) * 1000)
            last = (sg, t)
        gaps[str(g)] = pcts(xs)
    seg0 = turn.segs[0].stats if turn.segs else {}
    turn.done_msg = {"type": "turn_done", "turn": turn.uid, "audio_s": round(turn.samples / SR, 2), "frames": turn.seq, "samples": turn.samples,
                     "first_ms": int(turn.first_audio * 1000) if turn.first_audio is not None else None, "model_first_ms": int(seg0.get("first", 0) * 1000) if seg0.get("first") else None,
                     "queue_ms": int((turn.segs[0].sent_at - turn.t0) * 1000) if turn.segs and turn.segs[0].sent_at else None, "cold": turn.cold,
                     "gpu_segs": turn.gpu_segs, "segs": len(turn.segs), "chars": len(turn.full_text), "chunk_gap_ms_by_gpu": gaps, "errors": turn.errors, "integrity": turn.integrity,
                     "policy": turn.policy, "pinned": turn.pinned, "plan": turn.plan, "emotions": [g.emotion for g in turn.segs][:40], "replayed_frames": turn.replayed,
                     "seeds": [g.stats.get("seed") for g in turn.segs][:40], "library_id": (turn.lib or {}).get("library_id"),
                     "artifact_id": turn.art.aid if turn.art else None, "synthetic": True, "eval_truncated": turn.gen_truncated, "v13": v13_turn_summary(turn)}
    v16_turn_timing(turn, turn.done_msg.get("first_ms"), turn.done_msg.get("model_first_ms"), turn.done_msg.get("queue_ms"))
    turn.sess.send(turn.done_msg)
    TURN_LOG.append(dict(turn.done_msg, chars=len(turn.full_text), t=time.time()))
    if turn.gen_pcm:
        GEN_AUDIO[turn.uid] = b"".join(turn.gen_pcm)
        GEN_LIB[turn.uid] = (turn.lib or {}).get("library_id")
        while len(GEN_AUDIO) > 3:
            GEN_AUDIO.popitem(last=False)
        if LOOP is not None and VOICE.get("ref_summary") is not None:
            LOOP.create_task(acoustic_job(turn))
    sim_check(turn)


async def acoustic_job(turn):
    try:
        pcm = np.frombuffer(GEN_AUDIO.get(turn.uid, b""), dtype="<i2")
        if pcm.size < SR:
            return
        gen = await LOOP.run_in_executor(None, lambda: aq.acoustic_summary(pcm, SR, turn.full_text, "speech"))
        ref = VOICE["ref_summary"]
        turn.sess.send({"type": "acoustic", "turn": turn.uid, "ref": ref, "gen": gen, "diff": aq.compare_summaries(ref, gen)})
    except Exception as e:  # noqa: BLE001
        log.warning("声学摘要失败: %s", e)


def dispatch(turn, text, final=False):
    _norm = _v13.normalize_text(text) if v13_on("GUARD") else text
    _sp = _v14.spoken(_norm) if v14_on("TEXT") else _norm                # v14 M5:数字/小数/时间/金额/单位口语化(原文 → 口语化 可在诊断里看到)
    if _sp != _norm:
        V14M["spoken_rewrites"].append({"orig": _norm[:80], "spoken": _sp[:80]})
    clean = tts_clean(_sp, final=final)
    if not turn.tts or not has_speech(clean):
        return
    seg = Seg(len(turn.segs), clean, text.strip()[-1:])
    turn.segs.append(seg)
    if not POOL or not POOL.usable():
        seg.done = True
        seg.err = "没有可用的 GPU 进程或声音还没克隆好"
        if not turn.warned:
            turn.warned = True
            turn.sess.send({"type": "warn", "msg": "无法朗读: " + seg.err})
        return
    turn.sim_wait += 1
    prof = "first" if seg.idx == 0 else ("second" if seg.idx == 1 else "rest")
    POOL.backlog.append((turn.uid, seg.idx, clean, prof))
    POOL.schedule()


def _apply_gain(a, g):
    if a.size and abs(g - 1.0) > 0.02:
        a = np.clip(a.astype(np.float32) * g, -32767, 32767).astype("<i2")
    return a


def on_worker_msg(msg):
    k = msg[0]
    if k == "status":
        _, idx, stage, text = msg
        w = POOL.workers[idx]
        w.status, w.msg = stage, text
        broadcast(state_public())
    elif k == "backend":
        _, idx, info = msg
        BACKEND[idx] = info
        broadcast(state_public())
    elif k == "voice_ok":
        _, idx, vid, info = msg
        w = POOL.workers[idx]
        cal = info.pop("ch", None) if isinstance(info, dict) else None
        if vid == VOICE["vid"]:
            w.voice_vid, w.voice_info = vid, info
            VOICE["pending"].discard(idx)
            VOICE["info"][str(idx)] = info
            rs = {int(k_): v.get("rms") for k_, v in VOICE["info"].items() if v.get("rms")}
            if rs:                                              # 两卡有声 RMS 对齐(整卡常数增益,限制在 ±1.5dB 以内;不做逐 chunk 自动增益)
                tgt = float(np.exp(np.mean(np.log(list(rs.values())))))
                TARGET_RMS[0] = round(tgt, 1)
                for i, r in rs.items():
                    GAIN[i] = float(min(1.19, max(0.84, tgt / max(r, 1.0))))
            log.info("[GPU%d] 声音就绪: %s 增益 %.2f", idx, info, GAIN.get(idx, 1.0))
            st = W(idx)
            if info.get("rtf") and info.get("ttfa") and st["n"] == 0:
                st["rtf"], st["ttfa"] = float(info["rtf"]), float(info["ttfa"])
                st["F"] = min(0.2, max(0.03, float(info["rtf"]) * FRAME_S - st["D"] / 5))
                st["PRE"] = max(0.15, float(info["ttfa"]) - 2 * st["F"] - st["D"])
                if cal:
                    st["obs"].clear()
                    ingest_chunks(idx, cal)
            _voice_progress()
            POOL.schedule()
    elif k == "voice_err":
        _, idx, vid, err = msg
        if vid == VOICE["vid"]:
            VOICE["pending"].discard(idx)
            VOICE["err"] = err
            log.error("[GPU%d] 声音设置失败: %s", idx, err)
            _voice_progress()
    elif k == "asr":
        _, rid, text, err = msg
        fut = ASR_WAIT.pop(rid, None)
        if fut and not fut.done():
            fut.set_result((text, err))
    elif k in ("spk_qc", "spk_cmp"):
        _, rid, res, err = msg
        fut = QC_WAIT.pop(rid, None)
        if fut and not fut.done():
            fut.set_result((res, err))
    elif k == "opener":
        v13_on_opener(msg)
    elif k == "v13m":
        v13_on_metrics(msg)
    elif k == "chunk":
        _, tuid, seg_i, data, tsec = msg
        t = ACTIVE.get(tuid)
        if t is None or t.closed or seg_i >= len(t.segs):
            return
        seg = t.segs[seg_i]
        t.chunk_log.append((seg_i, seg.worker, time.time() - t.t0))
        a = v15_post(t, seg, v13_post(t, seg, seg.trim.feed(np.frombuffer(data, dtype="<i2"))))
        if a.size:
            seg.out.append(a)
            pump(t)
    elif k == "sim":
        _, tuid, seg_i, sim, dur = msg[:5]
        info = msg[5] if len(msg) > 5 and isinstance(msg[5], dict) else {"status": "completed" if sim is not None else "not_evaluated", "reason": ""}
        t = ACTIVE.get(tuid) or RECENT.get(tuid)
        if t is None or seg_i >= len(t.segs):
            return                                                    # 迟到/未知任务的结果直接丢弃,不会串到新一轮
        t.segs[seg_i].sim, t.segs[seg_i].sim_dur = sim, float(dur or 0)
        t.segs[seg_i].sim_info = info
        _sim_slot_done(t, seg_i)
    elif k in ("seg_done", "seg_err"):
        if k == "seg_done":
            _, tuid, seg_i, idx, stats = msg
            err = ""
        else:
            _, tuid, seg_i, idx, err = msg
            stats = {}
        w = POOL.workers[idx]
        w.inflight = max(0, w.inflight - 1)
        w.cur = None
        try:
            if stats.get("audio") and stats.get("wall") and not err and not stats.get("salvaged"):
                st = W(idx)
                a_s, first = float(stats["audio"]), float(stats.get("first") or 0)
                seg0 = ACTIVE.get(tuid)
                if a_s > 1.2 and stats["wall"] > first:
                    st["rtf"] = _ema(st["rtf"], (stats["wall"] - first) / max(a_s - 0.3, 0.3))
                    st["n"] += 1
                if first > 0:
                    st["ttfa"] = _ema(st["ttfa"], first)
                ingest_chunks(idx, stats.get("ch"))
                if seg0 is not None and seg_i < len(seg0.segs) and len(seg0.segs[seg_i].text) >= 6 and a_s > 1.0:
                    sg = seg0.segs[seg_i]
                    delivered = (sg.trim.total + sg.trim.carry.size) / SR
                    if delivered > 0.5 and (not v13_on("GUARD") or 0.1 <= delivered / max(len(sg.text), 1) <= 0.36):     # v13:失控/异常样本不污染在线估计
                        TEXT_STATS["spc"] = min(0.5, max(0.08, _ema(TEXT_STATS["spc"], delivered / len(sg.text))))
                        TEXT_STATS["trim"] = min(1.0, max(0.0, _ema(TEXT_STATS["trim"], a_s - delivered)))
        finally:
            POOL.schedule()
        t = ACTIVE.get(tuid)
        if t is None or t.closed or seg_i >= len(t.segs):
            if k == "seg_err":
                t2 = RECENT.get(tuid)
                if t2 is not None:
                    _sim_slot_done(t2, seg_i)
            return
        seg = t.segs[seg_i]
        w.pending = max(0, w.pending - len(seg.text))
        if err and v14_try_xretry(t, seg, idx, err):
            return
        if not err and not stats.get("skipped"):
            v14_record_seg(idx, stats)
            if getattr(seg, "x_tries", 0):
                V14M["xretry_ok"] += 1
            if stats.get("salvaged"):
                V14M["salvaged"] += 1
        a = v15_post(t, seg, v13_post(t, seg, seg.trim.flush(), final=True), final=True)
        if a.size:
            seg.out.append(a)
        if err or stats.get("skipped"):
            _sim_slot_done(t, seg_i)
        seg.done, seg.err, seg.stats = True, err, stats
        if stats.get("qc"):
            for wmsg in stats["qc"].get("warnings", []):
                t.integrity.append("第%d句: %s" % (seg_i + 1, wmsg))
        if err:
            t.errors.append("第%d句: %s" % (seg_i + 1, err))
            t.sess.send({"type": "warn", "msg": "第 %d 句音频被判定为损坏/合成失败(未标记为成功): %s" % (seg_i + 1, err), "integrity": True})
        elif stats.get("audio"):
            log.info("[#%d] 第%d句 GPU%d: %d字 → 音频 %.1fs, 首包 %.2fs, 耗时 %.1fs (RTF %.2f) seed=%s", t.uid, seg_i, idx, len(seg.text),
                     stats["audio"], stats.get("first") or 0, stats.get("wall") or 0, (stats.get("wall") or 0) / max(stats["audio"], 1e-3), stats.get("seed"))
        pump(t)


def turn_sim(turn):
    xs = [(g.sim, g.sim_dur) for g in turn.segs if g.sim is not None and g.sim_dur > 1.2]
    if not xs:
        return None
    return round(sum(a * b for a, b in xs) / sum(b for _, b in xs), 4)


def _sim_slot_done(turn, seg_i):
    g = turn.segs[seg_i]
    if g.sim_done:
        return
    g.sim_done = True
    turn.sim_wait = max(0, turn.sim_wait - 1)
    sim_check(turn)


def sim_check(turn):
    if turn.sim_sent:
        return
    v = turn_sim(turn)
    final = turn.closed and turn.sim_wait == 0
    if v is not None or final:
        infos = [getattr(g, "sim_info", None) for g in turn.segs if getattr(g, "sim_info", None)]
        st = "completed" if v is not None else ("failed" if any(i.get("status") == "failed" for i in infos) else "skipped" if any(i.get("status") == "skipped" for i in infos) else "not_evaluated")
        why = "" if v is not None else (next((i.get("reason") for i in infos if i.get("status") == st and i.get("reason")), "") or "没有可评分的句子(句子太短或评分器未就绪)")
        lib_ = turn.lib or {}
        turn.sess.send({"type": "sim", "turn": turn.uid, "value": v, "final": bool(final), "view": aq.similarity_view(v, SV_MODEL, CAL, "speech"),
                        "per_gpu": _sim_by_gpu(turn), "status": st, "reason": why, "scope": "生成音频 vs 当前参考样本的原始 cosine(不是留出评估)", "model": SV_MODEL,
                        "library_id": lib_.get("library_id"), "sample_id": lib_.get("sample_id"), "dataset_version": lib_.get("dataset_version")})
    if final:
        turn.sim_sent = True
        RECENT.pop(turn.uid, None)


def _sim_by_gpu(turn):
    d = {}
    for g in turn.segs:
        if g.sim is not None and g.sim_dur > 1.2 and g.worker >= 0:
            d.setdefault(str(g.worker), []).append(g.sim)
    return {k: {"mean": round(float(np.mean(v)), 4), "n": len(v)} for k, v in d.items()}


def _voice_progress():
    if not VOICE["pending"]:
        ok = [w for w in POOL.workers if w.voice_vid == VOICE["vid"]]
        VOICE["state"] = "ready" if ok else "error"
        if ok:
            VOICE["err"] = ""
            WARM["n"] = 0
        else:
            VOICE["err"] = VOICE["err"] or "所有 GPU 都没能完成声音设置"
    broadcast(state_public())


def reader_thread(loop):
    while True:
        try:
            msg = POOL.res_q.get()
        except Exception:  # noqa: BLE001
            return
        try:
            loop.call_soon_threadsafe(on_worker_msg, msg)
        except RuntimeError:
            return


# ════════════════════════════════════════════════════════════════
#  参考音频:解码 → 原件另存 → 处理版(去直流/去首尾静音/峰值 -3dBFS/24kHz) → 质检 → 克隆
# ════════════════════════════════════════════════════════════════
def decode_audio(data):
    """尽量接受任意格式: wav(16/24/32bit/float) 用 soundfile;其余交给 soundfile/librosa(ffmpeg)。返回 (float32 mono, sr, 原声道数)"""
    import soundfile as sf
    try:
        a, sr = sf.read(io.BytesIO(data), dtype="float32", always_2d=True)
    except Exception:  # noqa: BLE001
        import tempfile
        import librosa
        with tempfile.NamedTemporaryFile(suffix=".bin", delete=False) as f:
            f.write(data)
            tmp = f.name
        try:
            y, sr = librosa.load(tmp, sr=None, mono=False)
            a = (y[:, None] if y.ndim == 1 else y.T).astype(np.float32)
        finally:
            os.unlink(tmp)
    ch = a.shape[1]
    return a.mean(axis=1).astype(np.float32), int(sr), int(ch)


def resample_to(x, sr, to=SR):
    if sr == to:
        return x
    from math import gcd
    from scipy.signal import resample_poly
    g = gcd(int(sr), int(to))
    return resample_poly(x, to // g, int(sr) // g).astype(np.float32)


def prepare_reference(a, sr):
    """处理版:去直流、去首尾静音、峰值归一到 -3dBFS、重采样到 24kHz。原件另存,绝不覆盖。超过 30 秒时在 20~30 秒内能量最低处截断。"""
    a = a - float(a.mean())
    fr = max(1, sr // 100)
    n = len(a) // fr
    if n > 10:
        e = np.sqrt((a[: n * fr].reshape(n, fr) ** 2).mean(axis=1))
        thr = max(0.004, float(np.percentile(e, 95)) * 0.06)
        idx = np.where(e > thr)[0]
        if idx.size:
            s = max(0, idx[0] - 15) * fr
            t = min(n, idx[-1] + 20) * fr
            a = a[s:t]
    cropped = False
    if len(a) > 30 * sr:
        lo, hi = 20 * sr, 30 * sr
        w = np.convolve(np.abs(a[lo:hi]), np.ones(sr // 50) / (sr // 50), mode="same")
        a = a[: lo + int(np.argmin(w))]
        cropped = True
    pk = float(np.abs(a).max()) if a.size else 0
    if pk > 1e-4:
        a = a * (0.7 / pk)
    return resample_to(a.astype(np.float32), sr), cropped


def write_wav(path, x, sr):
    with wave.open(str(path), "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(sr)
        w.writeframes((np.clip(x, -1, 1) * 32767).astype("<i2").tobytes())


async def ask_worker(kind, path, timeout):
    w0 = next((w for w in POOL.workers if w.ready()), None) if POOL else None
    if w0 is None:
        return None, "没有可用的 GPU 进程"
    rid = "%s%d_%d" % (kind, VOICE["vid"], int(time.time() * 1000) % 100000)
    fut = LOOP.create_future()
    (ASR_WAIT if kind == "asr" else QC_WAIT)[rid] = fut
    w0.q.put((kind, rid, path))
    try:
        return await asyncio.wait_for(fut, timeout)
    except asyncio.TimeoutError:
        return None, "超时"


async def clone_job(vid, path, text, xvec):
    try:
        GAIN.clear()
        TARGET_RMS[0] = 0.0
        if not xvec and not text:
            VOICE["msg"] = "正在自动识别参考音频里说了什么(识别结果需要你核对)…"
            broadcast(state_public())
            text, err = await ask_worker("asr", path, 240)
            text = (text or "").strip()
            if err:
                log.warning("自动识别失败: %s", err)
            if text:
                VOICE["text_source"], VOICE["text_trusted"] = "asr", False
                qc = VOICE.get("qc") or {}
                voiced = qc.get("voiced_s") or 0
                n = len([c for c in text if c.isalnum() or "\u4e00" <= c <= "\u9fff"])
                if voiced > 1 and (n / voiced > 9 or n / voiced < 1.2):
                    qc.setdefault("warnings", []).append("ASR 文本与音频时长明显不匹配(%.1f 字/秒),很可能识别有误,请务必修正后重新克隆" % (n / voiced))
            else:
                xvec = True
                VOICE["text_source"] = "none(x-vector)"
        if vid != VOICE["vid"]:
            return
        VOICE.update(text=text, mode=("xvec" if xvec else "icl"), msg="", info={}, err="")
        (VOICE_DIR / "current.json").write_text(json.dumps({"path": path, "text": text, "xvec": xvec, "orig": VOICE.get("orig"), "text_source": VOICE["text_source"],
                                                              "text_trusted": VOICE["text_trusted"], "qc": VOICE.get("qc")}, ensure_ascii=False), encoding="utf-8")
        ref = VOICE.get("ref_summary") or {}
        if text and ref and not ref.get("error"):                     # 文字确定后再补算参考语音的语速
            try:
                y, _ = decode_audio(Path(path).read_bytes())[:2]
                VOICE["ref_summary"] = await LOOP.run_in_executor(None, lambda: aq.acoustic_summary(y, SR, text, VOICE.get("kind") if VOICE.get("kind") == "singing" else "speech"))
            except Exception as e:  # noqa: BLE001
                log.warning("参考摘要失败: %s", e)
        alive = [w for w in POOL.workers if w.proc.is_alive() and w.status != "error"]
        VOICE["pending"] = set(w.idx for w in alive)
        for w in POOL.workers:
            w.voice_vid = None
        if not alive:
            VOICE.update(state="error", err="没有可用的 GPU 进程")
            broadcast(state_public())
            return
        for w in alive:
            w.q.put(("voice", vid, path, text, xvec))
        broadcast(state_public())
    except Exception as e:  # noqa: BLE001
        log.exception("clone_job")
        VOICE.update(state="error", err="%s: %s" % (type(e).__name__, e))
        broadcast(state_public())


def start_clone(path, text, xvec):
    VOICE["vid"] += 1
    VOICE.update(state="cloning", path=path, text=text, mode="", pending=set(), info={}, err="", msg="准备中…")
    asyncio.get_running_loop().create_task(clone_job(VOICE["vid"], path, text, xvec))


@app.post("/api/voice")
async def api_voice(request: Request):
    if MONITOR_ONLY or not POOL or not POOL.workers:
        return JSONResponse({"ok": False, "error": "语音服务未启动(训练监控模式或没有 GPU)"}, status_code=503)
    q = request.query_params
    if q.get("consent") != "1":
        return JSONResponse({"ok": False, "error": "请先确认:这是你本人的声音,或已获得声音所有者的明确授权"}, status_code=400)
    data = await request.body()
    text = (q.get("text") or "").strip()
    ack = q.get("ack") == "1"
    ext = re.sub(r"[^a-z0-9]", "", (q.get("ext") or "bin").lower())[:5] or "bin"
    try:
        a, sr, ch = await LOOP.run_in_executor(None, decode_audio, data)
    except Exception as e:  # noqa: BLE001
        return JSONResponse({"ok": False, "error": "无法解码音频(%s)。请上传 wav / flac / mp3 / m4a" % str(e)[:120]}, status_code=415)
    proc, cropped = await LOOP.run_in_executor(None, prepare_reference, a, sr)
    rq15 = None
    if _v15 is not None and _v15.on("REFPREP"):
        try:
            proc, rq15 = await LOOP.run_in_executor(None, _v15.prepare_reference_v15, proc, SR)
            V15C.d["ref_quality"] = rq15
        except Exception as e:  # noqa: BLE001
            log.warning("v15 参考语音管线失败(回退 v14 处理版): %s", e)
    qc = await LOOP.run_in_executor(None, lambda: aq.reference_qc(proc, SR, orig_sr=sr, channels=ch, text=text or None))
    if rq15:
        qc["v15_ref_quality"] = rq15
        if rq15["redo"]:
            qc["warnings"].append("v15 参考质量评分 %d/100,建议重录:%s" % (rq15["score"], ";".join(rq15["reasons"]) or "综合评分偏低"))
    if cropped:
        text = ""                                                # 截断后原文字不再严格对应 → 交给 ASR
        qc["warnings"].append("音频超过 30 秒已截断,提供的参考文字不再对应,将重新自动识别(请核对)")
    if qc["kind"] == "clean_speech":
        tmp = VOICE_DIR / ("tmp_qc_%d.wav" % int(time.time() * 1000))
        write_wav(tmp, proc, SR)
        res, err = await ask_worker("spk_qc", str(tmp), 60)
        tmp.unlink(missing_ok=True)
        if res and not err:
            qc["speaker_check"] = res
            if res.get("suspect"):
                qc.update(kind="multi_speaker", kind_zh="疑似多人说话", blocking=True)
                qc["warnings"].append("疑似多人说话(窗口说话人相似度 P10=%s < 0.55,启发式)。克隆需要单一说话人" % res.get("p10"))
            elif res.get("status") in ("failed", "skipped"):
                qc["warnings"].append("多人检测未运行(%s):%s" % (res["status"], str(res.get("reason", ""))[:160]))
        elif err:
            qc["warnings"].append("多人检测未运行:%s" % str(err)[:160])
    if qc["blocking"] and not ack:
        return {"ok": False, "needs_ack": True, "qc": qc}
    try:                                                          # 语音库:新样本【追加】保存到当前库(不覆盖旧样本);容量不足明确拒绝
        lib_sample = await LOOP.run_in_executor(None, lambda: PORTAL.legacy_append(data, ext, proc, sr, ch, qc, text))
    except Exception as e:  # noqa: BLE001
        return JSONResponse({"ok": False, "error": str(e)}, status_code=getattr(e, "code", 500))
    VOICE_DIR.mkdir(parents=True, exist_ok=True)
    n = int(time.time())
    orig_path = VOICE_DIR / ("orig_%d.%s" % (n, ext))
    orig_path.write_bytes(data)                                  # 原件保留
    path = VOICE_DIR / ("ref_%d.wav" % n)
    write_wav(path, proc, SR)                                    # 处理版另存
    kind = "singing" if qc["kind"] == "singing" else "speech"
    ref_summary = await LOOP.run_in_executor(None, lambda: aq.acoustic_summary(proc, SR, text or None, kind))
    VOICE.update(qc=qc, orig=str(orig_path), kind=kind, ack=ack, ref_summary=ref_summary,
                 text_source=("user" if text else ""), text_trusted=bool(text))
    PORTAL.bind_voice(lib_sample)
    start_clone(str(path), text, False)
    return {"ok": True, "vid": VOICE["vid"], "seconds": round(len(proc) / SR, 1), "qc": qc, "library": VOICE.get("library"), "sample_id": lib_sample["sample_id"]}


