@app.get("/api/gen/{uid}.wav")
async def api_gen(uid: int, request: Request):
    """旧接口兼容:优先映射到磁盘上已校验的整轮产物(完整、播放顺序、含停顿);没有归档时退回内存副本(最近 3 轮)。"""
    aid = UID_AID.get(uid)
    if ART is not None and aid:
        try:
            p, fe, m = ART.resolve(aid, cur_lib(), "turn")
            return serve_file(request, p, fe["sha256"], "ai-synthetic_%s_full.wav" % aid)
        except art.ArtifactError:
            pass
    b = GEN_AUDIO.get(uid)
    if not b:
        return Response(status_code=404)
    bio = io.BytesIO()
