@app.get("/api/artifacts/zip")
async def api_art_zip(ids: str = "", check: int = 0):
    if ART is None:
        return JSONResponse({"ok": False, "error": "产物存储尚未就绪"}, status_code=503)
    lib = cur_lib()
    try:
        aids = [x for x in ids.split(",") if x] or [t["artifact_id"] for t in ART.list(lib) if t.get("downloadable")]
        if check:                                                   # 预检:前端先拿到具体原因(没有可下载产物/磁盘不足/ID 错误),再发起真正的下载
            items, need = ART.zip_plan(aids, lib)
            return {"ok": True, "turns": len(items), "estimated_mb": round(need / 1e6, 1)}
        tmp = await asyncio.get_running_loop().run_in_executor(None, lambda: ART.build_zip(aids, lib))
    except art.ArtifactError as e:
        return art_err(e)
    size = tmp.stat().st_size
    return StreamingResponse(art.iter_file(tmp), media_type="application/zip", background=BackgroundTask(lambda: tmp.unlink()),
                             headers={"Content-Length": str(size), "Cache-Control": "private, no-store", "X-Synthetic-Audio": "1",
                                      "Content-Disposition": 'attachment; filename="ai-synthetic_%s.zip"' % time.strftime("%Y%m%d_%H%M%S")})


