def replay(sess, uid, next_seq):
    t = sess.turns.get(uid)
    if t is None:
        EVENTS["resume_fail"] += 1
        sess.send({"type": "resume_fail", "turn": uid})
        return
    frames = t.log[next_seq:]
    sess.send({"type": "resume_ok", "turn": uid, "from": next_seq, "frames": len(frames)})
    for f in frames:
        sess.send_bin(f)
    t.replayed += len(frames)
    EVENTS["reconnect_resumed"] += 1
    if t.done_msg:
        sess.send(t.done_msg)
    pump(t)


def on_ack(sess, m):
    t = sess.turns.get(int(m.get("turn") or 0))
    if t is None:
        return
    t.has_acks = True
    t.played = max(t.played, int(m.get("played") or 0))
    t.level_ms = m.get("level_ms")
    pump(t)
    if POOL:
        POOL.schedule()


@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket):
    await ws.accept()
    sess = None

    def adopt(sid):
        nonlocal sess
        sid = (sid or "")[:48] or uuid.uuid4().hex[:12]
        old = SESS_BY_SID.get(sid)
        resumed = False
        if old is not None:
            if old.attached:
                old.detach()
            sess, resumed = old, True
        else:
            sess = Session(sid)
            SESS_BY_SID[sid] = sess
        SESSIONS.add(sess)
        sess.attach(ws)
        return resumed

    try:
        while True:
            raw = await ws.receive_text()
            try:
                m = json.loads(raw)
            except ValueError:
                continue
            k = m.get("type")
            if sess is None:
                resumed = adopt(m.get("sid") if k == "hello" else None)
                sess.send({"type": "hello_ok", "sid": sess.sid, "resumed": resumed, "server_t": time.time()})
                sess.send(state_public())
                if k == "hello":
                    rs = m.get("resume")
                    if resumed and rs and sess.turns.get(int(rs.get("turn") or 0)) is not None:
                        replay(sess, int(rs["turn"]), int(rs.get("next_seq") or 0))
                    elif resumed and sess.turn is not None and not sess.turn.closed:
                        cancel_turn(sess)                  # 页面重新加载:旧轮次没人接收了
                    continue
            if k == "ping":
                sess.send({"type": "pong", "t": m.get("t")})
            elif k == "ack":
                on_ack(sess, m)
            elif k == "resume":
                replay(sess, int(m.get("turn") or 0), int(m.get("next_seq") or 0))
            elif k == "metrics":
                m.pop("type", None)
                METRICS.append(m)
            elif k == "event":
                n = m.get("name")
                if n == "visibility":
                    EVENTS["visibility"] += 1
                elif n == "ab_vote":
                    EVENTS["ab_votes"].append({"choice": m.get("choice"), "t": time.time()})
            elif k == "chat":
                txt = str(m.get("text") or "").strip()
                if txt:
                    start_turn(sess, txt[:4000], m.get("opts") or {}, m.get("ref"))
            elif k == "say":
                txt = str(m.get("text") or "").strip()
                if txt:
                    o = dict(m.get("opts") or {})
                    o["tts"] = True
                    start_turn(sess, txt[:3000], o, m.get("ref"), say_only=True)
            elif k == "stop":
                cancel_turn(sess)
                sess.send({"type": "stopped"})
            elif k == "reset":
                cancel_turn(sess)
                sess.history = []
                sess.send({"type": "reset_ok"})
    except WebSocketDisconnect:
        pass
    except Exception as e:  # noqa: BLE001
        log.info("ws 结束: %s", e)
    finally:
        if sess is not None:
            if sess.ws is ws:
                sess.detach()          # 保留会话 RESUME_GRACE_S 秒:断线重连后按 next_seq 精确续传;超时由 gpu_loop 回收并取消轮次


@app.websocket("/monitor")
async def monitor_ws(ws: WebSocket):
    await ws.accept()
    MONITORS.add(ws)

    async def rd():
        try:
            while True:
                await ws.receive_text()
        except Exception:  # noqa: BLE001
            pass

    rt = asyncio.get_running_loop().create_task(rd())
    try:
        while not rt.done():
            await ws.send_text(json.dumps({"event": "gpu_status", "gpus": gpu_table(), **{"gpu%d" % w.idx: w.mem[2] for w in (POOL.workers if POOL else [])}}, ensure_ascii=False))
            await ws.send_text(json.dumps(read_train_progress(), ensure_ascii=False))
            await asyncio.sleep(2.0)
    except Exception:  # noqa: BLE001
        pass
    finally:
        rt.cancel()
        MONITORS.discard(ws)


@app.websocket("/stream")
async def stream_ws(ws: WebSocket):
    """兼容简化协议: 发 {"text": "..."} -> 收原始 PCM(int16, 24kHz, 无头) -> 收 {"event":"done","similarity":0.97}"""
    await ws.accept()
    sess = Session("legacy-%s" % uuid.uuid4().hex[:8])
    sess.legacy = True
    sess.attach(ws)
    SESSIONS.add(sess)
    st = {"deadline": None, "done": True, "sim": None}
    out_q = sess.q

    async def finish():
        st["done"] = True
        st["deadline"] = None
        await ws.send_text(json.dumps({"event": "done", "similarity": st["sim"]}))

    async def sender():
        try:
            while True:
                try:
                    m = await asyncio.wait_for(out_q.get(), 0.5)
                except asyncio.TimeoutError:
                    if st["deadline"] and not st["done"] and time.time() > st["deadline"]:
                        await finish()
                    continue
                if isinstance(m, (bytes, bytearray)):
                    sess.q_bytes -= len(m)
                    if len(m) > HEADER_SIZE:
                        await ws.send_bytes(bytes(m[HEADER_SIZE:]))
                    continue
                o = json.loads(m)
                t = o.get("type")
                if t == "sim":
                    st["sim"] = o.get("value") if o.get("value") is not None else st["sim"]
                    if o.get("final") and not st["done"]:
                        await finish()
                elif t == "turn_done":
                    st["deadline"] = time.time() + 3.0
                elif t == "error":
                    st["done"] = True
                    await ws.send_text(json.dumps({"event": "error", "message": o.get("msg", "")}, ensure_ascii=False))
                elif t == "warn":
                    await ws.send_text(json.dumps({"event": "warn", "message": o.get("msg", "")}, ensure_ascii=False))
        except Exception:  # noqa: BLE001
            pass

    # legacy 通道自己消费队列(不走 Session._sender),所以取消默认 sender
    if sess.sender:
        sess.sender.cancel()
    stt = asyncio.get_running_loop().create_task(sender())
    try:
        while True:
            raw = await ws.receive_text()
            try:
                m = json.loads(raw)
            except ValueError:
                m = {"text": raw}
            if m.get("type") == "ping" or m.get("event") == "ping":
                await ws.send_text(json.dumps({"event": "pong"}))
                continue
            if m.get("type") == "stop":
                cancel_turn(sess)
                continue
            txt = str(m.get("text") or "").strip()
            if not txt:
                continue
            if VOICE["state"] != "ready":
                await ws.send_text(json.dumps({"event": "error", "message": "声音还没有克隆好,请先在网页里录入参考语音"}, ensure_ascii=False))
                continue
            st.update(done=False, sim=None, deadline=None)
            start_turn(sess, txt[:3000], {"tts": True}, None, say_only=True)
    except WebSocketDisconnect:
        pass
    except Exception as e:  # noqa: BLE001
        log.info("stream 结束: %s", e)
    finally:
        cancel_turn(sess)
        SESSIONS.discard(sess)
        stt.cancel()


def _hash_model():
    try:
        p = Path(MODEL)
        if not p.is_dir():
            from huggingface_hub import snapshot_download
            p = Path(snapshot_download(MODEL, local_files_only=True))
        f = p / "model.safetensors"
        if not f.exists():
            return
        h = hashlib.sha256()
        with open(f, "rb") as fh:
            for blk in iter(lambda: fh.read(1 << 23), b""):
                h.update(blk)
        SEC["model_sha256"], SEC["model_file"] = h.hexdigest(), str(f)
        log.info("模型文件 sha256 %s (%s)", SEC["model_sha256"][:16], f)
    except Exception as e:  # noqa: BLE001
        log.warning("模型哈希失败: %s", e)


async def gpu_loop():
    while True:
        await asyncio.sleep(2.0)
        for k in [k for k, t in RECENT.items() if time.time() - t.t0 > 120]:
            RECENT.pop(k, None)
        for sid, s in list(SESS_BY_SID.items()):                # 回收超过续传宽限期仍未回来的会话
            if not s.attached and s.detached_at and time.time() - s.detached_at > RESUME_GRACE_S:
                cancel_turn(s)
                SESSIONS.discard(s)
                SESS_BY_SID.pop(sid, None)
        try:
            if not MOCK:
                p = await asyncio.create_subprocess_exec("nvidia-smi", "--query-gpu=index,name,memory.used,memory.total,utilization.gpu", "--format=csv,noheader,nounits",
                                                         stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL)
                out, _ = await asyncio.wait_for(p.communicate(), 5)
                for line in out.decode().strip().splitlines():
                    f = [x.strip() for x in line.split(",")]
                    if len(f) >= 5:
                        GPU_ROWS[int(f[0])] = {"name": f[1], "mem_used": float(f[2]) / 1024, "mem_total": float(f[3]) / 1024, "util": int(float(f[4]))}
            else:
                for i in (0, 1):
                    GPU_ROWS[i] = {"name": "MOCK-GPU%d" % i, "mem_used": 5.5 + i, "mem_total": 15.0, "util": 40 + 20 * i}
            for w in (POOL.workers if POOL else []):
                r = GPU_ROWS.get(int(w.gpu))
                if r:
                    w.mem = (r["mem_used"], r["mem_total"], r["util"])
        except Exception:  # noqa: BLE001
            pass
        if SESSIONS or MONITORS:
            broadcast(state_public())


def restore_voice():
    """重启后自动恢复上一次克隆的声音;或使用脚本里指定的默认参考音频。"""
    try:
        ra = os.environ.get("VC_REF_AUDIO")
        if os.environ.get("VC_REF_FORCE") == "1" and ra and Path(ra).exists():
            log.info("使用微调模型的说话人参考音频(x-vector 模式): %s", ra)
            VOICE.update(text_source="trained_ref", text_trusted=True)
            start_clone(ra, os.environ.get("VC_REF_TEXT", "").strip(), os.environ.get("VC_REF_XVEC") == "1")
            return
        f = VOICE_DIR / "current.json"
        if f.exists():
            j = json.loads(f.read_text(encoding="utf-8"))
            if Path(j["path"]).exists():
                log.info("恢复上一次的克隆声音: %s", j["path"])
                VOICE.update(text_source=j.get("text_source", ""), text_trusted=bool(j.get("text_trusted")), qc=j.get("qc"), orig=j.get("orig"))
                start_clone(j["path"], j.get("text", ""), bool(j.get("xvec")))
                return
        if ra and Path(ra).exists():
            log.info("使用默认参考音频: %s", ra)
            VOICE.update(text_source="user" if os.environ.get("VC_REF_TEXT") else "", text_trusted=bool(os.environ.get("VC_REF_TEXT")))
            start_clone(ra, os.environ.get("VC_REF_TEXT", "").strip(), os.environ.get("VC_REF_XVEC") == "1")
    except Exception as e:  # noqa: BLE001
        log.warning("恢复声音失败: %s", e)


@app.on_event("startup")
async def _startup():
    global LOOP
    LOOP = asyncio.get_running_loop()
    init_artifacts()
    LOOP.create_task(gpu_loop())
    if POOL is not None and POOL.workers:
        threading.Thread(target=reader_thread, args=(LOOP,), daemon=True).start()
        threading.Thread(target=_hash_model, daemon=True).start()
        if os.environ.get("VC_REF_FORCE") == "1" or not await PORTAL.on_startup():
            restore_voice()
    else:
        await PORTAL.on_startup()


