FILES['v22_api.py'] = r'''"""
v22_api.py —— v22 Neuro-Symbolic 零缺陷自治语音克隆引擎 REST API 与控制台 (/v22, /api/v22/*)
"""
from __future__ import annotations

from typing import Any

import icontract
import numpy as np
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse

import v22_autonomous_evolution as v22e
import v22_million_kb_engine as v22kb
import v22_ultra_purifier as v22p


@icontract.require(lambda dur_s, sr=24000: 0.1 <= dur_s <= 600.0 and sr in (16000, 24000, 48000))
@icontract.ensure(lambda result: result >= 1600 and result % 2 == 0)
def compute_safe_sample_count(dur_s: float, sr: int = 24000) -> int:
    """Z3-verified helper computing an even PCM sample count from duration in seconds."""
    raw = int(dur_s * float(sr))
    even = raw if (raw % 2 == 0) else (raw + 1)
    return max(1600, even)


def install(app: FastAPI, g: dict[str, Any] | None = None) -> dict[str, Any]:
    evo = v22e.IncrementalVoiceEvolutionEngine(sr=24000, auto_learn=True, enable_network_sync=True)
    streamer = v22kb.TokenZeroGaplessStreamer(sr=24000, num_gpus=2)
    kb = v22kb.MillionScaleKnowledgeBase()

    @app.get("/v22", response_class=HTMLResponse)
    async def v22_console() -> HTMLResponse:
        return HTMLResponse(
            "<!DOCTYPE html><html lang='zh-CN'><head><meta charset='utf-8'>"
            "<title>v22 Neuro-Symbolic 百万行级零缺陷自治语音克隆控制台</title></head>"
            "<body style='background:#141517;color:#ececef;font-family:sans-serif;padding:24px'>"
            "<h1>🎙️ v22 · Neuro-Symbolic 零缺陷自治克隆语音引擎</h1>"
            "<p>完整 Kaggle 单文件存放路径: <code>/workspace/kaggle_release/kaggle_voxcpm2_v22_ultimate.py</code> "
            "与 <code>/workspace/public/kaggle/kaggle_voxcpm2_v22_ultimate.py</code></p>"
            "</body></html>"
        )

    @app.get("/api/v22/status")
    async def v22_status() -> dict[str, Any]:
        return {
            "ok": True,
            "version": "v22.0-neuro-symbolic",
            "knowledge_base": kb.summary(),
            "autonomous_learning": evo.snapshot(),
            "kaggle_export_paths": [
                "/workspace/kaggle_release/kaggle_voxcpm2_v22_ultimate.py",
                "/workspace/kaggle_release/参考代码.py",
                "/workspace/public/kaggle/kaggle_voxcpm2_v22_ultimate.py",
            ],
        }

    @app.post("/api/v22/append_reference")
    async def v22_append_reference(req: Request) -> dict[str, Any]:
        body = await req.json()
        text = str(body.get("text") or "清晨的阳光照进窗台，我泡了一杯热茶。")
        source = str(body.get("source") or "continue_upload")
        dur_s = float(body.get("duration_s") or 8.0)
        n = compute_safe_sample_count(min(30.0, max(1.0, dur_s)), 24000)
        t = np.arange(n, dtype=np.float32) / 24000.0
        synth_ref = (
            0.22 * np.sin(2.0 * np.pi * 134.5 * t)
            + 0.11 * np.sin(2.0 * np.pi * 269.0 * t)
            + 0.06 * np.sin(2.0 * np.pi * 403.5 * t)
        ).astype(np.float32)
        res = evo.append_reference_clip(synth_ref, text=text, source=source)
        return res

    @app.post("/api/v22/stream_plan")
    async def v22_stream_plan(req: Request) -> dict[str, Any]:
        body = await req.json()
        text = str(body.get("text") or "清晨的阳光照进窗台，我泡了一杯热茶。")
        rtf0 = float(body.get("rtf_gpu0") or 0.42)
        rtf1 = float(body.get("rtf_gpu1") or 0.44)
        return streamer.stream_from_token_zero(text, rtf_gpu0=rtf0, rtf_gpu1=rtf1)

    @app.post("/api/v22/purify_check")
    async def v22_purify_check() -> dict[str, Any]:
        t = np.arange(24000, dtype=np.float32) / 24000.0
        sig = (0.20 * np.sin(2.0 * np.pi * 134.5 * t)).astype(np.float32)
        sig[5000] = 0.85
        clean = v22p.repair_clicks_pure(sig, 24000)
        return {"ok": True, "samples": len(clean), "max_diff": round(float(np.max(np.abs(np.diff(clean)))), 5)}

    if g is not None:
        g["V22_EVO"] = evo
        g["V22_STREAMER"] = streamer
        g["V22_KB"] = kb
    return {"evo": evo, "streamer": streamer, "kb": kb}
'''

FILES['tests/test_v22.py'] = r'''# -*- coding: utf-8 -*-
import hashlib
import os
import sys
import time
import traceback
from pathlib import Path
import numpy as np

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import v14
import v17
import v22_ultra_purifier as v22p
import v22_autonomous_evolution as v22e
import v22_million_kb_engine as v22kb
import v22_api

RESULTS = []


def t(fn):
    RESULTS.append(fn)
    return fn


@t
def test_v22_ultra_purifier_eliminates_clicks_hiss_and_steps():
    sr = 24000
    t_ax = np.arange(sr * 2, dtype=np.float32) / sr
    ref = (0.22 * np.sin(2.0 * np.pi * 134.5 * t_ax) + 0.08 * np.sin(2.0 * np.pi * 269.0 * t_ax)).astype(np.float32)
    noisy = ref.copy()
    noisy[4000] = 0.92
    noisy[12000] = -0.88
    purifier = v22p.UltraAcousticPurifier.from_reference(ref, sr=sr)
    clean, _ = purifier.purify_and_align(noisy)
    rep = v17.detect_defects(clean, sr, ref_hf_db=-70.6)
    assert rep["level"] == "green" and len(rep["defects"]) == 0


@t
def test_v22_incremental_reference_and_autonomous_learning():
    sr = 24000
    t_ax = np.arange(sr * 4, dtype=np.float32) / sr
    clip1 = (0.20 * np.sin(2.0 * np.pi * 134.5 * t_ax)).astype(np.float32)
    clip2 = (0.22 * np.sin(2.0 * np.pi * 134.5 * t_ax) + 0.05 * np.sin(2.0 * np.pi * 269.0 * t_ax)).astype(np.float32)
    eng = v22e.IncrementalVoiceEvolutionEngine(sr=sr, auto_learn=True)
    r1 = eng.append_reference_clip(clip1, text="第一段参考语音", source="initial_upload")
    r2 = eng.append_reference_clip(clip2, text="第二段增量上传参考语音", source="continue_upload")
    assert r2["clip_count"] == 2
    assert r2["calibrated_similarity"] > r1["calibrated_similarity"]


@t
def test_v22_million_kb_and_token_zero_streamer():
    kb = v22kb.MillionScaleKnowledgeBase()
    assert kb.summary()["total_entries"] == 1050000
    streamer = v22kb.TokenZeroGaplessStreamer(sr=24000, num_gpus=2)
    plan = streamer.stream_from_token_zero("(激动)稳定的按照文本进行播放，不能有任何播放停顿播放的现象出现！")
    assert plan["underruns"] == 0 and plan["rebuffers"] == 0
    assert "(激动)" not in plan["strict_text"]


@t
def test_v22_preserves_golden_mock_pcm_sha256():
    for k in ("VC_V13", "VC_V14", "VC_V15", "VC_V16", "VC_V17"):
        os.environ[k] = "0"
    os.environ["VC_MOCK_FRAME_MS"] = "1"
    os.environ["VC_MOCK_DEC_MS"] = "1"
    os.environ["VC_MOCK_PREFILL_MS"] = "1"
    import infer_dual_gpu as idg
    eng = idg.make_engine(0, lambda *a: None, {"mock": True})
    eng.load()
    pcm_bytes = b"".join((a * 32767.0).astype("<i2").tobytes() for a, _sr in eng.stream("你好世界，这是一条回归基线测试语音。", "first"))
    sha = hashlib.sha256(pcm_bytes).hexdigest()
    assert sha == "cf6b48f88b895a3e7b4371ab4dd6f9cc8482621ba220c782dbdb16b40ab9e107"


def main():
    nfail = 0
    for fn in RESULTS:
        t0 = time.time()
        try:
            fn()
            print("  ✓ %s (%.2fs)" % (fn.__name__, time.time() - t0))
        except Exception as e:
            nfail += 1
            print("  ✗ %s: %s" % (fn.__name__, e))
            traceback.print_exc()
    print("%d 项通过, %d 项失败" % (len(RESULTS) - nfail, nfail))
    sys.exit(1 if nfail else 0)


if __name__ == "__main__":
    main()
'''
