_VC_SRV = {"proc": None, "tail": deque(maxlen=60)}


def _stop_server():
    pr = _VC_SRV.get("proc")
    try:
        if pr and pr.poll() is None:
            os.killpg(os.getpgid(pr.pid), 15)
            pr.wait(15)
    except Exception:
        pass


def start_server(env=None):
    p = subprocess.Popen([PY, str(APP / "app.py")], cwd=str(APP), env=env or senv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, start_new_session=True)
    _VC_SRV["proc"] = p

    def pump():
        for line in p.stdout:
            line = line.rstrip()
            _VC_SRV["tail"].append(line)
            if re.search(r"Traceback|Error|error|ERROR|⚠|声音|首包|RTF|就绪|加载|捕获|检测到|模型|对话出错|合成失败|Warning|WARNING|增益|相似", line) and "DeprecationWarning" not in line:
                print("  [server] " + line[:200], flush=True)
    threading.Thread(target=pump, daemon=True).start()
    return p


def health():
    try:
        return json.load(urllib.request.urlopen("http://127.0.0.1:%d/health" % PORT, timeout=4))
    except Exception:
        return None


def open_ngrok(token):
    from pyngrok import conf, ngrok
    cfg = conf.get_default()
    cfg.auth_token = token
    try:                                                    # 二进制校验: 不存在/损坏就重新下载(网络抖动时 pyngrok 可能留下半个文件)
        if not os.path.exists(cfg.ngrok_path) or os.path.getsize(cfg.ngrok_path) < 5_000_000:
            try:
                os.remove(cfg.ngrok_path)
            except OSError:
                pass
            retry(lambda: ngrok.install_ngrok(cfg.ngrok_path), what="下载 ngrok 程序")
    except Exception as e:
        print("  ⚠ ngrok 程序校验跳过: %s" % e)

    def _open():
        for t in ngrok.get_tunnels():
            try:
                ngrok.disconnect(t.public_url)
            except Exception:
                pass
        return ngrok.connect(PORT, "http").public_url.replace("http://", "https://")
    return retry(_open, tries=3, wait=5, what="建立 ngrok 隧道")



